/* Contenido de charlas (prosip): más información y preguntas más exigentes. Lo aplica mejoras_comunes.js (sección 23). */
window.__mjContenidoAplicar && window.__mjContenidoAplicar({"grupo":"pro","temas":[{"id":"autocuidado","sec":"todos","title":"Actos inseguros, condiciones inseguras y autocuidado","thumb":"auto_cadena","learn":[{"s":"auto_acto","t":"¿Qué es un acto inseguro?","x":"Es una <b>acción u omisión de la persona</b> que se aparta de la forma segura de trabajar. Ejemplos en {EMP}:<ul><li>Retirar o levantar el resguardo de la sierra.</li><li>Cortar sin lentes ni protector auditivo.</li><li>Pasar bajo una carga levantada por la grúa horquilla.</li><li>Subirse a las horquillas, a un pallet o a una ruma de paneles.</li></ul>También es acto inseguro <b>no hacer</b> algo, como no avisar. La forma segura en la sierra: <b>resguardo puesto, empujador y EPP</b>."},{"s":"auto_cond","t":"¿Qué es una condición insegura?","x":"Es una situación del <b>lugar, la máquina, la herramienta o el material</b> que puede causar un accidente, aunque en ese momento nadie haga nada mal. Ejemplos:<ul><li>Adhesivo o aceite derramado en el pasillo.</li><li>Cable eléctrico dañado o cruzando el paso.</li><li>Pallet roto o ruma de paneles inclinada.</li><li>Extintor tapado por cajas o paneles.</li><li>Resguardo suelto o luz quemada.</li></ul>La condición insegura se <b>señaliza, se reporta y se corrige</b>."},{"s":"auto_cadena","t":"La mayoría de los accidentes empieza con una acción","x":"<b>La mayoría de los accidentes se relacionan con una acción insegura</b>: apurarse, saltarse un paso, no usar el EPP. A eso suele sumarse una condición insegura. Es como una fila de fichas de dominó: el apuro lleva a trabajar sin EPP, eso se junta con un derrame y termina en accidente. <b>Basta sacar una ficha para cortar la cadena</b>, y la ficha que más depende de ti es tu propia decisión.","k":"Corta la cadena: tu decisión segura es la ficha que tú controlas."},{"s":"auto_porque","t":"¿Por qué cometemos actos inseguros?","x":"<ul><li><b>Apuro:</b> “hay que sacar el camión”.</li><li><b>Exceso de confianza:</b> “llevo años en la sierra”.</li><li><b>Costumbre:</b> el riesgo se vuelve invisible.</li><li><b>Cansancio y sueño:</b> bajan la atención y los reflejos; si llegas así, avisa antes de operar una máquina.</li><li><b>Alcohol, drogas o remedios que dan sueño:</b> nunca se trabaja bajo sus efectos.</li><li><b>“Siempre se ha hecho así”:</b> que nunca haya pasado nada no significa que sea seguro.</li></ul>"},{"s":"auto_ppa","t":"Para, piensa, actúa","x":"Antes de cada tarea, sobre todo si es <b>nueva, no rutinaria o si algo cambió</b> (otra medida de panel, otra máquina, un compañero nuevo):<ul><li><b>Para:</b> detente unos segundos.</li><li><b>Piensa:</b> ¿qué puede salir mal? ¿Tengo el EPP, la herramienta y la instrucción correcta?</li><li><b>Actúa:</b> hazlo de forma segura. Si no sabes cómo, <b>pregunta antes</b> a tu jefatura.</li></ul>Unos segundos para pensar pueden evitar una lesión."},{"s":"auto_companero","t":"Me cuido y cuido a mi compañero","x":"Si ves a un compañero a punto de hacer algo riesgoso, <b>avísale de inmediato y con respeto</b>: “Espera, ponte los lentes”. Si no te hace caso y el riesgo sigue, <b>avisa a la jefatura</b>: no es acusar, es cuidarse entre todos. Si te avisan a ti, <b>agradece y corrige</b> de inmediato: te pueden estar salvando un ojo o una mano. A los trabajadores nuevos, enséñales siempre el camino seguro."},{"s":"auto_reporte","t":"Reporta las condiciones inseguras y los casi accidentes","x":"Si ves un derrame, un cable dañado o una protección rota, o tienes un <b>casi accidente</b> (un resbalón sin caída, algo que cayó cerca), <b>avisa a tu jefatura o al Delegado de SST</b>. Si puedes hacerlo sin riesgo, actúa de inmediato: pon un cono junto al derrame, aparta el pallet roto. Lo que no puedas corregir, <b>señalízalo y avisa</b>. Callar deja la trampa armada para el próximo que pase."},{"s":"auto_184","t":"Derecho a interrumpir ante riesgo grave","x":"Si hay un <b>riesgo grave e inminente</b> para tu vida o tu salud, tienes derecho a <b>interrumpir tus labores</b> y, si es necesario, abandonar el lugar, avisando a tu jefatura lo antes posible (Código del Trabajo, art. 184 bis). Ejemplos: un rack que se dobla, una ruma de paneles que se viene abajo, humo o fuego en la zona de encolado. <b>Ejercer este derecho no puede perjudicarte</b> ni ser motivo de sanción.","k":"Ante riesgo grave e inminente: detente, aléjate y avisa."},{"s":"auto_ri","t":"Tus obligaciones: Reglamento Interno y EPP","x":"También tienes deberes:<ul><li>Cumplir el <b>Reglamento Interno</b> de Orden, Higiene y Seguridad (Ley 16.744, art. 67).</li><li>Usar y cuidar el <b>EPP</b> que la empresa entrega sin costo.</li><li>Seguir los procedimientos de trabajo y no operar máquinas sin estar autorizado.</li><li>Asistir a las capacitaciones.</li></ul>Si un accidente se debe a <b>negligencia inexcusable</b> del trabajador, la ley permite multarlo (Ley 16.744, art. 70)."},{"s":"auto_conse","t":"Autocuidado: piensa en quién te espera","x":"Un accidente no solo te afecta a ti:<ul><li><b>Tú:</b> dolor, secuelas, meses sin trabajar ni hacer lo que te gusta.</li><li><b>Tu familia:</b> preocupación, cuidados y cambios en la casa.</li><li><b>Tu equipo:</b> un compañero menos, el susto y más carga de trabajo.</li></ul>El seguro cubre la atención, pero <b>un dedo o un ojo no se reponen</b>. Ningún apuro vale una lesión: decide seguro antes, no después."}],"quiz":[{"s":"auto_acto","v":[{"q":"Un operador levanta el resguardo de la sierra para ver mejor la línea de corte. Eso es:","o":["Un acto inseguro","Una condición insegura","Un control de ingeniería","Un riesgo aceptable si es por poco rato"],"w":"Es una acción de la persona que se aparta de la forma segura de trabajar."},{"q":"¿Cuál de estas situaciones en la sierra es un acto inseguro?","o":["Cortar sin lentes de seguridad","Un disco con un diente quebrado","Un resguardo suelto por un perno roto","Una luz quemada sobre la sierra"],"w":"Cortar sin lentes es una decisión de la persona; las otras son condiciones del equipo o del lugar."},{"q":"Retirar el resguardo de la sierra “solo por un corte” sigue siendo un acto inseguro.","vf":true,"w":"Verdadero. Da lo mismo cuánto dure: es una acción que se aparta de la forma segura."}]},{"s":"auto_cond","v":[{"q":"Un extintor tapado por cajas es:","o":["Una condición insegura","Un acto inseguro","Un control administrativo","Algo aceptable si las cajas son livianas"],"w":"Es un peligro que está en el lugar: se despeja y se reporta."},{"q":"Encuentras adhesivo derramado en el pasillo y nadie sabe quién fue. ¿Qué es?","o":["Una condición insegura que se señaliza y se reporta","Un acto inseguro del último que pasó","Un riesgo menor que no necesita aviso a nadie","Un problema que solo resuelve el aseo"],"w":"El derrame es una condición insegura del lugar, sin importar quién lo causó."},{"q":"¿Qué tienen en común un cable pelado, un pallet roto y una luz quemada?","o":["Son condiciones inseguras del lugar o del equipo","Son actos inseguros de quien los usa","Son peligros que solo controla el EPP","Son fallas que no requieren aviso"],"w":"Son situaciones del lugar, la máquina o el material que pueden causar un accidente."}]},{"s":"auto_cadena","v":[{"q":"La mayoría de los accidentes se relacionan con:","o":["Una acción insegura, como apurarse o no usar el EPP","Fallas de las máquinas que nadie puede prever","La mala suerte de estar en el lugar equivocado","El clima y la iluminación de la planta"],"w":"Por eso nuestras decisiones son clave para evitarlos."},{"q":"Según el ejemplo del dominó, ¿cómo se evita el accidente?","o":["Sacando una ficha de la cadena, por ejemplo, usando el EPP","Esperando que la jefatura corrija todas las condiciones","Trabajando más rápido para estar menos tiempo expuesto","Revisando solo la última ficha, la del accidente"],"w":"Basta cortar un eslabón para que la cadena no llegue al accidente."},{"q":"¿Cuál es la ficha de la cadena que más depende de ti?","o":["Tu propia decisión de trabajar seguro","El estado del piso de la planta","La calidad de las máquinas","La cantidad de pedidos del día"],"w":"Tu decisión es la ficha que tú controlas directamente."}]},{"s":"auto_porque","v":[{"q":"Si una tarea “siempre se ha hecho así” y nunca ha pasado nada, entonces es segura.","vf":false,"w":"Falso. Que no haya pasado nada todavía no elimina el riesgo."},{"q":"Dormiste mal y sientes mucho sueño antes de operar la sierra. ¿Qué haces?","o":["Aviso a mi jefatura antes de empezar","Opero igual, pero más despacio","Tomo un café y opero normal","No digo nada para no perder el turno"],"w":"El cansancio baja la atención y los reflejos: se avisa antes de operar una máquina."},{"q":"Un compañero con años en la planta dice: “yo corto sin lentes, nunca me ha pasado nada”. ¿Qué lo lleva a ese acto inseguro?","o":["El exceso de confianza","El cansancio","La falta de herramientas","El apuro por sacar un camión"],"w":"La experiencia no protege: la confianza excesiva hace que se salten pasos."}]},{"s":"auto_ppa","v":[{"q":"¿Qué significa “Para, piensa, actúa”?","o":["Detenerse, evaluar qué puede fallar y hacerlo de forma segura","Parar la máquina cada hora, pensar en la meta y seguir","Esperar que el supervisor revise y después actuar","Pensar mientras se trabaja para no perder tiempo"],"w":"Unos segundos para pensar antes de actuar evitan lesiones."},{"q":"Te piden cortar una medida de panel que nunca has hecho. ¿Qué corresponde?","o":["Detenerme, revisar el riesgo y preguntar a mi jefatura si tengo dudas","Hacerlo igual que los cortes de siempre para no atrasar el pedido","Pedirle a un compañero que lo haga sin decir nada","Probar directo en la sierra y corregir sobre la marcha"],"w":"Una tarea nueva o un cambio es justo cuando más se aplica Para, piensa, actúa."},{"q":"¿Cuándo es más importante aplicar “Para, piensa, actúa”?","o":["Cuando la tarea es nueva o algo cambió","Solo cuando ya ocurrió un accidente","Solo al final del turno, por el cansancio","Solo si el supervisor está presente"],"w":"Los cambios y lo no rutinario traen riesgos que no conoces."}]},{"s":"auto_ok","v":[{"q":"¿Qué hace un trabajador que corta de forma segura en la sierra?","o":["Usa el resguardo, el empujador y su EPP","Retira el resguardo para ver mejor la línea","Empuja el panel con la mano hasta el disco","Usa lentes solo en los cortes largos"],"w":"Resguardo, empujador y EPP: varias decisiones seguras juntas."},{"q":"Para un corte angosto en la sierra, la forma segura es:","o":["Usar el empujador con el resguardo puesto","Sacar el resguardo porque la pieza no cabe","Acercar los dedos lento y con cuidado","Pedir a un compañero que sujete el retazo"],"w":"El empujador mantiene tus manos lejos del disco."},{"q":"Si el corte es corto, se puede empujar la pieza con la mano en vez de usar el empujador.","vf":false,"w":"Falso. Justo en las piezas cortas la mano queda más cerca del disco."}]},{"s":"auto_reporte","v":[{"q":"Ves aceite derramado en el pasillo. ¿Qué haces?","o":["Lo señalizo si puedo y aviso a mi jefatura o al Delegado de SST","Paso por el lado con cuidado y sigo trabajando normalmente","Aviso al final del turno para no interrumpir","Le tiro retazos de OSB encima para no pisarlo"],"w":"Reportar y señalizar las condiciones inseguras es parte del autocuidado."},{"q":"Un compañero resbaló en el aceite del pasillo, pero no cayó. ¿Qué haces?","o":["Lo reporto como casi accidente y señalizo el aceite","Nada, porque no se lesionó","Lo comento solo con mis compañeros del turno","Lo informo si vuelve a pasar otra vez"],"w":"El casi accidente avisa que la causa sigue ahí."},{"q":"Ves aceite en el pasillo y no tienes con qué limpiarlo. ¿Qué corresponde?","o":["Poner un cono o señal y avisar a la jefatura","Seguir trabajando y avisar al final del turno","Tapar el aceite con cartón y seguir","Esperar a que otro lo vea"],"w":"Lo que no puedes corregir se señaliza y se avisa de inmediato."}]},{"s":"auto_184","v":[{"q":"Un rack con carga empieza a doblarse. ¿Qué derecho tienes?","o":["Interrumpir la labor, alejarme y avisar a mi jefatura","Ninguno: debo terminar la tarea asignada","Detenerme solo si el supervisor lo autoriza","Detenerme, pero me descuentan el tiempo"],"w":"Ante riesgo grave e inminente puedes interrumpir tus labores (Código del Trabajo, art. 184 bis)."},{"q":"¿Qué norma te da derecho a interrumpir tu trabajo ante un riesgo grave e inminente?","o":["El art. 184 bis del Código del Trabajo","El art. 53 del DS 594","La Ley 20.949 de carga manual","La Ley 20.580 de alcohol"],"w":"El art. 184 bis permite detenerse y alejarse, avisando a la jefatura."},{"q":"Si interrumpes tu trabajo por un riesgo grave e inminente, la empresa puede sancionarte.","vf":false,"w":"Falso. Ejercer este derecho no puede perjudicarte."}]},{"s":"auto_ri","v":[{"q":"Usar el EPP y cumplir el Reglamento Interno es obligación del trabajador.","vf":true,"w":"Verdadero. Son parte de tus deberes de seguridad."},{"q":"¿Qué documento reúne las obligaciones y prohibiciones de seguridad que debes cumplir en {EMP}?","o":["El Reglamento Interno de Orden, Higiene y Seguridad","La Hoja de Datos de Seguridad de cada producto","La matriz de riesgos de cada máquina","El manual del fabricante de la sierra"],"w":"El Reglamento Interno es obligatorio según la Ley 16.744, art. 67."},{"q":"Según la Ley 16.744, ¿qué puede pasar si un accidente se debe a negligencia inexcusable del trabajador?","o":["Puede ser multado","Pierde toda atención médica","Debe pagar la reparación de la máquina","Nada, el seguro lo cubre todo sin consecuencias"],"w":"El art. 70 permite multar al trabajador en ese caso."}]},{"s":"auto_companero","v":[{"q":"Un compañero va a cortar sin lentes. ¿Qué haces?","o":["Le aviso de inmediato y con respeto que se los ponga","Espero que termine y se lo comento después","Lo dejo: cada uno se cuida solo","Lo anoto para contárselo al supervisor a fin de mes"],"w":"Avisar a tiempo es cuidar, no acusar."},{"q":"Le avisaste a un compañero que se ponga los lentes y sigue cortando sin ellos. ¿Qué haces?","o":["Aviso a la jefatura para que se corrija","No insisto para no tener problemas","Lo dejo, porque ya le avisé una vez","Espero a fin de mes para comentarlo"],"w":"Si el riesgo sigue, se informa a la jefatura."},{"q":"Un compañero te advierte que te pongas los lentes. ¿Cuál es la actitud correcta?","o":["Agradecer y ponérmelos de inmediato","Explicarle que llevo años sin accidentes","Ponérmelos solo mientras él mira","Decirle que se preocupe de lo suyo"],"w":"Quien te avisa te puede estar salvando un ojo."}]}]},{"id":"peligros","sec":"todos","title":"Peligros y riesgos: identificación y control (MIPER)","thumb":"pyramid","learn":[{"s":"peligros_vs","t":"Peligro y riesgo no son lo mismo","x":"<b>Peligro</b> es la fuente que puede causar daño: la sierra girando, una carga suspendida, el adhesivo, el ruido de la rebajadora. <b>Riesgo</b> es la posibilidad de que ese peligro te dañe y qué tan grave sería. Ejemplo: la sierra es el peligro; cortarte un dedo es el riesgo. Con resguardo, empujador y lentes <b>el peligro sigue ahí, pero el riesgo baja</b>."},{"s":"peligros_planta","t":"Los peligros de nuestra planta","x":"<ul><li><b>Sierras y rebajadora:</b> cortes, amputaciones y proyección de astillas.</li><li><b>Prensas:</b> atrapamiento y aplastamiento.</li><li><b>Grúa horquilla:</b> atropello, aplastamiento y caída de carga.</li><li><b>Paneles y rumas:</b> sobreesfuerzo y caída de paneles.</li><li><b>Adhesivos:</b> contacto con la piel e inhalación.</li><li><b>Ruido y polvo de madera.</b></li><li><b>EPS y OSB:</b> incendio.</li><li><b>Restos en el piso:</b> tropiezos y caídas.</li></ul>"},{"s":"peligros_miper","t":"La matriz MIPER","x":"La <b>Matriz de Identificación de Peligros y Evaluación de Riesgos (MIPER)</b> ordena cada tarea con sus peligros, sus riesgos y las medidas de control. Ejemplo: tarea corte, peligro sierra, riesgo corte, control resguardo. El <b>DS 44</b> obliga a la empresa a identificar los peligros y evaluar los riesgos de cada puesto. La matriz se revisa <b>cuando algo cambia</b>: una máquina nueva, un proceso nuevo o después de un accidente."},{"s":"peligros_eval","t":"¿Cómo se evalúa un riesgo?","x":"Se hacen dos preguntas: <b>¿qué tan seguido puede pasar?</b> (probabilidad) y <b>¿qué tan grave sería?</b> (consecuencia). Juntas dan el nivel de riesgo: bajo, medio o alto. Un corte en la sierra quizás no es frecuente, pero puede costar un dedo: es un <b>riesgo alto</b> y se controla primero. Un tropiezo con un retazo es más frecuente, pero suele ser menos grave. <b>Los riesgos altos se atienden antes.</b>"},{"s":"peligros_jerarquia","t":"Jerarquía de controles","x":"De más a menos efectivo:<ul><li><b>Eliminar</b> el peligro.</li><li><b>Sustituir</b> por algo menos peligroso, como un adhesivo menos tóxico.</li><li><b>Ingeniería:</b> resguardos, aspiración, barreras.</li><li><b>Administrativos:</b> procedimientos, señalización, capacitación.</li><li><b>EPP:</b> la última barrera.</li></ul>Primero se busca controlar el peligro en su origen; el EPP te protege solo de lo que queda.","k":"Lo mejor es eliminar el peligro; el EPP es la última barrera."},{"s":"peligros_sierra","t":"Ejemplo: la sierra","x":"Un mismo peligro necesita <b>varias capas</b> de control: el <b>resguardo</b> del disco (ingeniería), el <b>empujador</b> y el procedimiento de trabajo seguro o PTS (administrativo), y los <b>lentes y el protector auditivo</b> (EPP). Cada capa tapa los huecos de las otras. Si alguien saca el resguardo, el empujador y los lentes quedan solos y el riesgo <b>sube de inmediato</b>.","k":"Nunca retires una protección: si falta una capa, el riesgo sube."},{"s":"peligros_irl","t":"Tu derecho a saber (IRL)","x":"El <b>DS 44</b> obliga a la empresa a <b>informarte los riesgos</b> de tu trabajo, las medidas preventivas y los métodos de trabajo correctos: es la Información de Riesgos Laborales (IRL). Se entrega <b>al ingresar</b> y otra vez si <b>cambias de puesto</b> o llega una máquina o un producto nuevo. Si algo no te queda claro, pregunta: <b>¿qué riesgos tiene y cómo me protejo?</b>"},{"s":"peligros_reporta","t":"Reporta las condiciones inseguras","x":"Resguardo suelto, cable pelado, pallet roto, derrame de adhesivo, luz quemada: <b>avísalo a tu jefatura o al Delegado de SST</b>. Si puedes corregirlo sin riesgo, como recoger un retazo, hazlo de inmediato. Si no, <b>no uses el equipo, advierte a los demás</b>, señaliza si es posible y avisa. Nunca pongas carga sobre un pallet roto ni uses una máquina con la protección dañada."},{"s":"peligros_auto","t":"Autocuidado: acción insegura vs condición insegura","x":"La <b>condición insegura</b> es el peligro que está en el lugar: un resguardo roto. La <b>acción insegura</b> es lo que hacemos: sacar el resguardo para cortar más rápido, o ver el problema y decir “no es mío”. La mayoría de los accidentes se relacionan con una acción insegura. La decisión segura: <b>detenerte, no usar el equipo y avisar</b>, aunque no sea tu zona."}],"quiz":[{"s":"peligros_vs","v":[{"q":"En la zona de corte, ¿cuál de estos es un peligro?","o":["El disco de la sierra girando","La posibilidad de cortarse un dedo","El resguardo de la sierra","El procedimiento de corte"],"w":"El peligro es la fuente que puede causar daño."},{"q":"En la MIPER, el disco de la sierra aparece como:","o":["Peligro","Riesgo","Medida de control","Consecuencia"],"w":"El disco es la fuente del daño: un peligro."},{"q":"La sierra girando es un peligro; cortarse con ella es el riesgo.","vf":true,"w":"Verdadero. Peligro es la fuente; riesgo es la posibilidad de daño."}]},{"s":"peligros_vs","v":[{"q":"La posibilidad de cortarse con la sierra y qué tan grave sería es:","o":["El riesgo","El peligro","La medida de control","El acto inseguro"],"w":"Riesgo es la posibilidad de daño y su gravedad."},{"q":"Se instala un resguardo en la sierra. ¿Qué cambia?","o":["Baja el riesgo, aunque el peligro sigue ahí","Desaparece el peligro de la sierra","Sube el riesgo porque se ve menos el disco","Nada, porque la sierra sigue igual"],"w":"El control reduce la posibilidad de daño, pero el disco sigue siendo un peligro."},{"q":"“Cortarme un dedo con la sierra” corresponde a:","o":["Un riesgo","Un peligro","Un control","Un EPP"],"w":"Es el daño posible: el riesgo."}]},{"s":"peligros_jerarquia","v":[{"q":"¿Cuál es la medida de control más efectiva?","o":["Eliminar el peligro","Usar EPP certificado","Poner señalización","Capacitar al trabajador"],"w":"Eliminar está en la cima de la jerarquía de controles."},{"q":"¿Cuál es el orden correcto, de más a menos efectivo?","o":["Eliminar, sustituir, ingeniería, administrativos, EPP","EPP, administrativos, ingeniería, sustituir, eliminar","Ingeniería, eliminar, EPP, sustituir, administrativos","Sustituir, eliminar, administrativos, EPP, ingeniería"],"w":"Primero se actúa sobre el peligro; el EPP va al final."},{"q":"El EPP es la primera medida que se debe aplicar frente a un peligro.","vf":false,"w":"Falso. Es la última barrera, después de los demás controles."}]},{"s":"peligros_eval","v":[{"q":"Para evaluar un riesgo se combinan:","o":["La probabilidad y la gravedad de la consecuencia","El costo del EPP y el tiempo de la tarea","La antigüedad del trabajador y su cargo","El tamaño de la máquina y su marca"],"w":"Qué tan seguido puede pasar y qué tan grave sería."},{"q":"Un corte en la sierra es poco frecuente, pero puede costar un dedo. ¿Cómo se clasifica?","o":["Riesgo alto, que se controla primero","Riesgo bajo, porque casi nunca pasa","No es riesgo, porque la sierra tiene resguardo","Riesgo medio, que se revisa a fin de año"],"w":"La gravedad de la consecuencia lo hace un riesgo alto."},{"q":"Entre un tropiezo con un retazo y un corte en la sierra, ¿cuál se atiende primero?","o":["El corte, porque su consecuencia es mucho más grave","El tropiezo, porque pasa más seguido","Ninguno: ambos dependen solo del cuidado personal","El que haya ocurrido más recientemente"],"w":"Los riesgos altos, por su gravedad, se controlan antes."}]},{"s":"peligros_sierra","v":[{"q":"Instalar un resguardo en la sierra es un control:","o":["De ingeniería","Administrativo","De EPP","De sustitución"],"w":"Los resguardos y la aspiración son controles de ingeniería."},{"q":"El procedimiento de trabajo seguro (PTS) de la sierra es un control:","o":["Administrativo","De ingeniería","De eliminación","De EPP"],"w":"Procedimientos, señalización y capacitación son controles administrativos."},{"q":"Un operador saca el resguardo, pero usa lentes y empujador. ¿Qué pasa con el riesgo?","o":["Sube, porque falta una capa de protección","Se mantiene igual, porque usa EPP","Baja, porque trabaja más cómodo","Desaparece si corta con cuidado"],"w":"Cada capa tapa los huecos de las otras: si falta una, el riesgo sube."}]},{"s":"peligros_irl","v":[{"q":"La empresa debe informarte los riesgos de tu puesto y cómo protegerte.","vf":true,"w":"Verdadero. Es tu derecho a saber, según el DS 44."},{"q":"Te cambian de la sierra a la zona de encolado. ¿Qué corresponde?","o":["Que me informen los riesgos del nuevo puesto y cómo protegerme","Usar la misma información que me dieron en la sierra","Aprender mirando a los compañeros","Esperar a la próxima inducción anual"],"w":"Cada cambio de puesto requiere informar sus riesgos (IRL)."},{"q":"¿Qué norma obliga a la empresa a informarte los riesgos de tu trabajo (IRL)?","o":["El DS 44","La Ley 20.580","La Ley de Tránsito 18.290","La Ley 20.949"],"w":"El DS 44 regula la gestión preventiva e incluye informar los riesgos."}]},{"s":"peligros_ignora","v":[{"q":"Un compañero ve un derrame junto al rack y dice “no es mío”. ¿Qué debió hacer?","o":["Advertir a los demás y avisar a la jefatura","Seguir trabajando, porque lo verá el de aseo","Pasar con cuidado y comentarlo al final del turno","Taparlo con un cartón y seguir"],"w":"Ver un peligro y avisarlo permite corregirlo antes de que alguien se lesione."},{"q":"Ver una condición insegura y no avisarla es:","o":["Una acción insegura","Una condición segura","Un control administrativo","Algo que solo le corresponde a la jefatura"],"w":"Callar también es una decisión insegura."},{"q":"Si una condición insegura no está en mi zona de trabajo, no me corresponde avisarla.","vf":false,"w":"Falso. Cualquier peligro que veas se avisa, sea o no de tu zona."}]},{"s":"peligros_reporta","v":[{"q":"Ves un pallet roto en el rack. ¿Qué haces?","o":["No lo uso, advierto a los demás y aviso a mi jefatura","Le pongo carga liviana encima con cuidado","Lo dejo donde está y uso otro sin avisar","Lo reparo con clavos para seguir"],"w":"Es una condición insegura: se aparta, se advierte y se reporta."},{"q":"Ves un pallet con una tabla quebrada cargado en el rack. ¿Qué corresponde?","o":["Advertir a los demás y avisar para bajarlo con seguridad","Sacarlo yo mismo, tirándolo con la mano","Agregarle más carga encima para estabilizarlo","Dejarlo así, porque todavía no se cae"],"w":"Un pallet dañado con carga puede ceder: se avisa y se retira con el equipo adecuado."},{"q":"Ves adhesivo derramado bajo el rack y no tienes con qué limpiarlo. ¿Qué haces?","o":["Advierto a los demás, señalizo si puedo y aviso","Paso por el lado con cuidado y sigo","Lo tapo con un panel para que no se vea","Espero que se seque solo en el turno"],"w":"Lo que no puedes corregir sin riesgo se señaliza y se avisa."}]},{"s":"peligros_auto","v":[{"q":"Sacar el resguardo de la sierra para cortar más rápido es:","o":["Una acción insegura","Una condición insegura","Un control de ingeniería","Un riesgo aceptado"],"w":"Es una decisión de la persona que puede costar una mano."},{"q":"Un resguardo roto que nadie ha reportado es:","o":["Una condición insegura","Una acción insegura","Un control administrativo","Un peligro eliminado"],"w":"Es un peligro que está en el lugar."},{"q":"Encuentras la sierra con el resguardo roto. ¿Cuál es la decisión segura?","o":["Detenerme, no usarla y avisar","Usarla con lentes y más cuidado","Cortar solo piezas grandes","Pedirle a otro que corte"],"w":"Una máquina sin protección no se usa hasta que se repare."}]}]},{"id":"epp","sec":"todos","title":"Uso y cuidado del EPP","thumb":"ppeAll","mins":5,"learn":[{"s":"epp_all","t":"¿Qué es el EPP?","x":"Son los <b>Elementos de Protección Personal</b>: casco, lentes de seguridad, protector auditivo, respirador, guantes, chaleco reflectante y zapatos de seguridad. Es la <b>última barrera</b>: primero se controla el peligro en la máquina o en el proceso, con resguardos y aspiración, y el EPP te protege de lo que queda. <b>No elimina el peligro</b>: solo reduce el daño si algo pasa, y solo si lo usas bien."},{"s":"epp_give","t":"Lo que dice la ley","x":"El <b>DS 594 (art. 53)</b> obliga al empleador a <b>proporcionar, libres de costo, los EPP adecuados al riesgo</b> y a enseñar su correcto uso. La <b>Ley 16.744 (art. 68)</b> también exige entregarlos sin costo: no se descuentan del sueldo. A su vez, el trabajador <b>debe usarlos mientras esté expuesto al riesgo</b>; no hacerlo es una falta al Reglamento Interno."},{"s":"epp_cert","t":"EPP certificado","x":"El EPP debe contar con <b>certificación de calidad</b> (DS 18 de 1982). Un lente de feria o un casco sin marca pueden verse igual, pero no resistir el impacto de una astilla de OSB. Usa el EPP que te entrega la empresa para tu puesto, no reemplazos comprados por tu cuenta. Respeta también su <b>vida útil</b>: los cascos y los filtros del respirador tienen fecha de recambio."},{"s":"epp_task","t":"Cada tarea, su EPP","x":"Ejemplos en {EMP}:<ul><li><b>Corte y rebaje:</b> lentes, protector auditivo y respirador para partículas.</li><li><b>Encolado:</b> guantes y lentes según la HDS del adhesivo.</li><li><b>Patio, carga y despacho:</b> casco y chaleco reflectante.</li><li><b>Todos:</b> zapatos de seguridad.</li></ul>Tu IRL y tu jefatura definen el EPP exacto de tu puesto. Pregunta antes de empezar si no lo tienes claro."},{"s":"epp_check","t":"Revísalo antes de usarlo","x":"Antes de cada turno, revisa:<ul><li><b>Casco:</b> sin trizaduras, golpes ni arnés suelto.</li><li><b>Lentes:</b> sin rayas que impidan ver.</li><li><b>Guantes:</b> sin cortes, hoyos ni adhesivo endurecido.</li><li><b>Respirador:</b> limpio, con elásticos firmes.</li><li><b>Fonos:</b> almohadillas enteras; tapones limpios.</li><li><b>Zapatos:</b> suela y puntera en buen estado.</li></ul>Si algo falla, no lo uses: pide recambio.","k":"EPP dañado no protege: no lo uses y pide recambio."},{"s":"epp_wear","t":"Bien puesto, o no sirve","x":"Los lentes van <b>en los ojos</b>, no sobre el casco ni en la frente. Los fonos, <b>sobre las orejas</b> y bien cerrados, no en el cuello. Los tapones, bien insertos en el oído. El respirador, <b>ajustado y sellado</b> a la cara: la barba impide el sello. El casco, con el arnés regulado. Los guantes, de tu talla para no perder agarre. Mal puesto es igual que no tenerlo."},{"s":"epp_time","t":"Todo el tiempo que estés expuesto","x":"Una astilla llega a tu ojo en <b>menos de un segundo</b>: un corte “rapidito” sin lentes basta para perderlo. Ponte el EPP <b>antes</b> de partir la tarea o de entrar a la zona señalizada, y sácatelo solo <b>al salir</b> del riesgo. Si hay ruido o polvo, también cuenta el rato que estás cerca de la máquina, aunque no la estés operando.","k":"Ponte el EPP antes de empezar y no te lo saques mientras haya riesgo."},{"s":"epp_care","t":"Cuídalo como tuyo","x":"Al terminar, límpialo y guárdalo en un lugar <b>limpio, seco y alejado del polvo y del sol</b>. Los <b>tapones, fonos y respiradores son personales</b>: no se prestan, por higiene y porque se ajustan a cada persona. No lo pintes, perfores, cortes ni le pegues adhesivos: cualquier modificación le quita protección. Limpia los lentes con agua o un paño limpio, no con el guante con polvo."},{"s":"epp_mod","t":"Si se daña o se pierde, pide recambio","x":"Si tu EPP está dañado, perdido, vencido o no es de tu talla, <b>avisa y pide recambio</b>: la empresa debe reponerlo sin costo. No lo “arregles” con cinta ni lo modifiques. Si un EPP te da calor o te molesta, la solución es <b>pedir otro modelo o talla</b>, no hacerle hoyos. Entrega el EPP dañado cuando recibas el nuevo."},{"s":"epp_self","t":"Autocuidado con el EPP","x":"La acción insegura típica: sacarse los lentes o el respirador <b>“un ratito”</b> porque se empañan, dan calor o incomodan. Justo en ese rato salta la astilla o se levanta el polvo. Decide seguro: si te molesta, <b>pide otra talla, otro modelo o lentes antiempañantes</b>, pero no trabajes sin él. Y <b>avisa</b> si falta EPP en tu puesto o si ves a alguien trabajando sin el suyo."}],"quiz":[{"s":"epp_give","v":[{"q":"¿Quién debe pagar el EPP que usas en {EMP}?","o":["La empresa, sin costo para el trabajador","Yo, con descuento por planilla","Lo pagamos a medias con la empresa","Yo, solo cuando lo pierdo o lo rompo"],"w":"DS 594 art. 53 y Ley 16.744 art. 68: el empleador lo proporciona sin costo."},{"q":"Se dañaron tus lentes de seguridad. ¿Cómo se reponen?","o":["Aviso y la empresa los repone sin costo","Me los descuentan del sueldo","Compro unos parecidos en una ferretería","Trabajo sin lentes hasta la próxima entrega"],"w":"La reposición del EPP también es sin costo para el trabajador."},{"q":"La empresa puede descontar del sueldo el EPP que entrega para tu puesto.","vf":false,"w":"Falso. La ley obliga a entregarlo libre de costo."}]},{"s":"epp_wearBad","v":[{"q":"¿Dónde deben ir los lentes de seguridad mientras cortas?","o":["En los ojos, bien puestos","Sobre el casco, listos para bajarlos","En la frente, para que no se empañen","Colgando del cuello con un cordón"],"w":"Los lentes solo protegen si están en los ojos."},{"q":"Un compañero tiene los fonos en el cuello mientras opera la rebajadora. ¿Qué pasa?","o":["No está protegido: deben ir sobre las orejas","Está bien, porque los tiene a mano","Está bien si la máquina hace poco ruido","Solo debe ponérselos en cortes largos"],"w":"Mal puesto es lo mismo que no tenerlo."},{"q":"Un trabajador lleva los lentes sobre el casco mientras corta. ¿Cómo está su protección?","o":["No protege: los lentes deben ir en los ojos","Protege, porque los lleva puestos","Protege si el casco tiene visera","Protege si el corte es corto"],"w":"Llevarlo encima no basta: tiene que estar bien puesto."}]},{"s":"epp_all","v":[{"q":"El EPP reduce el daño, pero no elimina el peligro de la tarea.","vf":true,"w":"Verdadero. Es la última barrera: el peligro sigue ahí."},{"q":"¿Por qué se dice que el EPP es la última barrera?","o":["Porque protege del riesgo que queda tras los otros controles","Porque es lo último que te pones antes de salir de la planta","Porque es el control más efectivo de todos","Porque solo se usa cuando las otras medidas ya fallaron"],"w":"Primero se controla en el origen; el EPP protege del riesgo que queda."},{"q":"Con resguardo y aspiración en la sierra, ¿sigue siendo necesario el EPP?","o":["Sí, porque protege del riesgo que queda","No, porque el peligro ya está controlado","Solo si el supervisor lo pide ese día","Solo en cortes de más de un minuto"],"w":"Los controles bajan el riesgo, pero no lo hacen cero."}]},{"s":"epp_time","v":[{"q":"Según el DS 594, ¿cuándo debes usar tu EPP?","o":["Todo el tiempo que esté expuesto al riesgo","Solo cuando la jefatura está presente","Solo en las tareas que duran más de una hora","Solo mientras opero directamente la máquina"],"w":"El trabajador debe usarlo todo el tiempo que esté expuesto."},{"q":"Pasas un rato junto a la rebajadora funcionando, aunque no la operas. ¿Necesitas tu EPP?","o":["Sí, el ruido y el polvo también me afectan cerca de la máquina","No, solo lo necesita el operador","Solo si me quedo más de una hora","No, si no la estoy operando no hay exposición"],"w":"La exposición cuenta aunque no operes la máquina."},{"q":"¿En qué momento te pones el EPP?","o":["Antes de partir la tarea o de entrar a la zona señalizada","Apenas empiezo a sentir ruido o polvo","Cuando el supervisor me lo recuerda","Después del primer corte, para probar la máquina"],"w":"El accidente no espera a que te pongas el EPP."}]},{"s":"epp_time","v":[{"q":"Para un corte rápido de 10 segundos en la sierra no es necesario usar lentes.","vf":false,"w":"Falso. Una astilla tarda menos de un segundo en llegar al ojo."},{"q":"Te queda un solo corte y dejaste los lentes lejos. ¿Qué haces?","o":["Voy por ellos antes de cortar","Hago el corte rápido entrecerrando los ojos","Uso mis lentes ópticos, que también protegen","Corto con el resguardo bajo y sin lentes"],"w":"Un lente común no está certificado contra impactos, y un corte basta para dañar un ojo."},{"q":"¿Cuánto tarda una astilla de la sierra en llegar a tu ojo?","o":["Menos de un segundo","Unos cinco segundos","Lo suficiente para cerrar los ojos","Depende del largo del corte"],"w":"No hay tiempo de reaccionar: el lente debe estar puesto antes."}]},{"s":"epp_check","v":[{"q":"Tu casco tiene una trizadura. ¿Qué haces?","o":["Aviso y pido uno nuevo","Lo sigo usando con cuidado","Le pongo cinta adhesiva","Lo uso solo en el patio"],"w":"Un casco trizado ya no protege: se reemplaza sin costo."},{"q":"Antes de usar el respirador ves un elástico cortado. ¿Qué corresponde?","o":["No lo uso y pido recambio","Lo amarro con un nudo y lo uso","Lo sujeto con la mano mientras corto","Lo uso igual, porque el filtro está bueno"],"w":"Sin elásticos firmes no sella: no protege."},{"q":"¿Cuándo debes revisar tu EPP?","o":["Antes de cada uso o turno","Una vez al mes","Solo cuando se nota roto","Solo cuando hay una inspección"],"w":"La revisión diaria detecta fallas antes de que te expongas."}]},{"s":"epp_care","v":[{"q":"Un compañero te ofrece su respirador usado. ¿Lo aceptas?","o":["No: tapones, fonos y respiradores son personales","Sí, si está limpio por fuera","Sí, solo por un rato","Sí, si le ajusto bien los elásticos a mi cara"],"w":"Son de uso personal por higiene y ajuste. Pide el tuyo."},{"q":"¿Dónde se guarda el EPP al terminar el turno?","o":["En un lugar limpio, seco y lejos del polvo y del sol","Colgado en la máquina, para tenerlo a mano","En el piso junto al puesto","En la mochila junto con la ropa sucia"],"w":"Bien guardado dura más y protege mejor."},{"q":"Los tapones, fonos y respiradores son de uso personal y no se prestan.","vf":true,"w":"Verdadero. Por higiene y porque se ajustan a cada persona."}]},{"s":"epp_cert","v":[{"q":"¿Qué debe tener un EPP para ser confiable?","o":["Certificación de calidad","El precio más bajo del mercado","Un color llamativo","Una talla única que sirva a todos"],"w":"El DS 18 de 1982 regula la certificación de calidad de los EPP."},{"q":"Compraste unos lentes de feria que se ven iguales a los de la empresa. ¿Puedes usarlos?","o":["No, porque sin certificación quizás no resisten un impacto","Sí, si son transparentes y cubren bien los ojos","Sí, siempre que no tengan rayas","Solo para tareas cortas"],"w":"Parecido no es lo mismo: usa el EPP certificado que entrega la empresa."},{"q":"¿Qué norma regula la certificación de calidad de los EPP?","o":["El DS 18 de 1982","La Ley 20.949","El DS 57","La Ley 18.290"],"w":"El DS 18 de 1982 exige certificación de calidad."}]},{"s":"epp_mod","v":[{"q":"Hacerle hoyos al casco para que ventile está bien si son pequeños.","vf":false,"w":"Falso. Cualquier modificación le quita resistencia."},{"q":"Tu casco da mucho calor en verano. ¿Qué corresponde?","o":["Pedir otro modelo, sin modificar el casco","Hacerle hoyos pequeños para ventilar","Usarlo solo en la mañana","Cambiarlo por un jockey"],"w":"Si molesta, se cambia de modelo; nunca se modifica."},{"q":"Tus guantes se rompieron en la punta. ¿Qué haces?","o":["Aviso y pido recambio sin costo","Los arreglo con cinta","Corto los dedos para que no molesten","Sigo con ellos hasta fin de mes"],"w":"EPP dañado se repone, no se arregla."}]},{"s":"epp_self","v":[{"q":"Los lentes se te empañan y te molestan. ¿Qué haces?","o":["Pido otro modelo o lentes antiempañantes","Me los saco un ratito mientras corto","Los subo a la frente y miro con cuidado","Trabajo sin lentes hasta que se aclaren"],"w":"La incomodidad se arregla con otro modelo; no trabajando sin protección."},{"q":"Por el calor, un compañero se saca los lentes “un ratito” mientras corta. ¿Qué es?","o":["Una acción insegura","Una condición insegura","Algo aceptado en verano","Un control administrativo"],"w":"Es una decisión de la persona: justo en ese rato puede saltar la astilla."},{"q":"Un compañero se sube los lentes a la frente porque se empañan. ¿Qué le recomiendas?","o":["Que pida otro modelo o antiempañantes y no trabaje sin ellos","Que corte rápido mientras se desempañan","Que los limpie con el guante y siga","Que trabaje sin lentes, pero más lejos del disco"],"w":"Avisar y buscar una solución es cuidarse entre todos."}]}]},{"id":"orden","sec":"todos","title":"Orden y aseo","thumb":"tidy","mins":5,"learn":[{"s":"orden_trip","t":"El desorden también accidenta","x":"Las caídas al mismo nivel están entre los accidentes más frecuentes. Casi siempre hay algo en el piso: <b>cables, retazos de OSB, trozos de EPS, viruta, zunchos</b> o una herramienta. Un tropiezo con un panel en las manos puede terminar en un esguince, un golpe en la cabeza o una caída hacia una máquina. Mira por dónde caminas y, si la carga te tapa la vista del piso, <b>revisa antes el camino o pide ayuda</b>."},{"s":"orden_aisle","t":"Pasillos despejados","x":"Los pasillos deben permitir el <b>movimiento seguro</b> de personas y materiales, <b>libres de obstáculos</b> (DS 594, art. 8). Por ahí pasan personas, carros, transpaletas y la grúa horquilla. Nunca dejes paneles, pallets ni carros “un rato” en el pasillo: obligas a otros a esquivar y a meterse en la ruta de la grúa. Respeta la <b>demarcación del piso</b>: lo que queda sobre la línea, invade."},{"s":"orden_stack","t":"Paneles bien apilados","x":"<ul><li>Sobre pallet o separadores, en piso firme y nivelado.</li><li>Rumas <b>parejas y estables</b>, sin paneles salidos.</li><li>A la <b>altura que indique tu jefatura</b>, sin que se incline.</li><li>Lo más pesado y grande, abajo.</li><li>Sin invadir el pasillo ni tapar señales.</li><li><b>Nunca te subas a una ruma</b> ni saques un panel de abajo.</li></ul>Si una ruma se inclina, <b>aléjate, no la sujetes y avisa</b>.","k":"Si una ruma se inclina: aléjate, no la sujetes y avisa."},{"s":"orden_exits","t":"Salidas, extintores y tableros libres","x":"Nunca dejes materiales delante de una <b>salida de emergencia, un extintor o un tablero eléctrico</b>, ni siquiera por un rato. En una emergencia cada segundo cuenta: nadie debería tener que mover pallets para escapar, apagar un amago o cortar la energía. Las salidas de emergencia no se cierran con llave durante el turno. Si ves una bloqueada, despéjala si puedes y <b>avisa</b>.","k":"Salidas, extintores y tableros siempre despejados."},{"s":"orden_cables","t":"Cables en el piso","x":"Una extensión cruzando el pasillo es un tropiezo seguro, y el cable se daña con las ruedas de la transpaleta y la grúa. Llévala <b>por el borde</b>, por arriba o protegida con un cubrecable. Al terminar, <b>desenchúfala, enróllala y guárdala</b>. Si ves un cable pelado o un enchufe quebrado, <b>no lo toques ni lo uses</b>: avisa a tu jefatura."},{"s":"orden_scraps","t":"Retazos y viruta","x":"Los cortes y el rebaje dejan <b>retazos de OSB, trozos de EPS y viruta</b>. Bajo las máquinas se acumulan, hacen resbalar y además son <b>combustible</b> para un incendio. Echa los retazos al contenedor <b>durante el turno</b>, a medida que se generan, no solo al final. Para sacar restos cerca del disco o de la cuchilla, <b>detén la máquina primero</b>: nunca con la mano mientras gira."},{"s":"orden_spill","t":"Derrames: avisa, señaliza y limpia","x":"Si cae adhesivo, aceite o agua al piso: <b>avisa, señaliza y limpia</b> de inmediato. Usa material absorbente; si es un producto químico, sigue lo que indica su <b>HDS</b> y usa el EPP que pide, como guantes y lentes. Deja el cono o la señal <b>hasta que el piso esté seco</b>. No lo dejes “para después”: el próximo que pase, quizás con un panel en las manos, puede resbalar."},{"s":"orden_clean","t":"Limpiar sin levantar polvo","x":"El polvo de madera <b>se aspira o se humedece antes de barrer</b>. Barrer en seco lo levanta y queda en el aire que respiras. <b>Nunca uses aire comprimido sobre la ropa ni el cuerpo</b>: el polvo se dispersa, y el aire a presión puede dañar ojos, oídos y piel. Limpia con la máquina detenida y usa tu respirador y lentes mientras lo haces."},{"s":"orden_5s","t":"Las 5S: cinco hábitos simples","x":"<ul><li><b>Separar:</b> saca del puesto lo que no sirve, como retazos y envases vacíos.</li><li><b>Ordenar:</b> un lugar para cada cosa y cada cosa en su lugar.</li><li><b>Limpiar:</b> al limpiar, revisa si algo está dañado.</li><li><b>Estandarizar:</b> marca lugares, rumas y pasillos.</li><li><b>Sostener:</b> hazlo todos los días, no solo cuando hay visita.</li></ul>La herramienta que sacas, la devuelves a su lugar al terminar."},{"s":"orden_self","t":"Autocuidado: orden y aseo","x":"La acción insegura típica aquí es <b>“lo ordeno después”</b>, o tomar un atajo pasando por encima de una ruma, un pallet o un cable. Otra: subirse a una ruma de paneles para alcanzar algo. Decide seguro: ordena al momento, usa el camino demarcado y <b>avisa</b> las condiciones inseguras que no puedas corregir: piso roto, luz quemada, ruma inclinada o pallet dañado."}],"quiz":[{"s":"orden_trip","v":[{"q":"¿Cuál es una causa frecuente de caídas al mismo nivel en la planta?","o":["Cables, retazos y viruta en el piso","Usar zapatos de seguridad nuevos","Caminar por el pasillo demarcado","Trabajar con buena iluminación"],"w":"Lo que queda en el piso hace tropezar o resbalar."},{"q":"Vas a trasladar un panel que te tapa la vista del piso. ¿Qué es lo más seguro?","o":["Revisar antes que el camino esté despejado o pedir ayuda","Caminar rápido para estar menos tiempo cargando","Arrastrar los pies para sentir los obstáculos","Ir por el camino más corto aunque haya retazos"],"w":"Si no ves el piso, el camino debe estar despejado antes de partir."},{"q":"Las caídas al mismo nivel están entre los accidentes más frecuentes.","vf":true,"w":"Verdadero. Por eso un piso despejado es tan importante."}]},{"s":"orden_5s","v":[{"q":"En las 5S, ¿qué significa “Ordenar”?","o":["Un lugar para cada cosa y cada cosa en su lugar","Juntar todo en el pasillo para tenerlo a mano","Limpiar solo cuando viene una visita","Sacar del puesto lo que no sirve"],"w":"Así encuentras todo rápido y nada queda tirado en el piso."},{"q":"Terminaste de usar el taladro. Según las 5S, ¿qué haces?","o":["Lo devuelvo a su lugar","Lo dejo sobre la ruma para el próximo","Lo dejo en el piso junto a la máquina","Lo guardo en mi bolso para no perderlo"],"w":"Lo que sacas, lo devuelves a su lugar."},{"q":"¿Qué “S” consiste en mantener el orden todos los días y no solo cuando hay visita?","o":["Sostener","Separar","Limpiar","Estandarizar"],"w":"Sostener es convertir el orden en hábito diario."}]},{"s":"orden_exitBad","v":[{"q":"Hay pallets apilados frente a una salida de emergencia. ¿Qué haces?","o":["Los despejo si puedo y aviso a mi jefatura","Los dejo: en una emergencia se mueven","Dejo un espacio pequeño para pasar de lado","Pongo un letrero sobre los pallets"],"w":"Salidas, extintores y tableros deben estar siempre despejados."},{"q":"¿Qué elementos deben estar siempre despejados?","o":["Salidas de emergencia, extintores y tableros eléctricos","Solo las salidas que dan a la calle","Solo los extintores, porque las salidas se usan poco","Solo los tableros, porque los usan los eléctricos"],"w":"En una emergencia los tres se necesitan sin demora."},{"q":"Se puede dejar un pallet delante de un tablero eléctrico si es solo por un rato.","vf":false,"w":"Falso. Una emergencia puede ocurrir justo en ese rato."}]},{"s":"orden_spill","v":[{"q":"Se derramó adhesivo en el piso. ¿Qué haces?","o":["Aviso, señalizo y limpio de inmediato","Sigo trabajando; después alguien limpia","Le tiro retazos encima para no pisarlo","Lo dejo secar solo para que no se esparza"],"w":"Avisar, señalizar y limpiar evita que otro resbale."},{"q":"Vas a limpiar el derrame de un producto químico. ¿Qué revisas primero?","o":["Su HDS y el EPP que indica","Que haya agua suficiente para diluirlo","Si huele fuerte, para saber si es peligroso","Que sea poco, para limpiarlo con la mano"],"w":"La HDS dice cómo limpiarlo y con qué protección."},{"q":"Ya limpiaste el derrame, pero el piso sigue húmedo. ¿Qué haces con la señal?","o":["La dejo hasta que el piso esté seco","La retiro, porque ya limpié","La cambio por un retazo de OSB","La guardo para no estorbar el paso"],"w":"Mientras el piso esté húmedo, sigue el riesgo de resbalar."}]},{"s":"orden_clean","v":[{"q":"¿Cómo se limpia el polvo de madera?","o":["Se aspira o se humedece antes de barrer","Se sopla con aire comprimido","Se barre en seco con fuerza","Se deja hasta el aseo del fin de semana"],"w":"Así no queda flotando en el aire que respiras."},{"q":"¿Por qué no se barre en seco el polvo de madera?","o":["Porque se levanta y queda en el aire que respiras","Porque raya el piso de la planta","Porque así tarda más en limpiarse la planta","Porque se pega a los zapatos"],"w":"El polvo en el aire se inhala."},{"q":"¿Cuál es la forma segura de limpiar bajo la sierra?","o":["Con la máquina detenida, aspirando y con respirador","Con la máquina girando, para que el disco bote el polvo","Soplando con aire comprimido para hacerlo rápido","Barriendo en seco, porque es más rápido"],"w":"Máquina detenida, sin levantar polvo y con EPP."}]},{"s":"orden_clean","v":[{"q":"Sacudirse el polvo de la ropa con aire comprimido es seguro.","vf":false,"w":"Falso. Levanta polvo y el aire a presión puede lesionar ojos, oídos y piel."},{"q":"Terminas el turno con la ropa llena de polvo. ¿Qué haces?","o":["Me limpio sin aire comprimido, por ejemplo con aspiradora","Me soplo con la pistola de aire","Le pido a un compañero que me sople","Me sacudo fuerte la ropa con las manos en el puesto"],"w":"El aire comprimido nunca se usa sobre la ropa ni el cuerpo."},{"q":"¿Qué daño puede causar el aire comprimido dirigido al cuerpo?","o":["Lesiones en ojos, oídos y piel","Ninguno, solo deja la ropa más limpia","Ninguno si es por poco rato","Solo un resfrío por el aire frío"],"w":"El aire a presión puede lesionar y además dispersa el polvo."}]},{"s":"orden_stack","v":[{"q":"¿Cómo debe quedar una ruma de paneles?","o":["Pareja, estable, a la altura indicada y fuera del pasillo","Lo más alta posible para ahorrar espacio","Apoyada en la pared del pasillo","Con los paneles chicos abajo y los grandes arriba"],"w":"Una ruma estable no se cae sobre nadie."},{"q":"Necesitas un panel que está abajo en la ruma. ¿Qué haces?","o":["Retiro primero los de arriba, con ayuda o equipo","Tiro el panel de abajo con cuidado y de a poco","Me subo a la ruma para alcanzarlo","Lo saco de lado, moviendo la ruma"],"w":"Sacar un panel de abajo desestabiliza toda la ruma."},{"q":"En una ruma, lo más pesado y grande va abajo.","vf":true,"w":"Verdadero. Así la ruma queda estable."}]},{"s":"orden_cables","v":[{"q":"Necesitas una extensión que cruza el pasillo. ¿Qué haces?","o":["La llevo por el borde o protegida, y la guardo al terminar","La dejo cruzando: todos la ven","La tapo con retazos de OSB","La pongo bajo un pallet para que no se mueva del lugar"],"w":"Un cable atravesado hace tropezar y se daña."},{"q":"Ves un cable con el aislamiento pelado. ¿Qué haces?","o":["No lo toco ni lo uso y aviso","Lo envuelvo con cinta y sigo","Lo muevo con la mano a un lado","Lo uso con guantes"],"w":"Un cable pelado puede dar una descarga: se avisa."},{"q":"Terminaste de usar la extensión. ¿Qué corresponde?","o":["Desenchufarla, enrollarla y guardarla","Dejarla enchufada para el próximo turno","Dejarla estirada en el pasillo","Enrollarla enchufada para ganar tiempo"],"w":"Guardada no hace tropezar ni se daña."}]},{"s":"orden_scraps","v":[{"q":"¿Cuándo se sacan los retazos y la viruta del puesto?","o":["Durante el turno, a medida que se generan","Una vez a la semana","Solo al final del turno","Cuando la jefatura lo pide en la ronda"],"w":"Acumulados hacen resbalar y alimentan un incendio."},{"q":"¿Dónde van los retazos de OSB y EPS que salen del corte?","o":["Al contenedor, durante el turno","Bajo la máquina hasta el final del turno","Apilados en el pasillo para sacarlos juntos","Junto a la ruma de paneles buenos"],"w":"Lo que sobra va al contenedor, no al piso."},{"q":"¿Por qué la viruta acumulada bajo las máquinas es peligrosa?","o":["Hace resbalar y es combustible para un incendio","Solo porque se ve desordenado","Porque desgasta las ruedas de los carros","Porque tapa la demarcación del piso"],"w":"Es riesgo de caída y de incendio a la vez."}]},{"s":"orden_stack","v":[{"q":"Ves una ruma de paneles que se está inclinando. ¿Qué haces?","o":["Me alejo, aviso y no dejo que nadie pase cerca","La enderezo solo, empujándola con el hombro","La sujeto con las manos mientras llamo a alguien","Le pongo un panel de apoyo y sigo"],"w":"Una ruma que se viene abajo puede aplastarte."},{"q":"Una ruma se inclina hacia el pasillo. ¿Por qué no debes sujetarla?","o":["Porque si cae puede aplastarte; hay que alejarse y avisar","Porque es tarea exclusiva del operador de grúa","Porque se puede rayar el panel","Porque basta con poner un cono"],"w":"Ninguna persona puede contener el peso de una ruma que cae."},{"q":"Ves una ruma alta y despareja junto al pasillo. ¿Qué haces?","o":["Aviso para que se rearme estable y no paso cerca","La dejo, porque todavía no se cae","La empujo para emparejarla","Saco los paneles de abajo para bajarla"],"w":"Una ruma despareja es una condición insegura que se avisa."}]}]},{"id":"cargas","sec":"todos","title":"Manejo manual de cargas","thumb":"cargas_tecnica","mins":5,"learn":[{"s":"cargas_intro","t":"¿Qué es el manejo manual de carga?","x":"Es cualquier tarea en que usas tu cuerpo para <b>levantar, bajar, empujar, arrastrar o trasladar</b> algo. En {EMP}: tableros OSB, planchas de EPS, paneles SIP, sacos y tambores de adhesivo, cajas. <b>La zona que más se lesiona es la espalda baja (zona lumbar)</b>: un lumbago o una hernia pueden acompañarte por años. El riesgo sube con el peso, la distancia, los giros, la repetición y el apuro."},{"s":"cargas_limites","t":"Los límites de la ley","x":"<ul><li><b>Hombres adultos:</b> máximo <b>25 kg</b> (Código del Trabajo, art. 211-H).</li><li><b>Mujeres y menores de 18 años:</b> máximo <b>20 kg</b> (art. 211-J).</li><li><b>Trabajadoras embarazadas:</b> tienen <b>prohibido</b> cargar y descargar manualmente, sin importar el peso (art. 211-I).</li></ul>Estos límites vienen de la <b>Ley 20.949</b>. Que la ley permita 25 kg no significa que levantarlos mal sea seguro."},{"s":"cargas_piensa","t":"Antes de levantar, piensa 5 segundos","x":"<ul><li>¿Cuánto pesa? Mira la etiqueta o pruébalo moviéndolo un poco.</li><li>¿Tiene buen agarre o es largo e incómodo?</li><li>¿El camino está libre, el piso seco y sin retazos?</li><li>¿Dónde lo voy a dejar y a qué altura?</li><li>¿Tengo guantes para los cantos del OSB?</li></ul>Si algo no calza, <b>pide ayuda</b> o usa transpaleta o carro. Planificar 5 segundos evita meses de dolor."},{"s":"cargas_tecnica","t":"Levanta con las piernas, no con la espalda","x":"<ul><li>Acércate a la carga, con los pies separados a los lados.</li><li>Flecta las rodillas y mantén la <b>espalda recta</b>.</li><li>Agarra firme con toda la mano y <b>pega la carga al cuerpo</b>.</li><li>Sube con la fuerza de las piernas, suave y sin tirones.</li><li>Para bajarla, haz lo mismo al revés.</li></ul>Mientras más lejos del cuerpo va la carga, más esfuerzo hace tu espalda.","k":"Piernas trabajan, espalda recta, carga pegada al cuerpo."},{"s":"cargas_giro","t":"No gires la cintura","x":"Pasa mucho al dejar un saco o una plancha en el pallet de al lado: se gira el tronco con los pies quietos. <b>Torcer la cintura con peso</b> es una de las causas más comunes de lumbago. <b>Gira moviendo los pies</b>, con la carga siempre frente a ti y pegada al cuerpo. Organiza el puesto para que el pallet de destino quede cerca y de frente."},{"s":"cargas_ayuda","t":"Ayuda mecánica: tu mejor compañera","x":"Un saco de 35 kg <b>supera el límite legal</b>: no se levanta a mano. Para eso están la <b>transpaleta, el carro u otra ayuda mecánica</b>; úsalas también con pallets de paneles y cajas pesadas. <b>Empujar es mejor que tirar</b>: ves el camino y usas el peso de tu cuerpo. Con la transpaleta, revisa ruedas y freno, mantén los pies fuera de las horquillas y nunca te subas a ella.","k":"Sobre el límite no se discute: ayuda mecánica."},{"s":"cargas_dos","t":"Paneles largos: entre dos","x":"Un panel SIP largo quizás no pesa tanto, pero es incómodo, se balancea y el viento lo mueve en el patio. Entre dos: <b>uno dirige y avisa</b> (“¡Arriba!”, “¡Vamos!”, “¡Abajo!”) y ambos levantan, caminan y bajan al mismo tiempo. Antes, revisen que el camino esté libre y acuerden dónde lo dejarán. Si pueden, busquen un compañero de altura parecida."},{"s":"cargas_zona","t":"Lo pesado, a la altura correcta","x":"La zona más segura para manipular es <b>entre las rodillas y los hombros</b>. Guarda lo más pesado en los niveles del medio del rack, y lo liviano arriba o abajo. Evita levantar cargas por sobre los hombros o directo desde el suelo. Para alcanzar algo alto, usa una escala: <b>nunca te subas al rack</b> ni a un pallet."},{"s":"cargas_auto","t":"Autocuidado: tú decides","x":"La acción insegura típica en cargas es <b>“es rápido, lo levanto solo”</b>: apurarse, doblar la espalda o cargar sobre el límite. La decisión segura: <b>pedir ayuda o usar la transpaleta</b>, aunque tome un minuto más. Si sientes dolor o un tirón, <b>detente y avisa de inmediato</b>: es un accidente del trabajo. Y avisa las condiciones inseguras: transpaleta dañada, piso irregular o pasillo bloqueado."}],"quiz":[{"s":"cargas_limites","v":[{"q":"Según el Código del Trabajo, ¿cuál es el peso máximo que un hombre adulto puede manipular manualmente?","o":["25 kg","20 kg","30 kg","50 kg"],"w":"Art. 211-H: 25 kg. Para mujeres y menores de 18 años, 20 kg."},{"q":"Un trabajador hombre debe mover cajas de 28 kg. ¿Qué corresponde?","o":["Usar ayuda mecánica, porque supera los 25 kg","Levantarlas con buena técnica, porque está cerca del límite","Levantarlas si es fuerte y tiene experiencia","Moverlas a mano, pero haciendo pausas"],"w":"Sobre el límite legal se usa ayuda mecánica."},{"q":"El límite de 25 kg significa que hasta ese peso cualquier forma de levantar es segura.","vf":false,"w":"Falso. Bajo el límite también hay que usar buena técnica."}]},{"s":"cargas_limites","v":[{"q":"¿Cuál es el límite de carga manual para mujeres y menores de 18 años?","o":["20 kg","25 kg","15 kg","30 kg"],"w":"Art. 211-J del Código del Trabajo: 20 kg."},{"q":"Un trabajador de 17 años debe mover un saco de 23 kg. ¿Qué corresponde?","o":["No lo levanta a mano: el máximo para menores de 18 es 20 kg","Puede levantarlo, porque el límite general es 25 kg","Puede levantarlo con buena técnica","Puede levantarlo si un adulto lo supervisa"],"w":"Para menores de 18 años el límite es 20 kg."},{"q":"¿Qué ley fijó los límites de 25 y 20 kg para la carga manual?","o":["La Ley 20.949","La Ley 21.643","La Ley 20.580","La Ley 18.290"],"w":"La Ley 20.949 modificó el Código del Trabajo con estos límites."}]},{"s":"cargas_q_emb","v":[{"q":"Una trabajadora embarazada puede cargar sacos si pesan menos de 20 kg.","vf":false,"w":"Falso. Las trabajadoras embarazadas tienen prohibido cargar y descargar manualmente (art. 211-I)."},{"q":"Una compañera embarazada debe mover cajas livianas de 5 kg. ¿Qué dice la ley?","o":["Tiene prohibido cargar y descargar manualmente","Puede hacerlo hasta 20 kg","Puede hacerlo si usa faja","Puede hacerlo con pausas cada hora"],"w":"La prohibición rige sin importar el peso."},{"q":"¿Cuál es el peso máximo que puede cargar manualmente una trabajadora embarazada?","o":["Ninguno: está prohibida","10 kg, con pausas","20 kg, como las mujeres","15 kg, con ayuda"],"w":"Art. 211-I: no puede realizar carga ni descarga manual."}]},{"s":"cargas_tecnica","v":[{"q":"¿Cuál es la técnica correcta para levantar una caja del suelo?","o":["Rodillas flectadas, espalda recta y carga pegada al cuerpo","Piernas estiradas y espalda doblada para llegar rápido","Brazos estirados para alejar la carga del cuerpo","Un tirón fuerte para aprovechar el impulso"],"w":"Las piernas hacen la fuerza y la espalda se mantiene recta."},{"q":"¿Por qué se debe llevar la carga pegada al cuerpo?","o":["Porque mientras más lejos va, más esfuerzo hace la espalda","Porque así se ve mejor el camino","Porque así la carga pesa menos en la balanza al pesarla","Porque así se cansan menos las piernas"],"w":"La distancia multiplica el esfuerzo sobre la zona lumbar."},{"q":"¿Qué parte del cuerpo debe hacer la fuerza al levantar?","o":["Las piernas","La espalda baja","Los brazos estirados","El cuello y los hombros"],"w":"Las piernas son más fuertes y protegen la espalda."}]},{"s":"cargas_giro","v":[{"q":"Si tengo que dejar la carga a mi lado, lo correcto es girar la cintura sin mover los pies.","vf":false,"w":"Falso. Se gira moviendo los pies; torcer la cintura con carga daña la espalda."},{"q":"Debes dejar un saco en el pallet que está a tu derecha. ¿Cómo lo haces?","o":["Giro moviendo los pies, con la carga frente a mí","Giro solo la cintura para hacerlo rápido","Lanzo el saco hacia el pallet","Giro la cintura de a poco y con cuidado"],"w":"Primero los pies, después el cuerpo."},{"q":"¿Qué movimiento con carga es una causa común de lumbago?","o":["Torcer la cintura con los pies quietos","Caminar con la carga pegada al cuerpo","Flectar las rodillas al bajar","Empujar un carro"],"w":"El giro de tronco con peso sobrecarga la zona lumbar."}]},{"s":"cargas_ayuda","v":[{"q":"Un saco de adhesivo pesa 35 kg. ¿Qué haces?","o":["Uso transpaleta, carro u otra ayuda mecánica","Lo levanto rápido para que dure poco","Lo arrastro con la espalda recta","Lo levanto con buena técnica, flectando las rodillas"],"w":"Supera el límite de 25 kg: la técnica no basta, se usa ayuda mecánica."},{"q":"Con una carga sobre ruedas, ¿qué es mejor?","o":["Empujar, porque veo el camino y uso mi peso","Tirar de espaldas, porque cuesta menos","Tirar con un brazo para tener el otro libre","Da lo mismo empujar o tirar"],"w":"Empujando ves por dónde vas y usas el peso del cuerpo."},{"q":"Al usar la transpaleta, ¿qué es correcto?","o":["Revisar ruedas y freno y mantener los pies fuera de las horquillas","Subirse a ella para avanzar más rápido en pasillos largos","Usarla aunque tenga una rueda trabada","Cargarla sobre su capacidad si el tramo es corto"],"w":"Una transpaleta revisada y bien usada evita aplastamientos."}]},{"s":"cargas_dos","v":[{"q":"Para trasladar un panel SIP largo entre dos, lo más importante es:","o":["Que uno dirija con la voz y ambos se muevan al mismo tiempo","Que cada uno camine a su ritmo","Que el más fuerte lleve la mayor parte sin avisar","Llevarlo sobre la cabeza para ver mejor"],"w":"Una sola voz dirige la maniobra."},{"q":"Van dos con un panel largo y tu compañero quiere bajarlo. ¿Qué corresponde?","o":["Que quien dirige avise “¡Abajo!” y lo bajen juntos","Que cada uno lo suelte cuando se canse","Que él baje primero su lado","Que lo baje sin avisar para ganar tiempo"],"w":"Bajar sin coordinar descarga todo el peso en el otro."},{"q":"Al mover un panel largo entre dos, una sola persona debe dirigir la maniobra.","vf":true,"w":"Verdadero. Así ambos levantan, caminan y bajan al mismo tiempo."}]},{"s":"cargas_piensa","v":[{"q":"Antes de levantar una carga, ¿qué debes revisar?","o":["Su peso, el agarre, el camino y dónde la dejarás","Solo el color del envase","Solo que no haya nadie mirando","Solo su tamaño, porque lo grande siempre pesa más"],"w":"Pensar 5 segundos antes de levantar evita errores típicos."},{"q":"Vas a mover un tambor de adhesivo y no sabes cuánto pesa. ¿Qué haces?","o":["Reviso la etiqueta o lo pruebo moviéndolo un poco","Lo levanto de un tirón para probar","Le pregunto a un compañero si se ve pesado","Lo levanto con buena técnica sin revisar"],"w":"Conocer el peso te dice si necesitas ayuda."},{"q":"El camino al pallet tiene retazos de OSB. ¿Qué haces antes de levantar?","o":["Despejo el camino","Lo levanto y paso con cuidado sobre ellos","Camino más rápido","Pido que alguien me guíe con la voz"],"w":"Un tropiezo con carga es doble riesgo."}]},{"s":"cargas_q_rack","v":[{"q":"¿Dónde conviene guardar lo más pesado en un rack?","o":["En los niveles del medio del rack","En el nivel más alto, para dejar espacio abajo","En el suelo, al fondo del rack","Donde quede espacio libre ese día"],"w":"Entre rodillas y hombros se manipula con menos esfuerzo."},{"q":"Tienes una caja pesada y otra liviana para guardar en el rack. ¿Dónde va la pesada?","o":["En un nivel del medio","En el nivel más alto","En el piso, bajo el primer nivel","Donde haya espacio libre"],"w":"Lo pesado al medio; lo liviano arriba o abajo."},{"q":"La zona más segura para manipular cargas está entre las rodillas y los hombros.","vf":true,"w":"Verdadero. Ahí la espalda trabaja recta y con menos esfuerzo."}]},{"s":"cargas_q_apuro","v":[{"q":"Vas atrasado y la caja es pesada. ¿Cuál es la decisión segura?","o":["Detenerme y pedir ayuda o usar ayuda mecánica","Levantarla solo, de un tirón, para ganar tiempo","Arrastrarla con la espalda doblada","Levantarla rápido con los brazos estirados"],"w":"Pedir ayuda toma segundos; una lesión lumbar, meses."},{"q":"Hay que despachar un camión y quedan tres cajas pesadas. ¿Qué haces?","o":["Uso el carro o pido ayuda, aunque tarde un poco más","Las levanto de un tirón para alcanzar","Las arrastro doblando la espalda","Las cargo de a dos juntas para ahorrar viajes"],"w":"El apuro es la causa típica de la acción insegura."},{"q":"“Es rápido, lo levanto solo” es un ejemplo de:","o":["Acción insegura","Condición insegura","Buena técnica","Control de ingeniería"],"w":"Es una decisión de la persona que expone su espalda."}]}]},{"id":"accidente","sec":"todos","title":"¿Qué hacer si tengo un accidente del trabajo?","thumb":"accidente_ley","mins":5,"learn":[{"s":"accidente_ley","t":"Estás protegido por la Ley 16.744","x":"Todo trabajador tiene un <b>seguro obligatorio</b> que cubre accidentes del trabajo, accidentes de trayecto y enfermedades profesionales. Lo paga la empresa, no tú. {EMP} está adherida a la <b>ACHS</b>: la atención allí es <b>gratuita</b>, desde la primera curación hasta la rehabilitación. Si corresponde, el seguro también paga tus días de licencia mediante un <b>subsidio</b> y, si queda una secuela, indemnización o pensión."},{"s":"accidente_que","t":"¿Qué es un accidente del trabajo?","x":"Según la Ley 16.744 (art. 5), es toda <b>lesión que sufres a causa o con ocasión del trabajo</b> y que te produce incapacidad o la muerte. En {EMP}: un corte en la sierra, un panel que golpea un pie, una torcedura al bajar del camión, un lumbago al levantar un saco. También cuenta si ocurre en una tarea que te encargaron fuera de la planta, como un despacho."},{"s":"accidente_avisa","t":"Avisa de inmediato","x":"<b>Por pequeño que sea, avisa a tu jefatura de inmediato</b>, el mismo día y antes de irte. Un corte “sin importancia” puede infectarse; un tirón en la espalda puede empeorar mañana. Si no avisas, después cuesta probar que ocurrió en el trabajo y puedes terminar atendiéndote por Fonasa o tu Isapre, pagando tú. No te atiendas por tu cuenta en otro lugar.","k":"Por pequeño que sea: avisa de inmediato a tu jefatura."},{"s":"ind_avisa","t":"¿Dónde me atiendo?","x":"<ul><li>Te atiendes en la <b>ACHS</b>. Ante una urgencia, llama al <b>1404</b>.</li><li>Pregunta hoy a tu jefatura cuál es el centro ACHS más cercano a la planta.</li><li>Al llegar, <b>di que fue un accidente del trabajo</b>, para que te atiendan por el seguro.</li><li>Si la lesión es grave, llama al <b>131</b> (SAMU) o al <b>1404</b>.</li></ul>Lleva tu cédula de identidad."},{"s":"accidente_diat","t":"La DIAT: la denuncia del accidente","x":"La empresa debe presentar la <b>DIAT</b> (Denuncia Individual de Accidente del Trabajo) en la ACHS dentro de las <b>24 horas</b> desde que sabe del accidente. <b>Si no la hace, la puedes hacer tú</b>, un familiar, el médico que te atendió o el Comité Paritario. Pide siempre una copia o el número de la denuncia. Sin DIAT no queda registro del accidente."},{"s":"accidente_trayecto","t":"Accidente de trayecto y cómo acreditarlo","x":"La Ley 16.744 también cubre el accidente en el <b>trayecto directo, de ida o regreso, entre tu habitación y el trabajo</b>. Si te desvías por asuntos personales, ya no es trayecto directo. Debes poder <b>acreditarlo</b>:<ul><li>Atiéndete en la ACHS lo antes posible y avisa a tu jefatura.</li><li>Si fue choque o atropello, deja <b>constancia en Carabineros</b>.</li><li>Anota nombre y teléfono de <b>testigos</b>.</li></ul>"},{"s":"accidente_companero","t":"Si un compañero se accidenta","x":"<ul><li><b>No te expongas</b> al mismo peligro: detén la máquina solo si es seguro.</li><li>Si cayó de altura, del camión o recibió un golpe fuerte, <b>no lo muevas</b>: puede tener una lesión de columna. Solo se mueve si hay fuego u otro peligro inmediato.</li><li>Llama al <b>131</b> o al <b>1404</b> y avisa a la jefatura.</li><li>Acompáñalo, abrígalo y háblale hasta que llegue la ayuda.</li></ul>","k":"Primero tu seguridad; si cayó o se golpeó fuerte, no lo muevas."},{"s":"ind_grave","t":"Accidente grave: paraliza, delimita y avisa","x":"Según la SUSESO, es <b>grave</b> el accidente con caída de más de 1,8 m, amputación, atrapamiento, pérdida de conocimiento, o que requiere rescate o reanimación, entre otros. En ese caso:<ul><li><b>Paraliza</b> la tarea.</li><li><b>Delimita</b> el lugar y no muevas máquinas ni materiales, salvo para rescatar.</li><li><b>Avisa</b> de inmediato a la jefatura.</li></ul>La empresa debe suspender la faena e informar a la Inspección del Trabajo y a la SEREMI de Salud."},{"s":"accidente_casi","t":"Los “casi accidentes” también se avisan","x":"Un pallet que cae cerca, un resbalón que no terminó en caída, la grúa que pasó rozando. <b>No pasó nada esta vez</b>, pero la causa sigue ahí. Avisa el casi accidente a tu jefatura o al Delegado de SST. La empresa <b>investiga</b> los accidentes y casi accidentes para <b>corregir la causa, no para buscar culpables</b>: cuenta lo que pasó con la verdad."},{"s":"accidente_auto","t":"Autocuidado: el accidente empieza con una decisión","x":"La mayoría de los accidentes se relacionan con una <b>acción insegura</b>: apurarse, saltarse un paso, no usar el EPP, acercar la mano a la sierra para “ganar tiempo”. La decisión segura: <b>detenerte, usar el empujador, pedir ayuda</b>. Y si un compañero esconde una lesión (“no es nada, que nadie sepa”), anímalo a avisar: ocultarla solo lo perjudica a él."}],"quiz":[{"s":"accidente_avisa","v":[{"q":"Me hice un corte pequeño con un tablero OSB. ¿Qué hago?","o":["Aviso a mi jefatura de inmediato","Me pongo una curita y sigo, porque es poco","Lo aviso solo si se infecta","Lo aviso al día siguiente, al llegar"],"w":"Por pequeño que sea, se avisa de inmediato."},{"q":"¿Por qué hay que avisar un accidente el mismo día, aunque parezca leve?","o":["Porque después cuesta probar que ocurrió en el trabajo","Porque así la empresa paga una multa menor","Porque después la ACHS ya no atiende cortes","Porque así se evita hacer la DIAT"],"w":"Lo que no se avisa a tiempo es difícil de acreditar."},{"q":"Un accidente leve se puede avisar a fin de semana, cuando se junten varios.","vf":false,"w":"Falso. Se avisa de inmediato, el mismo día."}]},{"s":"accidente_ley","v":[{"q":"La atención por un accidente del trabajo en la ACHS es gratuita para el trabajador.","vf":true,"w":"Verdadero. La cubre el seguro de la Ley 16.744."},{"q":"¿Qué cubre el seguro de la Ley 16.744?","o":["Accidentes del trabajo, de trayecto y enfermedades profesionales","Solo accidentes dentro de la planta","Solo los accidentes graves que requieren hospitalización","Cualquier enfermedad del trabajador"],"w":"Cubre las tres situaciones ligadas al trabajo."},{"q":"Estás con licencia por un accidente del trabajo. ¿Quién paga esos días?","o":["El seguro de la Ley 16.744, mediante un subsidio","Nadie: son días sin sueldo","Yo, descontando mis días de vacaciones","Mi Isapre o Fonasa"],"w":"El seguro paga un subsidio por los días de licencia."}]},{"s":"accidente_diat","v":[{"q":"Si la empresa no hace la DIAT de mi accidente, ¿qué puedo hacer?","o":["Hacerla yo directamente en la ACHS","Nada, pierdo la cobertura","Esperar un mes a que la hagan","Dejar solo una constancia en Carabineros"],"w":"La DIAT la debe hacer la empresa, pero si no la hace, puedes presentarla tú."},{"q":"¿En qué plazo debe la empresa presentar la DIAT?","o":["Dentro de 24 horas desde que sabe del accidente","Dentro de 30 días","Al cierre del mes","Solo si el trabajador queda con licencia médica"],"w":"La denuncia debe hacerse dentro de 24 horas."},{"q":"¿Qué es la DIAT?","o":["La denuncia individual del accidente del trabajo","El certificado de alta médica","La licencia médica por accidente","El informe de investigación del accidente"],"w":"Sin DIAT no queda registro del accidente."}]},{"s":"accidente_trayecto","v":[{"q":"Un accidente de trayecto es el que ocurre:","o":["En el trayecto directo, de ida o regreso, entre la habitación y el trabajo","En cualquier viaje, incluso el fin de semana","Solo dentro de la planta","En el camino al trabajo, aunque antes pases a otro lugar por asuntos personales"],"w":"Así lo define la Ley 16.744: trayecto directo."},{"q":"Al salir del trabajo pasas a la casa de un amigo y después te caes camino a tu casa. ¿Es accidente de trayecto?","o":["No, porque te desviaste por un asunto personal","Sí, cualquier caída después del turno lo es","Sí, si fue el mismo día","Solo si ibas en bicicleta"],"w":"El desvío por asuntos personales interrumpe el trayecto directo."},{"q":"Si te caes de la bicicleta en el camino directo de tu casa a la planta, es accidente de trayecto.","vf":true,"w":"Verdadero. Ocurrió en el trayecto directo entre la habitación y el trabajo."}]},{"s":"accidente_pruebas","v":[{"q":"¿Qué ayuda a acreditar un accidente de trayecto?","o":["Constancia en Carabineros, testigos y atención rápida","Contarlo una semana después","Una foto del lugar tomada al día siguiente","Basta con decírselo a la jefatura"],"w":"Las pruebas demuestran que ocurrió en el camino directo."},{"q":"Te atropellan camino a la planta. Además de atenderte, ¿qué conviene hacer?","o":["Dejar constancia en Carabineros y anotar testigos","Arreglarme con el conductor y no decir nada","Esperar el alta para avisar en el trabajo","Atenderme en mi Isapre para no perder tiempo"],"w":"La constancia y los testigos respaldan tu caso."},{"q":"¿Por qué conviene atenderse pronto en la ACHS tras un accidente de trayecto?","o":["Porque ayuda a demostrar que ocurrió en el camino","Porque después la ACHS cobra la atención","Porque así no hay que avisar a la jefatura","Porque el seguro cubre solo el primer día"],"w":"La atención rápida es parte de la prueba del trayecto."}]},{"s":"accidente_companero","v":[{"q":"Un compañero cayó del camión y se queja de la espalda. ¿Qué haces?","o":["No lo muevo, llamo al 131 o al 1404 y aviso","Lo levanto rápido para llevarlo en auto","Le digo que se pare y camine","Lo siento para que respire mejor"],"w":"Podría tener una lesión de columna: no se mueve."},{"q":"Un compañero cayó desde la plataforma del camión; está consciente, pero adolorido. ¿Qué haces?","o":["Lo dejo quieto, pido ayuda y lo acompaño","Lo ayudo a pararse para ver si puede caminar","Lo llevo en mi auto al consultorio","Lo siento apoyado contra el camión"],"w":"Moverlo puede agravar una lesión que no se ve."},{"q":"¿Cuándo se puede mover a un compañero que cayó de altura?","o":["Solo si hay fuego u otro peligro inmediato","Siempre, para ponerlo cómodo","Cuando él diga que se siente bien","Cuando pasen cinco minutos"],"w":"Solo un peligro inmediato justifica moverlo."}]},{"s":"accidente_ocultar","v":[{"q":"Un compañero se cortó y dice “no es nada, que nadie sepa”. ¿Qué le aconsejas?","o":["Que avise de inmediato a la jefatura","Que se ponga una curita y siga","Que espere a ver si empeora","Que se atienda por su cuenta en la farmacia"],"w":"Avisar permite atenderse en la ACHS y hacer la DIAT."},{"q":"¿Qué arriesga quien oculta una lesión del trabajo?","o":["Que después cueste probarla y quede sin cobertura","Nada, el seguro la cubre igual en cualquier momento","Solo una amonestación verbal","Que le descuenten el día"],"w":"Sin aviso ni registro, la lesión es difícil de acreditar."},{"q":"Atenderse una lesión del trabajo por Fonasa o la Isapre es lo mismo que atenderse en la ACHS.","vf":false,"w":"Falso. Por el seguro de la Ley 16.744 la atención es gratuita en la ACHS; por la previsión común puedes terminar pagando tú."}]},{"s":"accidente_casi","v":[{"q":"Un pallet cayó cerca de mí pero no me golpeó. Igual debo avisarlo.","vf":true,"w":"Verdadero. Los casi accidentes muestran una causa que hay que corregir."},{"q":"Un pallet cayó del rack cerca de un compañero y nadie se lesionó. ¿Por qué se debe avisar?","o":["Porque la causa sigue ahí y puede lesionar a otro","Porque así se descuenta el pallet","Porque la ACHS lo exige para pagar","No es necesario, porque nadie se lesionó"],"w":"Cada casi accidente avisa dónde estará el próximo."},{"q":"La grúa pasó rozando a un compañero sin tocarlo. ¿Qué corresponde?","o":["Avisarlo como casi accidente","Nada, porque no hubo lesión","Comentarlo solo con el operador","Avisarlo solo si se repite"],"w":"Se investiga para corregir la causa, no para buscar culpables."}]},{"s":"ind_grave","v":[{"q":"Un compañero cae desde más de 1,8 m y pierde el conocimiento. Además de pedir ayuda, ¿qué se hace con el lugar?","o":["Se paraliza la tarea y se delimita el lugar","Se limpia rápido para seguir trabajando","Se mueven los materiales para despejar","Se sigue trabajando en el resto de la zona"],"w":"Es un accidente grave: paralizar, delimitar y avisar."},{"q":"¿Cuál de estos es un accidente grave según la SUSESO?","o":["Una amputación o un atrapamiento","Un corte superficial en un dedo","Un golpe leve en el brazo","Una torcedura al bajar un escalón"],"w":"Amputación, atrapamiento, caída de más de 1,8 m o pérdida de conocimiento son graves."},{"q":"Ocurrió un accidente grave. ¿Cuál es el orden correcto?","o":["Paralizar, delimitar y avisar","Avisar, limpiar y seguir","Delimitar, mover la máquina y avisar","Seguir trabajando y avisar al final"],"w":"El lugar no se altera, salvo para rescatar."}]},{"s":"accidente_donde","v":[{"q":"¿Dónde te atiendes si tienes un accidente del trabajo en {EMP}?","o":["En la ACHS","En el consultorio, por Fonasa","En la clínica de mi Isapre","En la farmacia más cercana"],"w":"{EMP} está adherida a la ACHS: ahí te atiende el seguro."},{"q":"Llegas a la ACHS por una lesión en la planta. ¿Qué debes decir?","o":["Que fue un accidente del trabajo","Solo mis síntomas, sin decir dónde ocurrió","Que fue en mi casa, para no complicar a la empresa","Que vengo por una consulta general"],"w":"Así te atienden por el seguro de la Ley 16.744."},{"q":"¿Qué número de la ACHS puedes llamar ante una urgencia?","o":["1404","131","132","133"],"w":"El 1404 es el número de la ACHS; 131 es SAMU, 132 Bomberos y 133 Carabineros."}]}]},{"id":"incendios","sec":"todos","title":"Prevención de incendios y uso del extintor","thumb":"incendios_ext","mins":5,"learn":[{"s":"incendios_tri","t":"El triángulo del fuego","x":"El fuego necesita tres cosas a la vez: <b>combustible</b> (lo que arde: EPS, OSB, cartón, solventes), <b>oxígeno</b> (el aire) y <b>calor</b> (una chispa, una llama, un cable recalentado, un cigarro). <b>Si quitas una, no hay fuego.</b> Prevenir es mantenerlas separadas. El extintor apaga quitando el calor o cubriendo el combustible para cortarle el oxígeno."},{"s":"incendios_eps","t":"En la planta sobra combustible","x":"<b>El EPS (plumavit) es combustible</b>: con llama o chispas se derrite, gotea encendido, arde muy rápido y genera <b>humo negro y tóxico</b>. También arden el OSB, la madera, el cartón, los envoltorios y muchos adhesivos y solventes. En un incendio, el humo es lo que más daña: quita la visibilidad y se respira en segundos. Por eso <b>no se fuma en ninguna parte de la planta</b>."},{"s":"incendios_viruta","t":"Polvo y viruta: combustible escondido","x":"El polvo y la viruta de <b>OSB y EPS</b> que se acumulan bajo las sierras, la rebajadora y en los rincones <b>arden fácilmente</b>: basta una chispa del esmeril o un motor recalentado. Por eso se retiran <b>durante el turno</b>, aspirando o humedeciendo antes de barrer, y los retazos van al contenedor. Mantén limpios también motores y tableros: el polvo encima los recalienta."},{"s":"incendios_chispasOk","t":"Chispas del esmeril","x":"Las chispas del esmeril o la soldadura saltan varios metros y pueden quedar <b>encendidas sin que se vea</b> en la viruta o el EPS.<ul><li><b>Antes:</b> retira el material combustible o cúbrelo, y ten un extintor a mano.</li><li><b>Durante:</b> dirige las chispas lejos de paneles y viruta.</li><li><b>Al terminar:</b> revisa que no quede nada humeando, y vuelve a mirar un rato después.</li></ul>"},{"s":"incendios_enchufe","t":"Enchufes y cigarros","x":"<ul><li><b>No sobrecargues enchufes</b> ni conectes zapatillas o alargadores en cadena.</li><li>Si un enchufe o cable está <b>caliente, derretido, pelado o huele a quemado</b>, desconéctalo si es seguro y avisa.</li><li>No uses extensiones domésticas para las máquinas.</li><li><b>No fumes</b> dentro de la planta ni cerca de combustibles; solo en el lugar habilitado que indique la jefatura.</li></ul>"},{"s":"incendios_clases","t":"Clases de fuego","x":"<ul><li><b>A:</b> sólidos (madera, OSB, EPS, cartón).</li><li><b>B:</b> líquidos inflamables (solventes, combustibles).</li><li><b>C:</b> equipos eléctricos energizados (tableros, motores).</li><li><b>D:</b> metales combustibles.</li></ul>Cada extintor indica en su etiqueta para qué clases sirve; los de polvo químico seco multipropósito sirven para A, B y C. <b>Nunca uses agua sobre un fuego eléctrico</b> ni sobre líquidos inflamables."},{"s":"incendios_acceso","t":"Extintores libres y a la vista","x":"La empresa debe tener extintores <b>del tipo adecuado</b>, en lugares de <b>fácil acceso</b>, señalizados y libres de obstáculos (DS 594, arts. 45 a 48). Tu parte:<ul><li>Nunca dejes paneles ni pallets delante.</li><li>Conoce dónde está el más cercano a tu puesto.</li><li>Avisa si falta, si la aguja del manómetro no está en verde o si tiene el sello roto.</li></ul>"},{"s":"incendios_ext","t":"Cómo usar el extintor","x":"Úsalo solo frente a un <b>amago</b> (fuego pequeño que recién empieza), si sabes usarlo y sin arriesgarte. Primero <b>da la alarma a viva voz</b>. Ponte a unos <b>2 a 3 metros</b>; en el patio, con el viento a tu espalda.<ul><li><b>1. Saca el seguro.</b></li><li><b>2. Apunta</b> a la <b>base</b> del fuego, no a las llamas.</li><li><b>3. Presiona</b> la manilla.</li><li><b>4. Barre</b> de lado a lado.</li></ul>","k":"Saca el seguro, apunta a la base, presiona y barre."},{"s":"incendios_retirada","t":"Distancia y retirada","x":"<ul><li><b>Mantén distancia</b>: acércate solo lo necesario.</li><li>Ten siempre la <b>salida a tu espalda</b>, para no quedar atrapado.</li><li><b>Nunca le des la espalda al fuego</b>, ni siquiera cuando parece apagado: retrocede mirándolo, porque puede reavivarse.</li><li>Un extintor portátil se descarga en <b>pocos segundos</b>. <b>Si no se apaga, evacúa</b> y llama al <b>132</b>.</li></ul>","k":"Si no se apaga en segundos, evacúa y llama al 132."},{"s":"incendios_self","t":"Autocuidado: incendios","x":"La acción insegura típica: <b>esmerilar junto a la viruta</b>, sobrecargar un enchufe, fumar “escondido” o querer apagar solo un fuego que ya creció. Decide seguro: <b>da la alarma primero</b>, aunque creas que puedes apagarlo, y <b>avisa</b> las condiciones inseguras, como un extintor tapado o descargado, viruta acumulada o un cable pelado. Ningún panel vale tu vida."}],"quiz":[{"s":"incendios_tri","v":[{"q":"¿Qué tres cosas necesita el fuego?","o":["Combustible, oxígeno y calor","Combustible, agua y calor","Oxígeno, electricidad y madera","Calor, humo y viento"],"w":"Es el triángulo del fuego: si quitas una, el fuego se apaga."},{"q":"Al retirar la viruta bajo la sierra, ¿qué lado del triángulo del fuego estás quitando?","o":["El combustible","El oxígeno","El calor","Ninguno, solo es aseo"],"w":"La viruta es combustible: sin ella, una chispa no tiene qué encender."},{"q":"Si se quita uno de los tres elementos del triángulo, el fuego no puede existir.","vf":true,"w":"Verdadero. Por eso prevenir es mantenerlos separados."}]},{"s":"incendios_eps","v":[{"q":"El plumavit (EPS) no se quema, solo se derrite.","vf":false,"w":"Falso. Se derrite, gotea encendido, arde rápido y genera humo negro tóxico."},{"q":"En un incendio con EPS, ¿qué es lo que más daña a las personas?","o":["El humo negro y tóxico, que se respira en segundos","El agua que se usa para apagar las llamas","El ruido de la alarma","El olor que queda en la ropa"],"w":"El humo quita la visibilidad y se respira muy rápido."},{"q":"¿Cuál de estos materiales de la planta es combustible?","o":["Todos: EPS, OSB y cartón","Solo el OSB, porque es madera","Solo el cartón de los envoltorios","Ninguno, porque son materiales industriales"],"w":"En la planta casi todo lo que se almacena puede arder."}]},{"s":"incendios_extMal","v":[{"q":"Un compañero apunta el extintor a la punta de las llamas. ¿Qué debe corregir?","o":["Apuntar a la base del fuego","Acercarse más a las llamas","Disparar en ráfagas hacia arriba","Esperar a que el fuego baje solo"],"w":"Se apunta a la base, donde está el combustible."},{"q":"¿Por qué el chorro del extintor se dirige a la base del fuego?","o":["Porque ahí está el combustible que alimenta las llamas","Porque así se gasta menos polvo","Porque las llamas altas son las más peligrosas","Porque así el humo se va hacia arriba"],"w":"Apagando la base se corta lo que alimenta el fuego."},{"q":"¿Hacia dónde se apunta el extintor?","o":["A la base del fuego","Al centro de las llamas","Al humo","A la parte más alta del fuego"],"w":"Las llamas son el efecto; la base es la causa."}]},{"s":"incendios_ext","v":[{"q":"¿Cuál es el orden correcto para usar el extintor?","o":["Sacar el seguro, apuntar a la base, presionar y barrer","Presionar, apuntar a las llamas y después sacar el seguro","Apuntar a la base, sacar el seguro, barrer y presionar","Sacar el seguro, presionar y apuntar a las llamas sin moverse"],"w":"Seguro, apuntar a la base, presionar y barrer de lado a lado."},{"q":"Ves un amago en un cartón. ¿Qué haces antes de usar el extintor?","o":["Doy la alarma a viva voz","Voy a buscar a la jefatura a la oficina","Termino lo que estaba haciendo","Busco primero un balde de agua"],"w":"Avisar primero permite que otros se protejan y llegue ayuda."},{"q":"¿A qué distancia aproximada te pones para usar el extintor en un amago?","o":["Entre 2 y 3 metros","A medio metro","A 10 metros","Pegado a las llamas"],"w":"Lo bastante cerca para alcanzar la base, sin exponerte."}]},{"s":"incendios_retirada","v":[{"q":"Intentaste apagar un amago y no se apaga en segundos. ¿Qué haces?","o":["Me retiro sin darle la espalda, evacúo y aviso","Sigo intentando hasta que se acabe el extintor","Busco un balde de agua","Voy por un segundo extintor y sigo solo"],"w":"Si no se apaga en segundos, se evacúa. Tu vida vale más que la planta."},{"q":"Al usar el extintor, ¿dónde debe quedar la salida?","o":["A mi espalda","Detrás del fuego","A un costado, lejos","Da lo mismo"],"w":"Así siempre tienes por dónde escapar."},{"q":"Una vez apagado el fuego, puedes darle la espalda y retirarte de inmediato.","vf":false,"w":"Falso. Se retrocede mirándolo, porque puede reavivarse."}]},{"s":"incendios_clases","v":[{"q":"Un fuego en un tablero eléctrico energizado es de clase:","o":["C","A","B","D"],"w":"Clase C: equipos eléctricos energizados."},{"q":"Arde un retazo de OSB. ¿Qué clase de fuego es?","o":["A","B","C","D"],"w":"Clase A: sólidos como madera, OSB, EPS y cartón."},{"q":"Hay fuego en un motor energizado. ¿Qué NO debes usar?","o":["Agua","Un extintor de polvo químico seco ABC","Un extintor cuya etiqueta indique clase C","El corte de energía del tablero, si es seguro"],"w":"El agua conduce la electricidad: nunca sobre un fuego eléctrico."}]},{"s":"incendios_chispas","v":[{"q":"Vas a esmerilar cerca de paneles y viruta. ¿Qué haces antes?","o":["Retiro o cubro el combustible y dirijo las chispas lejos","Esmerilo rápido para que salten menos chispas","Mojo el esmeril para que no saque chispas","Nada: las chispas se apagan solas al caer"],"w":"Una chispa puede quedar encendida en la viruta o el EPS."},{"q":"Terminaste de esmerilar junto a una ruma de EPS. ¿Qué haces?","o":["Reviso que no quede nada humeando, también un rato después","Me voy de inmediato, porque ya no saltan chispas","Barro las chispas hacia la viruta","Guardo el esmeril y cierro la zona"],"w":"Una chispa escondida puede encender el material minutos después."},{"q":"Una chispa del esmeril puede quedar encendida en la viruta sin que se vea.","vf":true,"w":"Verdadero. Por eso se revisa al terminar y un rato después."}]},{"s":"incendios_viruta","v":[{"q":"¿Por qué se retira la viruta bajo la sierra durante el turno?","o":["Porque arde fácilmente con una chispa","Solo para que la planta se vea ordenada","Porque desgasta el disco de la sierra","Porque la viruta mancha los paneles"],"w":"El polvo y la viruta acumulados son combustible escondido."},{"q":"¿Cómo se retira la viruta acumulada?","o":["Aspirando o humedeciendo antes de barrer","Soplándola con aire comprimido","Barriéndola en seco hacia un rincón","Esperando la limpieza del fin de semana"],"w":"Así no se levanta polvo ni queda acumulada."},{"q":"¿Por qué hay que mantener sin polvo los motores y tableros?","o":["Porque el polvo encima los recalienta y puede encenderse","Porque el polvo raya la pintura","Porque así se ven mejor en las visitas de clientes","Porque el polvo hace más ruido"],"w":"Calor más combustible: la mitad del triángulo del fuego."}]},{"s":"incendios_acceso","v":[{"q":"Hay pallets delante del extintor. ¿Qué haces?","o":["Los saco o aviso para que quede despejado","Nada: en una emergencia los muevo","Pongo un letrero sobre los pallets","Muevo el extintor detrás de los pallets"],"w":"Los extintores deben estar en lugares de fácil acceso y libres de obstáculos."},{"q":"Revisas el extintor de tu sector y la aguja del manómetro está fuera del verde. ¿Qué haces?","o":["Aviso a mi jefatura para que lo revisen o recarguen","Nada: si tiene el sello puesto, igual sirve","Lo agito para que suba la aguja","Lo cambio por el de otro sector"],"w":"Aguja fuera del verde: el extintor puede no funcionar."},{"q":"Según el DS 594, ¿cómo deben estar los extintores?","o":["Del tipo adecuado, señalizados y en lugares de fácil acceso","Guardados en bodega para que no se dañen","Solo en la oficina, junto al botiquín","Detrás de las rumas, protegidos de golpes de la grúa"],"w":"Un extintor que no se ve o no se alcanza no sirve en una emergencia."}]},{"s":"incendios_enchufe","v":[{"q":"¿Cuál es una práctica segura con los enchufes?","o":["No sobrecargarlos ni conectar zapatillas en cadena","Conectar varias zapatillas para no gastar enchufes","Tapar con cinta un enchufe que está caliente","Usar extensiones domésticas en las máquinas"],"w":"La sobrecarga recalienta los cables y puede iniciar un incendio."},{"q":"Un enchufe de la zona de corte está caliente y huele a quemado. ¿Qué haces?","o":["Lo desconecto si es seguro y aviso","Sigo usándolo hasta terminar el turno","Le echo agua para enfriarlo","Conecto la máquina en una zapatilla al lado"],"w":"Un enchufe caliente es una fuente de calor junto a mucho combustible."},{"q":"¿Dónde se puede fumar en {EMP}?","o":["Solo en el lugar habilitado que indique la jefatura","En la planta, si las máquinas están detenidas","En el patio, junto a las rumas de EPS","En la bodega, si hay ventilación"],"w":"El EPS y el OSB arden muy rápido: no se fuma en la planta."}]}]},{"id":"emergencias","sec":"todos","title":"Emergencias, sismos y evacuación","thumb":"quake","learn":[{"s":"emergencias_tipos","t":"¿Qué emergencias pueden ocurrir?","x":"<ul><li><b>Incendio:</b> EPS, OSB y adhesivos arden rápido.</li><li><b>Sismo:</b> pueden caer paneles desde rumas y racks.</li><li><b>Corte de luz</b> con máquinas funcionando.</li><li><b>Fuga o derrame</b> de un producto químico o del gas de una grúa.</li><li><b>Persona lesionada</b> o accidente grave.</li></ul>Tsunami no aplica: Los Ángeles está en el interior. Pensar antes qué harías te ahorra segundos valiosos."},{"s":"emergencias_plan","t":"El plan de emergencia","x":"La empresa debe tener un <b>plan de emergencia</b> y practicarlo con simulacros. Tú debes conocer:<ul><li>Cómo suena la <b>alarma</b> y cómo se da.</li><li>Las <b>vías de evacuación</b> desde tu puesto, y una alternativa.</li><li>La <b>zona de seguridad</b>: pregunta a tu jefatura cuál es.</li><li>Dónde están los extintores y el botiquín.</li><li>Quién dirige la evacuación en tu turno.</li></ul>"},{"s":"emergencias_sismo","t":"Durante un sismo","x":"SENAPRED recomienda: <b>“Agáchate, cúbrete y afírmate”</b>. Aléjate de racks, rumas de paneles y ventanas, que pueden caer o quebrarse. <b>No corras</b> mientras se mueve el piso. Si estás en una máquina, detenla. Si operas la grúa horquilla: <b>detente, baja la carga al piso y frena</b>. Evacúa cuando termine el movimiento o te lo indiquen, atento a las réplicas.","k":"Durante el sismo: agáchate, cúbrete y afírmate, lejos de racks y rumas."},{"s":"emergencias_incendio","t":"Incendio","x":"<ul><li><b>Da la alarma</b> de inmediato, a viva voz y por el medio que indique el plan.</li><li>Solo si es un <b>amago</b> y estás capacitado, usa el extintor <b>con la salida a tu espalda</b>.</li><li>Si el fuego crece, <b>evacúa</b> y llama al <b>132</b>.</li><li>El EPS genera <b>humo negro y tóxico</b>: avanza agachado, donde hay más aire limpio.</li><li>Antes de abrir una puerta, tócala con el dorso de la mano: si está caliente, busca otra salida.</li></ul>"},{"s":"emergencias_luz","t":"Corte de luz","x":"Quédate quieto hasta que veas bien. <b>No metas las manos</b>: el disco de la sierra sigue girando unos segundos después del corte. <b>Apaga tu máquina</b> para que no parta sola cuando vuelva la energía. Si operas la grúa, detente y baja la carga. Camina despacio, con la linterna del celular si la necesitas, y espera instrucciones de tu jefatura."},{"s":"emergencias_fuga","t":"Fuga o derrame","x":"Aléjate y aleja a los demás. <b>Avisa</b> a tu jefatura. No toques el producto sin el EPP que indica su <b>HDS</b>, y si no sabes cómo manejarlo, no lo intentes. Si huele a gas, por ejemplo, desde el cilindro de una grúa, <b>no hagas chispas</b>: no enciendas ni apagues interruptores, no uses el celular cerca y evacúa la zona."},{"s":"emergencias_llamar","t":"Cómo pedir ayuda","x":"<ul><li><b>131</b> SAMU. <b>132</b> Bomberos. <b>133</b> Carabineros. <b>1404</b> ACHS.</li><li>Da la <b>dirección exacta</b> de la planta y una referencia.</li><li>Di qué pasó, cuántos lesionados hay y si están conscientes.</li><li><b>No cortes</b> hasta que te lo indiquen.</li><li>Pide que alguien espere a la ambulancia en la entrada.</li></ul>Avisa también a tu jefatura."},{"s":"emergencias_evac","t":"Evacuación","x":"Cuando se indique, sal por la <b>vía de evacuación</b>: camina rápido, <b>sin correr</b>, sin empujar y sin devolverte. Si puedes hacerlo en segundos, deja tu máquina apagada. <b>No uses el celular para grabar</b>, no vuelvas por tus cosas y ayuda a visitas, contratistas o a quien lo necesite. Sigue las señales verdes hasta la zona de seguridad."},{"s":"emergencias_conteo","t":"En la zona de seguridad","x":"Ve al punto de encuentro y quédate ahí. Se <b>cuenta a las personas</b>: avisa si falta alguien o si viste a alguien herido o atrapado, y dónde. <b>No vuelvas a entrar</b> hasta que se autorice. Si alguien falta, informa a quien dirige la evacuación o a Bomberos: no vuelvas tú a buscarlo, porque puedes terminar siendo otra víctima.","k":"Nadie vuelve a entrar hasta que se autorice."},{"s":"emergencias_auto","t":"Autocuidado en emergencias","x":"Las acciones inseguras típicas: <b>tapar salidas o extintores</b> con pallets, volver por la mochila, grabar con el celular o correr durante el sismo. La decisión segura: mantener las salidas despejadas, participar en serio en los simulacros y seguir el plan. <b>Avisa</b> si ves una salida bloqueada o con llave, o un extintor sin carga: una salida despejada hoy puede salvarte mañana."}],"quiz":[{"s":"emergencias_sismo","v":[{"q":"Durante un sismo, SENAPRED recomienda:","o":["Agáchate, cúbrete y afírmate","Corre a la salida más cercana","Ponte junto al rack más firme","Sal al patio apenas empiece"],"w":"Protege tu cabeza y aléjate de lo que puede caer."},{"q":"Empieza un sismo fuerte mientras ordenas paneles junto al rack. ¿Qué haces?","o":["Me alejo del rack, me agacho, me cubro y me afirmo","Sujeto los paneles del rack para que no caigan","Corro hacia la salida","Me quedo junto al rack, que es firme"],"w":"Racks y rumas pueden soltar su carga durante el sismo."},{"q":"¿Cuándo se evacúa en un sismo?","o":["Cuando termina el movimiento o lo indican","Apenas se siente el primer movimiento","Solo si se corta la luz","Nunca: hay que quedarse en el puesto"],"w":"Moverse durante el sismo provoca caídas y golpes."}]},{"s":"emergencias_sismo","v":[{"q":"Durante el movimiento de un sismo, lo correcto es correr hacia la salida.","vf":false,"w":"Falso. Correr mientras se mueve el piso provoca caídas y golpes."},{"q":"¿Por qué no se debe correr mientras se mueve el piso?","o":["Porque provoca caídas y golpes","Porque cansa antes de evacuar","Porque así no se escucha la alarma","Porque está prohibido por el reglamento"],"w":"El piso en movimiento hace perder el equilibrio."},{"q":"¿De qué debes alejarte durante un sismo en la planta?","o":["De racks, rumas de paneles y ventanas","De las paredes interiores","De los compañeros","De la zona de seguridad"],"w":"Son lo que puede caer o quebrarse."}]},{"s":"emergencias_grua","v":[{"q":"Si operas la grúa horquilla durante un sismo, debes:","o":["Detenerte, bajar la carga al piso y frenar","Levantar la carga para protegerla","Acelerar para salir de la nave","Seguir hasta dejar la carga en el rack"],"w":"Una carga en altura puede caer sobre alguien."},{"q":"¿Por qué el operador de grúa debe bajar la carga durante un sismo?","o":["Porque una carga en altura puede caer sobre alguien","Porque así la grúa gasta menos gas al detenerse","Porque así puede bajarse corriendo","Porque así termina antes la tarea"],"w":"Con la carga abajo, la grúa es más estable y nada cae desde altura."},{"q":"Si un sismo te sorprende operando la grúa, lo correcto es detenerte, bajar la carga y frenar.","vf":true,"w":"Verdadero. Así evitas que la carga caiga o que la grúa se mueva."}]},{"s":"emergencias_llamar","v":[{"q":"¿Cuál es el número de Bomberos?","o":["132","131","133","1404"],"w":"131 SAMU, 132 Bomberos, 133 Carabineros, 1404 ACHS."},{"q":"Sale humo de la bodega de EPS. ¿A qué número llamas?","o":["132","131","133","1404"],"w":"Un incendio se informa a Bomberos, al 132."},{"q":"Al llamar a emergencias, ¿qué dato es indispensable dar primero?","o":["La dirección exacta de la planta","Mi RUT y mi cargo","Solo el nombre de la empresa","La hora en que empezó todo"],"w":"Sin la dirección exacta, la ayuda no llega."}]},{"s":"emergencias_llamar","v":[{"q":"Hay un lesionado grave. ¿A qué número llamas para pedir una ambulancia del SAMU?","o":["131","132","133","134"],"w":"El 131 es el SAMU."},{"q":"Llamaste al 131. ¿Cuándo cortas?","o":["Cuando la operadora me lo indique","Apenas doy la dirección","Después de decir qué pasó","Cuando escucho la sirena"],"w":"La operadora puede necesitar más datos o darte instrucciones."},{"q":"¿Qué información ayuda más al SAMU cuando llamas?","o":["Dirección exacta, qué pasó, cuántos lesionados y si están conscientes","Solo que hubo un accidente en una empresa","El nombre y el teléfono del supervisor","La marca y el modelo de la máquina"],"w":"Con esos datos envían la ayuda adecuada."}]},{"s":"emergencias_luz","v":[{"q":"Se corta la luz mientras usas la sierra. ¿Qué haces?","o":["Apago mi máquina y no meto las manos","Saco el panel con la mano mientras el disco se detiene","Camino rápido hacia la salida a oscuras","Dejo la máquina encendida para seguir cuando vuelva la luz"],"w":"Así evitas cortes y que la máquina parta sola al volver la energía."},{"q":"¿Por qué hay que apagar la máquina cuando se corta la luz?","o":["Para que no parta sola cuando vuelva la energía","Para ahorrar electricidad","Para que se enfríe el motor de la máquina","Porque así lo pide el SAMU"],"w":"Una máquina que arranca sola puede atrapar a alguien desprevenido."},{"q":"Cuando se corta la luz, el disco de la sierra se detiene de inmediato.","vf":false,"w":"Falso. Sigue girando unos segundos: no metas las manos."}]},{"s":"emergencias_bloqueo","v":[{"q":"Ves pallets delante del extintor y de la salida de emergencia. ¿Qué haces?","o":["Los despejo si puedo y aviso a mi jefatura","Los dejo: en una emergencia se mueven rápido","Dejo un espacio pequeño para pasar","Pongo un letrero que diga salida"],"w":"Salidas y extintores deben estar siempre despejados."},{"q":"¿Cómo deben estar las salidas de emergencia durante el turno?","o":["Despejadas y sin llave","Cerradas con llave para evitar robos","Abiertas solo en los simulacros","Con material liviano delante"],"w":"En una emergencia no hay tiempo para buscar llaves ni mover cosas."},{"q":"Tapar una salida de emergencia con paneles es:","o":["Una acción insegura","Un control administrativo","Algo aceptable por un rato","Responsabilidad solo de la jefatura"],"w":"Es una decisión que pone en riesgo a todos."}]},{"s":"emergencias_auto","v":[{"q":"Ya evacuaste y recuerdas que dejaste tu celular en el puesto. ¿Qué haces?","o":["Me quedo en la zona de seguridad hasta que se autorice volver","Vuelvo corriendo, porque es rápido","Le pido a un compañero que vaya por él","Vuelvo por la otra salida, que está más cerca del puesto"],"w":"Nadie vuelve a entrar hasta que se autorice."},{"q":"Un compañero quiere volver por su mochila mientras se cuenta al personal. ¿Qué le dices?","o":["Que se quede: nadie entra hasta que se autorice","Que vaya rápido por la salida más cercana","Que vaya si el humo es poco","Que espere cinco minutos y entre"],"w":"Volver por cosas personales puede costar una vida."},{"q":"¿Qué haces con tus pertenencias al evacuar?","o":["Las dejo y salgo de inmediato","Vuelvo por ellas antes de salir","Las busco si están cerca del camino","Le pido a otro que las saque"],"w":"Ninguna pertenencia vale el riesgo."}]},{"s":"emergencias_conteo","v":[{"q":"Al llegar a la zona de seguridad, lo correcto es:","o":["Quedarme para el conteo y avisar si falta alguien","Grabar con el celular y subirlo","Irme a mi casa, porque ya salí","Volver a la planta a buscar a los que faltan"],"w":"El conteo permite saber si alguien quedó atrapado."},{"q":"En el conteo notas que falta un compañero que estaba en la bodega. ¿Qué haces?","o":["Informo a quien dirige la evacuación o a Bomberos y dónde lo vi","Entro a buscarlo de inmediato","Espero callado a que aparezca","Lo llamo por celular y entro a buscarlo si no contesta"],"w":"Quien rescata debe ser personal preparado; tu dato los guía."},{"q":"Nadie debe volver a entrar a la planta hasta que se autorice.","vf":true,"w":"Verdadero. Volver antes puede convertirte en otra víctima."}]}]},{"id":"senaletica","sec":"todos","title":"Señalización de seguridad","thumb":"signsAll","learn":[{"s":"senaletica_porque","t":"¿Para qué sirven las señales?","x":"Te avisan de un peligro, una obligación o una ruta de escape <b>antes</b> de que te expongas, incluso en una zona que no conoces. En Chile siguen la <b>NCh 1410</b> (colores de seguridad) y la <b>NCh 1411</b> (letreros de seguridad), y el <b>DS 594</b> obliga a la empresa a señalizar los riesgos. Una señal <b>no elimina el peligro</b>: solo te advierte. Tu parte es leerla y obedecerla."},{"s":"senaletica_formas","t":"Forma y color tienen significado","x":"<ul><li><b>Círculo rojo con barra:</b> prohibición.</li><li><b>Círculo azul:</b> obligación.</li><li><b>Triángulo amarillo con borde negro:</b> advertencia de peligro.</li><li><b>Rectángulo verde:</b> evacuación, salida y primeros auxilios.</li><li><b>Rectángulo rojo:</b> extintores y equipos contra incendio.</li></ul>La forma y el color dicen qué tipo de señal es; el símbolo del centro dice qué se prohíbe, exige o advierte."},{"s":"senaletica_prohib","t":"Prohibición: círculo rojo con barra","x":"Indica algo que <b>no se puede hacer</b>: no fumar, no pasar, no usar el celular, no encender fuego. En {EMP} el <b>EPS (poliestireno) y el OSB arden muy rápido</b>, y el EPS al quemarse suelta un humo negro y tóxico. Por eso la prohibición de fumar rige en toda la planta, también en las pausas y con las máquinas detenidas. Solo se fuma en el lugar habilitado que indique la jefatura.","k":"Nunca fumes ni hagas chispas cerca del EPS o del OSB."},{"s":"senaletica_oblig","t":"Obligación: círculo azul","x":"Indica lo que <b>debes usar o hacer</b> en esa zona: casco, protector auditivo, lentes, mascarilla, zapatos de seguridad. Si la zona está señalizada, el EPP es <b>obligatorio todo el tiempo</b> que estés dentro, aunque solo vayas de paso o la máquina esté apagada. Si te falta un EPP o está dañado, <b>pídelo antes de entrar</b>: la empresa lo entrega sin costo."},{"s":"senaletica_adv","t":"Advertencia: triángulo amarillo","x":"Avisa de un <b>peligro cercano</b>: tránsito de grúa horquilla, riesgo eléctrico, carga suspendida, piso resbaladizo. No prohíbe el paso, pero exige que <b>bajes el ritmo, mires a tu alrededor y aumentes la atención</b>. La grúa también avisa con luz y sonido: <b>la baliza encendida y la alarma de retroceso</b> significan que la máquina se mueve cerca de ti."},{"s":"senaletica_evac","t":"Verde para salir, rojo para el fuego","x":"Las señales <b>verdes</b> muestran la vía de evacuación, la salida de emergencia y los primeros auxilios, como el botiquín con su cruz blanca: síguelas en el sentido de la flecha hasta la zona de seguridad. Las señales <b>rojas</b> marcan dónde están los extintores y otros equipos contra incendio. Ambas deben estar <b>siempre visibles</b>: nunca dejes pallets ni paneles delante de una salida, una señal o un extintor."},{"s":"senaletica_sga","t":"Pictogramas de productos químicos","x":"Los envases de adhesivos y químicos llevan pictogramas del Sistema Globalmente Armonizado (SGA), exigidos por el <b>DS 57</b>: <b>rombos de borde rojo, fondo blanco y símbolo negro</b>. La llama indica inflamable; el signo de exclamación, irritante o nocivo; la silueta con el pecho dañado, daño grave a la salud. Antes de usar un producto, lee su etiqueta y su <b>Hoja de Datos de Seguridad (HDS)</b>. <b>Envase sin etiqueta no se usa.</b>"},{"s":"senaletica_piso","t":"Demarcación en el piso","x":"Las líneas pintadas en el piso también son señalización: delimitan <b>pasillos peatonales</b>, la <b>zona de tránsito de grúa</b> y las áreas de acopio. Las franjas <b>amarillas y negras</b> marcan un peligro o un borde. Camina solo por tu pasillo, cruza la ruta de la grúa por donde indique la jefatura y <b>no dejes pallets, paneles ni recortes sobre las líneas</b>, ni siquiera por un rato.","k":"Camina por el pasillo peatonal, nunca por la ruta de la grúa."},{"s":"senaletica_auto","t":"Autocuidado: no te acostumbres a las señales","x":"Acciones inseguras típicas: ignorar un letrero \"porque siempre ha estado ahí\", cruzar la zona de grúa por el camino corto, tapar una señal con pallets, sacarse el protector porque \"hoy no hay tanto ruido\". La decisión segura: <b>obedecer cada señal, cada vez</b>. Si ves una señal caída, rota, borrosa o tapada, <b>avísalo a tu jefatura</b>: una señal que no se ve no protege a nadie."}],"quiz":[{"s":"senaletica_oblig","v":[{"q":"En una puerta de la planta ves un círculo azul con la figura de unos fonos. ¿Qué significa?","o":["Que el protector auditivo es obligatorio en esa zona","Que está prohibido entrar con protector auditivo","Que hay ruido y el protector es opcional","Que en esa sala se entregan protectores"],"w":"El círculo azul indica una obligación: lo que debes usar o hacer en esa zona."},{"q":"¿Qué tipo de señal es un círculo de fondo azul con un símbolo blanco?","o":["Obligación","Prohibición","Advertencia","Información"],"w":"Azul y circular: algo que es obligatorio usar o hacer."},{"q":"Un círculo azul indica una recomendación: puedes cumplirla si te acomoda.","vf":false,"w":"Falso. El círculo azul es una obligación, no una sugerencia."}]},{"s":"senaletica_adv","v":[{"q":"Ves un triángulo amarillo con borde negro y la figura de una grúa horquilla. ¿Qué debes hacer?","o":["Bajar el ritmo, mirar a mi alrededor y estar atento","Dejar de pasar, porque esa zona está prohibida","Ponerme un EPP especial antes de pasar","Seguir igual, porque es solo informativa"],"w":"La advertencia no prohíbe el paso: exige más atención porque hay un peligro cerca."},{"q":"¿Qué indica una señal triangular amarilla con borde negro?","o":["Advertencia de un peligro cercano","Prohibición de una acción","Obligación de usar un EPP","Ubicación de la salida de emergencia"],"w":"El triángulo amarillo advierte de un peligro."},{"q":"Escuchas la alarma de retroceso y ves la baliza encendida de la grúa cerca de tu pasillo. ¿Qué significan?","o":["Que la grúa se mueve cerca: atención y distancia","Que la grúa está detenida y puedo pasar","Que hay una emergencia y hay que evacuar","Que el operador terminó su turno"],"w":"La baliza y la alarma son avisos luminosos y sonoros de una máquina en movimiento."}]},{"s":"senaletica_prohib","v":[{"q":"Estás en tu pausa y la sierra está detenida. ¿Puedes fumar junto al acopio de EPS y OSB?","o":["No: rige siempre, el EPS y el OSB arden rápido","Sí, porque la sierra está apagada y no hay chispas","Sí, si tengo un extintor a mano y estoy atento","Sí, si me alejo del adhesivo y de los solventes"],"w":"La prohibición de fumar no depende de la máquina: el material arde muy rápido."},{"q":"¿Qué significa un círculo rojo con una barra diagonal?","o":["Que esa acción está prohibida","Que esa acción se permite con cuidado","Que ahí hay un equipo contra incendio","Que es una zona de advertencia"],"w":"Rojo con barra: prohibición, sin excepciones."},{"q":"En la planta, la prohibición de fumar se respeta también durante las pausas y con las máquinas detenidas.","vf":true,"w":"Verdadero. Solo se fuma en el lugar habilitado que indique la jefatura."}]},{"s":"senaletica_evac","v":[{"q":"Se activa la alarma de evacuación. ¿Qué señales sigues para salir?","o":["Las verdes, en el sentido de la flecha","Las rojas, porque indican emergencia","Las azules, porque son obligatorias","Las amarillas, porque marcan peligro"],"w":"El verde indica evacuación y salida hasta la zona de seguridad."},{"q":"¿De qué color son las señales de salida de emergencia y de primeros auxilios?","o":["Verde","Rojo","Azul","Amarillo"],"w":"Verde: evacuación, salida y primeros auxilios."},{"q":"Buscas el botiquín de primeros auxilios. ¿Qué señal te guía hasta él?","o":["Una señal verde con una cruz blanca","Una señal roja con una cruz blanca","Un círculo azul con una cruz","Un triángulo amarillo con una cruz"],"w":"Los primeros auxilios se señalizan en verde."}]},{"s":"senaletica_evac","v":[{"q":"Una señal de fondo rojo con la figura de un extintor indica:","o":["Dónde hay un equipo contra incendio","Que está prohibido encender fuego","Una salida de emergencia","Que hay riesgo de incendio cerca"],"w":"Las señales rojas de este tipo marcan extintores y equipos contra incendio."},{"q":"Hay un amago de fuego y buscas un extintor. ¿Qué señal te ayuda a encontrarlo?","o":["Una señal roja con el dibujo del extintor","Una señal verde con una flecha","Un triángulo amarillo con una llama","Un círculo azul con un extintor"],"w":"El rojo te muestra dónde está el equipo contra incendio."},{"q":"Además de la prohibición, ¿para qué se usa el color rojo en las señales?","o":["Para marcar extintores y equipos contra incendio","Para marcar las salidas de emergencia","Para marcar el EPP obligatorio","Para marcar los pasillos peatonales"],"w":"Rojo: prohibición y equipos contra incendio. Verde: salida."}]},{"s":"senaletica_sga","v":[{"q":"¿Cómo son los pictogramas SGA del envase de adhesivo?","o":["Rombos de borde rojo, fondo blanco y símbolo negro","Rombos de fondo amarillo y borde negro","Triángulos amarillos con símbolo negro","Círculos rojos con un símbolo blanco"],"w":"Así son los pictogramas del SGA que exige el DS 57."},{"q":"Encuentras un bidón sin etiqueta en la zona de encolado. ¿Qué haces?","o":["No lo uso y aviso a mi jefatura","Lo huelo para saber qué contiene","Lo uso si se parece al adhesivo de siempre","Le pongo la etiqueta del bidón de al lado"],"w":"Envase sin etiqueta no se usa: no sabes qué peligro tiene."},{"q":"En la etiqueta del adhesivo ves un rombo con una llama. ¿Qué indica?","o":["Que el producto es inflamable","Que el producto es corrosivo","Que el producto es explosivo","Que el producto daña el medio ambiente"],"w":"La llama indica inflamable. La HDS explica cómo usarlo y guardarlo."}]},{"s":"senaletica_tapada","v":[{"q":"Al llegar al turno ves pallets de paneles delante del extintor y de su señal. ¿Qué corresponde?","o":["Despejar o pedir que se despeje de inmediato y avisar","Dejarlo así si es solo por este turno","Mover la señal a otro lugar más visible","Esperar la próxima inspección del prevencionista"],"w":"Extintores y señales deben estar siempre visibles y con el acceso libre."},{"q":"¿Cuál es la condición correcta de un extintor y su señal?","o":["Visibles y con el acceso despejado","Detrás de los pallets, protegidos de golpes","Guardados en bodega hasta que se necesiten","Visibles, aunque con material delante"],"w":"En una emergencia no hay tiempo para despejar el acceso."},{"q":"Una señal de advertencia quedó tapada por un acopio de OSB. ¿Por qué es un problema?","o":["Porque una señal que no se ve no avisa del peligro","Porque las señales se ensucian con el polvo","Solo es problema si viene una inspección","No lo es si los antiguos ya conocen el peligro"],"w":"El peligro sigue ahí aunque la señal esté tapada; los nuevos no lo conocen."}]},{"s":"senaletica_piso","v":[{"q":"Un pallet no cabe en el acopio. ¿Puedes dejarlo un rato sobre la línea del pasillo peatonal?","o":["No: las líneas marcan pasillos que deben estar libres","Sí, si es menos de una hora","Sí, si aviso a mis compañeros","Sí, si queda sobre la línea y no dentro del pasillo"],"w":"La demarcación separa personas y máquinas; nada se deja sobre ella."},{"q":"¿Qué marcan las franjas amarillas y negras pintadas en el piso?","o":["Un peligro o un borde que hay que respetar","La zona donde se puede acopiar material","El lugar de descanso del personal","Una ruta de evacuación"],"w":"Amarillo y negro alternados advierten de un peligro."},{"q":"Puedo cruzar por la zona de tránsito de grúa para acortar camino si no viene ninguna grúa.","vf":false,"w":"Falso. Se camina por el pasillo peatonal y se cruza solo por donde indique la jefatura."}]},{"s":"senaletica_oblig","v":[{"q":"La zona tiene la señal de protector auditivo, pero hoy \"no hay tanto ruido\". ¿Qué haces?","o":["Lo uso igual, todo el tiempo que estoy en la zona","Lo uso solo mientras funciona la sierra","Lo uso solo si me molesta el ruido","Lo llevo al cuello, listo para ponérmelo"],"w":"Si la zona está señalizada, el protector es obligatorio todo el tiempo."},{"q":"Solo vas de paso por una zona con señal azul de casco y lentes. ¿Qué corresponde?","o":["Usar casco y lentes mientras estoy dentro","No usarlos, porque solo voy de paso","Usar solo el casco, que es lo principal","Usarlos solo si hay una máquina encendida"],"w":"La obligación rige para todos los que entran a la zona, aunque sea de paso."},{"q":"Te falta el protector auditivo y debes entrar a una zona señalizada. ¿Qué haces?","o":["Lo pido antes de entrar; se entrega gratis","Entro rápido y salgo antes de que me afecte","Me tapo los oídos con algodón o papel","Entro y lo pido al terminar la tarea"],"w":"Sin el EPP obligatorio no se entra. La empresa lo entrega sin costo."}]}]},{"id":"uv","sec":"todos","title":"Radiación UV de origen solar","thumb":"uv_intro","learn":[{"s":"uv_intro","t":"Radiación UV: un peligro que no se siente","x":"El sol emite <b>radiación ultravioleta (UV)</b>: no se ve ni se siente como calor, pero daña la piel y los ojos. En {EMP} te expones al trabajar en el <b>patio</b>, al <b>cargar y descargar camiones</b> con paneles y en el <b>montaje en obra</b>. En verano basta poco tiempo al sol para quemarse, y el daño se va sumando durante toda la vida."},{"s":"uv_efectos","t":"Efectos en la salud","x":"<ul><li><b>Quemaduras</b> solares.</li><li><b>Daño ocular</b>: irritación y, con los años, lesiones como cataratas.</li><li><b>Cáncer de piel</b>, por la exposición acumulada.</li></ul>El daño se acumula desde joven. Revisa tu piel: un lunar que cambia de forma, color o tamaño, o una herida que no sana, debe verla un médico."},{"s":"uv_escala","t":"El índice UV","x":"Indica cuánta radiación UV llega. Mientras más alto, más rápido daña:<ul><li>De 1 a 2, <b>verde</b>: bajo.</li><li>De 3 a 5, <b>amarillo</b>: moderado.</li><li>De 6 a 7, <b>naranjo</b>: alto.</li><li>De 8 a 10, <b>rojo</b>: muy alto.</li><li>11 o más, <b>violeta</b>: extremo.</li></ul><b>Desde 3 hay que protegerse.</b> El índice del día se informa en los medios y en el sitio de la Dirección Meteorológica."},{"s":"uv_horario","t":"Horario de mayor radiación","x":"La radiación es mayor cuando el sol está más alto: en verano, aproximadamente entre las <b>10:00 y las 17:00</b>, con el máximo cerca del mediodía. Cuando se pueda, deja las tareas al sol para temprano o para el final de la tarde, y busca la sombra en las pausas. Un truco simple: <b>si tu sombra es más corta que tu estatura, el sol está fuerte</b>."},{"s":"uv_nublado","t":"Aunque esté nublado o fresco","x":"Las nubes <b>no detienen toda la radiación UV</b>: en un día nublado igual te puedes quemar. La radiación UV <b>no depende de la temperatura</b>: puede haber índice alto en un día fresco y con viento. Además, superficies claras como el cemento del patio <b>reflejan parte de la radiación</b> y aumentan la exposición. Protégete siempre que trabajes al aire libre."},{"s":"uv_ropa","t":"Ropa y EPP contra el sol","x":"<ul><li><b>Manga larga</b> y pantalón largo: no arremangues el overol.</li><li><b>Legionario o cubrenuca bajo el casco</b>: protege orejas y cuello.</li><li><b>Lentes con filtro UV</b>: un lente oscuro sin filtro es peor, porque la pupila se abre y entra más radiación.</li></ul>La empresa entrega estos elementos sin costo. Úsalos durante toda la exposición, no solo cuando sientas calor.","k":"Al sol: manga larga, legionario bajo el casco y lentes con filtro UV."},{"s":"uv_bloq","t":"Bloqueador solar","x":"Usa bloqueador <b>FPS 30 o más</b> en lo que la ropa no cubre: cara, nariz, orejas, cuello y dorso de las manos. Aplícalo <b>unos 30 minutos antes</b> de salir al sol y <b>reaplícalo cada 2 a 3 horas</b>, y más seguido si sudas mucho. Ni el FPS más alto reemplaza a la ropa ni a la sombra: es una barrera más."},{"s":"uv_sombra","t":"Sombra e hidratación","x":"Aprovecha la sombra en las pausas y haz bajo techo las tareas que lo permitan. <b>Toma agua</b> durante toda la jornada aunque no tengas sed: al sol y con esfuerzo físico se pierde mucho líquido. Si sientes mareo, dolor de cabeza, náuseas o calambres, <b>detén la tarea, avisa y busca la sombra</b>: pueden ser señales de que el calor te está afectando."},{"s":"uv_ley","t":"Qué dice la normativa","x":"La <b>Ley 20.096</b> (art. 19) obliga al empleador a adoptar medidas para proteger a quienes trabajan expuestos a radiación UV. El <b>DS 594</b> (arts. 109 a y siguientes) y la <b>Guía Técnica de Radiación UV de Origen Solar</b> del MINSAL detallan esas medidas: informar el riesgo y el índice del día, organizar tareas y pausas, y entregar EPP. Tu parte: <b>usarlos siempre</b> y avisar si falta algo."},{"s":"uv_auto","t":"Autocuidado: \"es solo un rato\"","x":"La mayoría de los daños se relacionan con una acción insegura. Con el sol, la típica es pensar <b>\"es solo un rato\"</b> y salir sin manga larga, legionario ni bloqueador, o sacarse la ropa por el calor. Cada exposición se suma al daño acumulado. La decisión segura: <b>protegerte cada vez que sales al sol</b>. Avisar si falta bloqueador o sombra también es autocuidado.","k":"Protégete cada vez que sales al sol, aunque sea un rato."}],"quiz":[{"s":"uv_intro","v":[{"q":"¿En cuál de estas tareas de {EMP} te expones a radiación UV?","o":["Cargando paneles en un camión en el patio","Operando la sierra dentro de la nave","Aplicando adhesivo en la encoladora","Ordenando la bodega interior"],"w":"Toda tarea al aire libre te expone al sol: patio, carga de camiones y obra."},{"q":"¿Por qué la radiación UV es un peligro difícil de notar?","o":["No se ve ni se siente como calor, pero daña","Solo afecta a las personas de piel clara","Sus efectos aparecen solo en vacaciones","Solo existe en días de mucho calor"],"w":"Que no la sientas no significa que no te esté dañando."},{"q":"Vas a montar paneles en una obra al aire libre toda la mañana. ¿Qué riesgo se suma al de la tarea?","o":["La exposición a radiación UV","El ruido de las sierras de la planta","El polvo de la rebajadora","Ninguno, si el día está fresco"],"w":"El montaje en obra es trabajo al sol: hay que protegerse aunque esté fresco."}]},{"s":"uv_escala","v":[{"q":"El índice UV de hoy es 9. ¿Qué nivel y color le corresponde?","o":["Muy alto, rojo","Alto, naranjo","Extremo, violeta","Moderado, amarillo"],"w":"De 8 a 10 es rojo: riesgo muy alto."},{"q":"¿Desde qué valor del índice UV hay que protegerse?","o":["Desde 3, color amarillo","Desde 6, color naranjo","Desde 8, color rojo","Desde 11, color violeta"],"w":"Desde el nivel moderado (3) ya se necesita protección."},{"q":"Un índice UV de 6 a 7 corresponde a:","o":["Alto, color naranjo","Moderado, color amarillo","Muy alto, color rojo","Bajo, color verde"],"w":"De 6 a 7 es naranjo: riesgo alto."}]},{"s":"uv_horario","v":[{"q":"En verano, ¿en qué horario la radiación UV es mayor?","o":["Aproximadamente de 10:00 a 17:00","Aproximadamente de 7:00 a 10:00","Aproximadamente de 17:00 a 20:00","Es igual durante todo el día"],"w":"Es cuando el sol está más alto, con el máximo cerca del mediodía."},{"q":"Hay que cargar un camión al sol en verano y se puede elegir la hora. ¿Cuál es la mejor?","o":["Temprano en la mañana","A las 13:00","A las 15:00","Da lo mismo si uso bloqueador"],"w":"Fuera del horario de mayor radiación la exposición es menor."},{"q":"Si tu sombra es más corta que tu estatura, el sol está fuerte y debes protegerte.","vf":true,"w":"Verdadero. Sombra corta significa sol alto y radiación intensa."}]},{"s":"uv_nublado","v":[{"q":"Está nublado y fresco. ¿Qué haces antes de salir a cargar al patio?","o":["Me protejo igual: las nubes no detienen la UV","No me protejo, porque hoy no hay sol directo","Me pongo solo bloqueador en la cara y salgo","Me protejo solo si se despeja durante el día"],"w":"Parte de la radiación UV atraviesa las nubes."},{"q":"¿Qué pasa con la radiación UV en un día nublado?","o":["Parte atraviesa las nubes y puede quemar","Las nubes la bloquean por completo","Solo llega si hace calor","Solo llega al mediodía"],"w":"Nublado no significa protegido."},{"q":"Hoy está nublado y hace 15 grados. Un compañero dice que no hace falta protegerse. ¿Qué es correcto?","o":["Hay que protegerse: la UV no depende del calor","Tiene razón: con frío no llega radiación UV","Solo hay que protegerse con índice violeta","Basta con usar lentes oscuros comunes"],"w":"La radiación UV no se siente como calor y pasa a través de las nubes."}]},{"s":"uv_bloq","v":[{"q":"¿Cada cuánto se debe reaplicar el bloqueador al trabajar al sol?","o":["Cada 2 a 3 horas, y antes si sudas mucho","Una vez al día, en la mañana","Cada 6 horas","Solo cuando la piel se pone roja"],"w":"El bloqueador pierde efecto con el sudor y el tiempo."},{"q":"Te pusiste bloqueador a las 8:00 y a las 11:30 sigues cargando al sol, transpirando. ¿Qué haces?","o":["Me lo vuelvo a aplicar","Nada, dura toda la jornada","Me lo aplico solo si siento ardor","Me pongo más solo en la cara"],"w":"Pasaron más de 3 horas y con sudor: toca reaplicar en todas las zonas expuestas."},{"q":"¿Cuándo se aplica el bloqueador por primera vez?","o":["Unos 30 minutos antes de salir al sol","Después de una hora al sol","Solo cuando siento calor","Al volver a la sombra"],"w":"Necesita un tiempo para hacer efecto antes de la exposición."}]},{"s":"uv_mal","v":[{"q":"Un compañero carga paneles al sol con el overol arremangado, sin legionario y sin lentes. ¿Qué le falta?","o":["Bajar las mangas, legionario y lentes con filtro UV","Solo tomar más agua y descansar a la sombra","Solo ponerse bloqueador en la cara y los brazos","Nada, si el trabajo dura menos de una hora"],"w":"La protección es la combinación: ropa, legionario, lentes y bloqueador."},{"q":"¿Qué combinación protege bien del sol al trabajar en el patio?","o":["Manga larga, legionario, lentes UV y bloqueador","Polera de manga corta y bloqueador FPS 50","Casco, lentes oscuros comunes y bloqueador","Manga larga y casco, sin legionario ni lentes"],"w":"Cada elemento cubre una parte distinta: piel, cuello, ojos."},{"q":"¿Por qué no sirven unos lentes oscuros comunes, sin filtro UV?","o":["Oscurecen, la pupila se abre y entra más radiación","Porque se rayan con el polvo","Porque son incómodos con el casco","Sí sirven: cualquier lente oscuro protege"],"w":"Solo el filtro UV bloquea la radiación; lo oscuro por sí solo no."}]},{"s":"uv_ropa","v":[{"q":"¿Para qué sirve el legionario o cubrenuca bajo el casco?","o":["Protege orejas y cuello, que el casco deja al sol","Reemplaza al casco en el patio","Absorbe el sudor de la frente","Se usa solo en invierno, contra el frío"],"w":"Cubre las zonas que el casco no protege."},{"q":"¿Qué partes del cuerpo quedan más expuestas si usas casco sin legionario?","o":["Orejas y cuello","Frente y cabeza","Espalda y pecho","Pies y tobillos"],"w":"El casco cubre la cabeza, pero no las orejas ni la nuca."},{"q":"Hace calor y te arremangas el overol para cargar el camión. ¿Es correcto?","o":["No: la manga larga es parte de la protección UV","Sí, si me pongo bloqueador en los brazos","Sí, si es menos de una hora","Sí, porque el calor es peor que el sol"],"w":"El bloqueador no reemplaza a la ropa: es una barrera más."}]},{"s":"uv_bloq","v":[{"q":"¿Qué factor de protección se recomienda como mínimo para el bloqueador?","o":["FPS 30 o más","FPS 10 o más","FPS 15 o más","Cualquier FPS, si se aplica bien"],"w":"Se recomienda FPS 30 o más, reaplicado cada 2 a 3 horas."},{"q":"¿En qué zonas se aplica el bloqueador?","o":["Cara, nariz, orejas, cuello y manos","Solo en la cara, que es lo más expuesto","Solo en los brazos y la nuca","Sobre la ropa, para que dure más tiempo"],"w":"Va en toda la piel que la ropa no cubre."},{"q":"Si uso bloqueador FPS 50, puedo trabajar al sol sin manga larga ni legionario.","vf":false,"w":"Falso. Ningún bloqueador reemplaza a la ropa ni al legionario."}]},{"s":"uv_efectos","v":[{"q":"¿Cuáles son efectos de la radiación UV en la salud?","o":["Quemaduras, daño ocular y cáncer de piel","Solo quemaduras leves que se pasan","Solo dolor de cabeza","Solo un bronceado sin consecuencias"],"w":"Y el daño se acumula con los años."},{"q":"Notas que un lunar del brazo cambió de color y de tamaño. ¿Qué haces?","o":["Consulto a un médico","Espero a ver si vuelve a la normalidad","Le pongo bloqueador y sigo","Lo cubro con una venda"],"w":"Un lunar que cambia es una señal de alerta que debe evaluar un médico."},{"q":"¿Por qué hay que protegerse del sol desde joven?","o":["Porque el daño se acumula durante toda la vida","Porque la piel joven se recupera sola","Porque el cáncer de piel aparece en días","Porque después de los 40 ya no afecta"],"w":"Cada exposición suma al daño total."}]},{"s":"uv_auto","v":[{"q":"Hace calor y vas a cargar un camión \"solo un rato\". ¿Qué haces?","o":["Me protejo igual, con todo mi EPP y bloqueador","Voy sin protección porque es poco tiempo","Me pongo solo el bloqueador en la cara","Me saco el legionario por el calor que hace"],"w":"Cada exposición suma: la protección se usa siempre."},{"q":"En el patio se acabó el bloqueador. ¿Qué es lo correcto?","o":["Avisar a la jefatura para que lo repongan","Seguir sin bloqueador hasta fin de mes","No decir nada y trabajar a la sombra cuando pueda","Seguir igual, porque la ropa basta"],"w":"Avisar lo que falta también es autocuidado."},{"q":"¿Por qué pensar \"es solo un rato\" es una acción insegura con el sol?","o":["Porque cada exposición se suma al daño","Porque en poco rato la UV no daña","Porque solo importa si te quemas","No es insegura si el día está nublado"],"w":"El daño de la radiación UV es acumulativo."}]}]},{"id":"enfermedades","sec":"todos","title":"Efectos en la salud y enfermedades profesionales","thumb":"bodyMap","learn":[{"s":"enfermedades_vs","t":"Accidente y enfermedad profesional","x":"Un <b>accidente del trabajo</b> ocurre de golpe: un corte, una caída. Una <b>enfermedad profesional</b> (Ley 16.744, art. 7) es la causada de manera directa por el ejercicio de la profesión o el trabajo que realizas, y que produce incapacidad o muerte. Aparece de a poco, a veces después de años, y casi siempre <b>sin dolor al comienzo</b>. Por eso se previene antes de sentir molestias."},{"s":"enfermedades_ruido","t":"Ruido: hipoacusia","x":"Las sierras, la rebajadora y el aire comprimido dañan de a poco las células del oído interno. La pérdida auditiva por ruido, o <b>hipoacusia</b>, es <b>permanente: no tiene cura</b>. El DS 594 fija <b>85 dB(A) para 8 horas</b>, y por cada 3 dB más el tiempo permitido baja a la mitad: con 88 dB(A), 4 horas. En zona señalizada, el protector va <b>bien puesto todo el tiempo</b>.","k":"Usa el protector auditivo todo el turno: el oído dañado no se recupera."},{"s":"enfermedades_piel","t":"Adhesivos: dermatitis","x":"El contacto repetido con adhesivo puede causar <b>dermatitis</b>: enrojecimiento, picazón, grietas o ronchas. Algunas personas se sensibilizan y después reaccionan con muy poco producto. Usa los <b>guantes que indica la Hoja de Datos de Seguridad (HDS)</b>, porque el guante de cuero no protege de químicos. Lávate con agua y jabón antes de comer y al terminar, y <b>nunca limpies la piel con solventes</b>."},{"s":"enfermedades_polvo","t":"Polvo de madera: respiración","x":"Cortar y rebajar OSB genera polvo fino que irrita ojos y nariz y puede causar tos, rinitis y asma. La IARC clasifica el polvo de madera como <b>cancerígeno para humanos (Grupo 1)</b>. El polvo más dañino es el que no se ve. Usa la <b>aspiración conectada</b> en la máquina y la <b>mascarilla indicada</b>, bien ajustada. Limpia con aspiradora o escobilla, <b>nunca soplando</b> con aire comprimido."},{"s":"enfermedades_musculo","t":"Lesiones musculoesqueléticas","x":"Levantar paneles doblando la espalda, girar el tronco con carga o repetir el mismo gesto todo el turno daña <b>espalda, hombros y muñecas</b>. Al principio es cansancio; después, dolor que no se pasa con el descanso. La Ley 20.949 fija la carga manual máxima en <b>25 kg para hombres y 20 kg para mujeres y menores de 18</b>. Usa ayuda mecánica, carga los paneles entre dos y aprovecha las pausas."},{"s":"enfermedades_vigilancia","t":"Vigilancia de la salud","x":"Cuando una evaluación ambiental confirma exposición sobre el nivel de acción, por ejemplo al ruido según el protocolo <b>PREXOR</b>, la <b>ACHS</b> incorpora a los trabajadores expuestos a un <b>programa de vigilancia de la salud</b>, con exámenes periódicos como la audiometría. No tienen costo para ti. <b>Asistir es parte de tu protección</b>: los exámenes detectan el daño antes de que avance, aunque hoy te sientas bien."},{"s":"enfermedades_senales","t":"Señales de alerta","x":"<ul><li><b>Zumbido</b> en los oídos o necesidad de hablar cada vez más fuerte.</li><li><b>Picazón</b>, ronchas o grietas en las manos.</li><li><b>Tos</b> o nariz tapada que no se pasa.</li><li><b>Hormigueo</b> o dolor en manos, hombros o espalda que se repite.</li></ul>Avísalo a tu jefatura o al prevencionista: mientras antes se evalúa, más se puede hacer.","k":"Si notas una señal de alerta, avísala de inmediato a tu jefatura."},{"s":"enfermedades_diep","t":"Si crees que es por el trabajo","x":"Avisa a tu jefatura. La empresa debe hacer la <b>DIEP</b> (Denuncia Individual de Enfermedad Profesional) y derivarte a la <b>ACHS</b>, que evalúa si es de origen laboral. Si la empresa no la hace, puedes presentarla tú, un familiar, el médico tratante o el comité paritario. Si se califica como profesional, la Ley 16.744 cubre <b>atención gratuita</b>, subsidio y otras prestaciones. Fono de la ACHS: <b>1404</b>."},{"s":"enfermedades_auto","t":"Autocuidado: la protección no tiene pausa","x":"Acciones inseguras típicas: sacarse los fonos \"solo un rato\", tocar el adhesivo sin guantes, soplar el polvo, <b>faltar al examen</b>. El daño se suma día a día. La decisión segura: <b>protección todo el turno</b>, ir a tus controles y pedir el recambio si tu EPP está malo: un fono que no sella o una mascarilla rota no protegen."}],"quiz":[{"s":"enfermedades_vs","v":[{"q":"¿Cuál es una enfermedad profesional según la Ley 16.744?","o":["La causada de manera directa por el trabajo que realizas","Cualquier enfermedad que aparezca durante el turno","Un corte en la mano con la sierra","Un resfrío contagiado por un compañero"],"w":"Así la define la Ley 16.744, art. 7: causada directamente por el trabajo."},{"q":"¿Qué diferencia a una enfermedad profesional de un accidente del trabajo?","o":["Aparece de a poco, a veces después de años","Siempre duele desde el primer día","Solo afecta a trabajadores mayores","Solo la causa un golpe repentino"],"w":"El accidente ocurre de golpe; la enfermedad avanza en silencio."},{"q":"Como no siento dolor, puedo estar seguro de que mi trabajo no me está enfermando.","vf":false,"w":"Falso. La enfermedad profesional casi siempre empieza sin dolor."}]},{"s":"enfermedades_ruido","v":[{"q":"La pérdida auditiva causada por el ruido:","o":["Es permanente: no tiene cura","Se recupera con unos días de descanso","Se cura con tratamiento médico","Desaparece al cambiar de puesto"],"w":"La hipoacusia por ruido solo se previene."},{"q":"Según el DS 594, ¿cuál es el límite de ruido para una jornada de 8 horas?","o":["85 dB(A)","75 dB(A)","95 dB(A)","100 dB(A)"],"w":"Sobre 85 dB(A) en 8 horas hay riesgo de daño auditivo."},{"q":"Si el ruido sube de 85 a 88 dB(A), ¿cuánto tiempo se permite de exposición sin protección?","o":["4 horas","8 horas","6 horas","2 horas"],"w":"Cada 3 dB más, el tiempo permitido baja a la mitad."}]},{"s":"enfermedades_fonosMal","v":[{"q":"En una zona señalizada con protector auditivo, ¿puedes sacártelo un rato si estás cansado?","o":["No: va puesto todo el tiempo que estoy en la zona","Sí, si son menos de 15 minutos","Sí, si la sierra está detenida justo en ese momento","Sí, si me alejo un par de metros"],"w":"Incluso ratos cortos sin protector suman daño al oído."},{"q":"Te sacas los fonos 15 minutos para conversar junto a la sierra en marcha. ¿Qué pasa?","o":["Ese rato sin protección suma daño al oído","Nada: el daño ocurre solo en jornadas completas","Nada, si después los aprieto más","Nada, porque al conversar baja el ruido"],"w":"El daño auditivo se acumula con cada exposición sin protección."},{"q":"En una zona señalizada, puedo sacarme el protector auditivo mientras converso con un compañero.","vf":false,"w":"Falso. En zona señalizada el protector es obligatorio todo el tiempo."}]},{"s":"enfermedades_piel","v":[{"q":"Tocar adhesivo sin guantes todos los días puede causar:","o":["Dermatitis: enrojecimiento, picazón o grietas","Solo manchas que se quitan con solvente","Callos que protegen la piel","Nada, si me lavo una vez al día"],"w":"Por eso se usan los guantes que indica la HDS."},{"q":"Te cayó adhesivo en la mano. ¿Cómo la limpias?","o":["Con agua y jabón, nunca con solvente","Con diluyente, porque saca todo rápido","Con un paño con bencina","Lo dejo secar y lo raspo"],"w":"Los solventes dañan la piel y aumentan la dermatitis."},{"q":"¿Qué guante usas para manipular el adhesivo?","o":["El que indica la HDS del producto","El guante de cuero de siempre","Cualquier guante, mientras cubra","Ninguno, si tengo cuidado"],"w":"El guante de cuero no protege de químicos; la HDS dice cuál sirve."}]},{"s":"enfermedades_polvo","v":[{"q":"Según la IARC, el polvo de madera es:","o":["Cancerígeno para humanos (Grupo 1)","Solo irritante, sin efectos a largo plazo","Posible cancerígeno, sin pruebas","Inofensivo si no se ve"],"w":"Por eso se controla en la fuente y se usa mascarilla."},{"q":"Al terminar de rebajar, la mesa está llena de polvo de OSB. ¿Cómo la limpias?","o":["Con aspiradora o escobilla, nunca soplando","Con aire comprimido, que es más rápido","Sacudiendo con un trapo seco","Soplando con la boca, si es poco"],"w":"Soplar levanta el polvo fino y lo respiras."},{"q":"La máquina tiene aspiración, pero la manguera está desconectada. ¿Qué haces?","o":["No corto hasta conectarla o avisar","Corto igual con la mascarilla puesta","Corto igual y barro al final","Corto rápido para hacer menos polvo"],"w":"La aspiración conectada controla el polvo en la fuente."}]},{"s":"enfermedades_vigilancia","v":[{"q":"Me citan a una audiometría del programa de vigilancia de la salud. ¿Qué hago?","o":["Asisto: detecta el daño antes de que avance","No voy, porque escucho bien","Voy solo si me duele el oído","La dejo para cuando cambie de trabajo"],"w":"Los exámenes detectan daños antes de que los notes."},{"q":"¿Qué organismo incorpora a los trabajadores de {EMP} a los programas de vigilancia de la salud?","o":["La ACHS","La Inspección del Trabajo","Fonasa","La municipalidad"],"w":"La ACHS es el organismo administrador de la Ley 16.744 en la empresa."},{"q":"¿Cuándo se incorpora a un trabajador a un programa de vigilancia de la salud?","o":["Cuando se confirma exposición sobre el nivel de acción","Solo cuando ya tiene síntomas de una enfermedad","Solo si el trabajador lo pide por escrito","Solo si tuvo un accidente en ese puesto"],"w":"Se vigila a los expuestos para detectar el daño a tiempo."}]},{"s":"enfermedades_fonosBien","v":[{"q":"¿Qué condición hace que el protector auditivo realmente proteja?","o":["Puesto sobre los oídos, ajustado y todo el tiempo","Que sea de un color llamativo","Usarlo solo en las tareas más ruidosas","Llevarlo al cuello, listo para usar"],"w":"El protector sirve solo puesto y bien sellado."},{"q":"¿Cómo debe usar los fonos quien opera la sierra?","o":["Sobre ambos oídos, ajustados, todo el turno","Sobre un solo oído, para escuchar a otros","Sueltos bajo el casco","Al cuello, poniéndoselos al cortar"],"w":"Un oído descubierto queda expuesto al ruido."},{"q":"Tus fonos tienen la almohadilla rota y no sellan. ¿Qué haces?","o":["Pido el recambio: si no sellan, no protegen","Los sigo usando, algo protegen","Los aprieto más con el casco","Uso solo el lado que está bueno"],"w":"EPP dañado se cambia; la empresa lo repone sin costo."}]},{"s":"enfermedades_senales","v":[{"q":"Tengo zumbido en los oídos al final del turno hace semanas. ¿Qué hago?","o":["Lo aviso a mi jefatura o al prevencionista","Espero a que se pase solo","Lo comento solo con mis compañeros","Me cambio de puesto por mi cuenta"],"w":"Es una señal de alerta: avisar permite evaluarla a tiempo."},{"q":"¿Cuál de estas es una señal de alerta de daño por el trabajo?","o":["Hormigueo o dolor en las manos que se repite","Cansancio después de un día largo","Hambre a mitad del turno","Sueño después de almorzar"],"w":"Un dolor u hormigueo que se repite no es normal: se avisa."},{"q":"Tienes picazón y grietas en las manos desde que trabajas en encolado. ¿Qué haces?","o":["Lo aviso a mi jefatura o al prevencionista","Me pongo crema y sigo sin decir nada","Me lavo con diluyente para sacar el adhesivo","Espero a que empeore para no exagerar"],"w":"Puede ser dermatitis por adhesivo: se avisa y se evalúa."}]},{"s":"enfermedades_diep","v":[{"q":"¿Qué significa la sigla DIEP?","o":["Denuncia Individual de Enfermedad Profesional","Declaración Interna de Exposición Permanente","Denuncia Individual de Evento Peligroso","Documento de Inspección de Equipos de Protección"],"w":"Con ella se inicia la evaluación en la ACHS."},{"q":"Crees que tu dolor de muñeca se debe al trabajo y la empresa no hace la DIEP. ¿Qué puedes hacer?","o":["Presentarla yo mismo en la ACHS","Nada: solo la empresa puede hacerla","Esperar a que se pase el dolor","Atenderme por Fonasa sin decir nada"],"w":"Si la empresa no la hace, la puede presentar el trabajador, un familiar, el médico o el comité paritario."},{"q":"Si una enfermedad se califica como profesional, la Ley 16.744 cubre la atención en forma gratuita.","vf":true,"w":"Verdadero. Además cubre subsidio y otras prestaciones."}]}]},{"id":"psicosocial","sec":"todos","title":"Riesgos psicosociales y bienestar en el trabajo","thumb":"psico_intro","learn":[{"s":"psico_intro","t":"¿Qué son los riesgos psicosociales?","x":"Son condiciones de la <b>organización del trabajo</b> y de las relaciones que pueden dañar la salud mental y física: un ritmo imposible, órdenes confusas, falta de apoyo o malos tratos. No se ven como una sierra, pero también lesionan. El <b>DS 44</b> exige a la empresa identificarlos y gestionarlos igual que los demás riesgos del trabajo."},{"s":"psico_factores","t":"Factores que influyen","x":"<ul><li><b>Carga y ritmo</b> de trabajo.</li><li><b>Claridad:</b> saber qué se espera de ti.</li><li><b>Apoyo</b> de compañeros y jefatura.</li><li><b>Buen trato</b> y respeto.</li><li><b>Equilibrio</b> entre trabajo y vida personal.</li></ul>Cuando estos factores están bien, el trabajo protege la salud; cuando fallan por mucho tiempo, la dañan. Ejemplo en planta: pedidos urgentes todos los días, órdenes que se contradicen y nadie a quien preguntar."},{"s":"psico_estres","t":"El estrés laboral","x":"El estrés aparece cuando lo que se exige supera, <b>por mucho tiempo</b>, lo que se puede hacer. Es como una correa de máquina siempre tensa: aguanta un rato, pero si nunca se suelta, se corta. Algo de presión puntual es normal; el problema es que sea permanente. El estrés sostenido también afecta al cuerpo: <b>presión alta, problemas digestivos y dolores musculares</b>."},{"s":"psico_senales","t":"Señales de alerta","x":"<ul><li>Cansancio que no se pasa con el descanso.</li><li>Problemas para dormir.</li><li>Irritabilidad o ganas de llorar.</li><li>Dolores de cabeza o de estómago.</li><li>No querer ir a trabajar.</li></ul>En el trabajo se nota en <b>más errores, olvidos y discusiones</b> que antes. Si lo notas en ti o en un compañero, no lo ignores: conversarlo a tiempo evita que empeore."},{"s":"psico_carga","t":"Si la carga de trabajo te supera","x":"Conversa con tu jefatura <b>a tiempo</b>, apenas lo notes: pregunta qué es prioritario, avisa si no alcanzas y pide instrucciones claras. Quedarse callado y trabajar al límite no soluciona el problema y aumenta los errores y los accidentes. <b>Nunca te saltes un paso de seguridad</b> para cumplir una meta: ningún pedido justifica una lesión.","k":"Ningún pedido justifica saltarte un paso de seguridad."},{"s":"psico_apoyo","t":"Nos apoyamos como equipo","x":"Un equipo que se ayuda trabaja mejor y más seguro: compartir el peso de un panel, <b>explicarle la tarea y sus riesgos al nuevo</b>, preguntar \"¿cómo estás?\". El apoyo entre compañeros es uno de los factores que más protegen la salud mental. Si un compañero se ve agotado o distinto, pregúntale cómo está y <b>escúchalo sin juzgar</b>."},{"s":"psico_respeto","t":"Buen trato","x":"Gritos, burlas, sobrenombres o humillaciones dañan la salud y el ambiente de trabajo. Con la <b>Ley Karin</b> (Ley 21.643), el maltrato puede constituir <b>acoso laboral</b>, incluso si ocurre una sola vez. Corrige con respeto, explicando qué mejorar, sin gritos ni descalificaciones. Saluda, pide las cosas por favor y trata a todos por igual, también a choferes y contratistas."},{"s":"psico_ceal","t":"El cuestionario CEAL-SM/SUSESO","x":"El <b>Protocolo de Vigilancia de Riesgos Psicosociales en el Trabajo</b> del MINSAL usa el cuestionario <b>CEAL-SM/SUSESO</b>, que reemplazó al ISTAS21. Evalúa las condiciones del trabajo, no a las personas. Cuando corresponda aplicarlo en tu centro de trabajo, tu participación es <b>anónima y voluntaria</b>, y tus respuestas son confidenciales. Responder con sinceridad ayuda a mejorar las condiciones de todos."},{"s":"psico_ayuda","t":"¿A quién recurrir?","x":"<ul><li>A tu <b>jefatura</b>.</li><li>Al <b>Delegado de SST</b> o al asesor en prevención.</li><li>Si el malestar se debe al trabajo, la <b>ACHS</b> puede evaluarlo dentro del seguro de la Ley 16.744.</li></ul>Pedir ayuda no es debilidad: es una decisión responsable. Si un compañero está muy mal, no lo dejes solo y avisa de inmediato."},{"s":"psico_auto","t":"Autocuidado: cansado o apurado, el riesgo sube","x":"La mayoría de los accidentes se relacionan con una acción insegura, y el estrés y el cansancio las hacen más probables: <b>te apuras, te saltas un paso, te distraes</b> en la sierra. La decisión segura: <b>reconocer que no estás bien y decirlo a tu jefatura</b> antes de operar una máquina. Avisar lo que genera sobrecarga también es autocuidado.","k":"Si no estás bien, dilo antes de operar una máquina."}],"quiz":[{"s":"psico_factores","v":[{"q":"Los riesgos psicosociales se relacionan principalmente con:","o":["La organización del trabajo y las relaciones","Las máquinas y las herramientas","El polvo y el ruido de la planta","El clima y la temperatura"],"w":"Carga, ritmo, claridad, apoyo y trato son factores psicosociales."},{"q":"¿Cuál de estos es un factor de riesgo psicosocial?","o":["Recibir órdenes confusas y contradictorias","Cortar paneles con la sierra escuadradora","Manipular adhesivo sin guantes","Levantar un panel pesado sin ayuda"],"w":"La falta de claridad es un factor de la organización del trabajo."},{"q":"¿Qué norma exige a la empresa gestionar los riesgos psicosociales como los demás riesgos?","o":["El DS 44","La Ley de Tránsito","El DS 57","La Ley 20.949"],"w":"El DS 44 regula la gestión preventiva de todos los riesgos laborales."}]},{"s":"psico_ceal","v":[{"q":"Cuando corresponda aplicar el cuestionario CEAL-SM en tu centro de trabajo, tu participación es:","o":["Anónima y voluntaria","Obligatoria y con nombre","Voluntaria, pero con RUT","Anónima, pero obligatoria"],"w":"Es anónima y voluntaria, para que respondas con sinceridad."},{"q":"¿Qué evalúa el cuestionario CEAL-SM/SUSESO?","o":["Las condiciones del trabajo, no a las personas","El rendimiento de cada trabajador","Un diagnóstico de salud mental de cada persona","Quién se queja más en cada área"],"w":"Sus resultados sirven para mejorar la organización del trabajo."},{"q":"Un compañero no quiere responder el CEAL-SM porque teme que la jefatura vea sus respuestas. ¿Qué le explicas?","o":["Que es anónimo y las respuestas son confidenciales","Que mejor responda todo positivo","Que debe poner su nombre para que valga","Que es obligatorio y lo pueden sancionar"],"w":"La confidencialidad permite responder con sinceridad."}]},{"s":"psico_ceal","v":[{"q":"El cuestionario CEAL-SM/SUSESO reemplazó al ISTAS21 como instrumento del Protocolo.","vf":true,"w":"Verdadero. Es el instrumento actual del Protocolo de Vigilancia de Riesgos Psicosociales."},{"q":"¿Qué instrumento usa hoy el Protocolo de Vigilancia de Riesgos Psicosociales del MINSAL?","o":["El cuestionario CEAL-SM/SUSESO","El cuestionario ISTAS21","Una entrevista con la jefatura","Un examen médico individual"],"w":"El CEAL-SM/SUSESO reemplazó al ISTAS21."},{"q":"¿Qué cuestionario fue reemplazado por el CEAL-SM/SUSESO?","o":["El ISTAS21","La matriz de riesgos MIPER","La encuesta de clima interna","La evaluación de desempeño"],"w":"El ISTAS21 era el instrumento anterior del Protocolo."}]},{"s":"psico_estres","v":[{"q":"El estrés laboral afecta solo el ánimo, nunca la salud física.","vf":false,"w":"Falso. Puede causar presión alta, problemas digestivos y dolores musculares."},{"q":"¿Qué puede causar en el cuerpo el estrés laboral sostenido?","o":["Presión alta, problemas digestivos y dolores","Solo cansancio que se pasa con una noche de sueño","Mejor rendimiento físico","Nada, si la persona es fuerte"],"w":"El estrés permanente también enferma al cuerpo."},{"q":"¿Cuándo la presión en el trabajo se vuelve un problema para la salud?","o":["Cuando es permanente, sin respiro","Cuando hay un día puntual de mucho trabajo","Solo cuando hay gritos","Solo cuando el turno es de noche"],"w":"Algo de presión puntual es normal; el problema es que sea permanente."}]},{"s":"psico_senales","v":[{"q":"¿Cuál es una señal de alerta de estrés?","o":["Problemas para dormir e irritabilidad","Hambre a la hora de almuerzo","Cansancio tras un día de mucho esfuerzo","Ganas de tomar vacaciones en verano"],"w":"Son señales para prestar atención y conversar a tiempo."},{"q":"Hace semanas duermes mal, estás irritable y te duele la cabeza. ¿Qué haces?","o":["Lo converso con mi jefatura o pido apoyo","Lo aguanto, ya se pasará","Tomo más café para rendir","Trabajo más horas para distraerme"],"w":"Reconocer las señales y pedir apoyo evita que empeore."},{"q":"¿Qué cambio en el trabajo puede indicar estrés en un compañero?","o":["Más errores, olvidos y discusiones que antes","Que pide instrucciones claras a la jefatura","Que toma su pausa a la hora indicada","Que pregunta antes de hacer una tarea nueva"],"w":"Los cambios de conducta son una señal de alerta."}]},{"s":"psico_carga","v":[{"q":"Tienes más pedidos de los que alcanzas a sacar en el turno. ¿Qué haces?","o":["Converso a tiempo con mi jefatura para priorizar","Me salto pasos de seguridad para avanzar","No digo nada y trabajo al límite","Me quedo después del turno sin avisar"],"w":"Hablar a tiempo permite ordenar prioridades sin arriesgarse."},{"q":"La jefatura te pide dos trabajos urgentes a la vez. ¿Qué es lo correcto?","o":["Preguntar cuál es prioritario","Hacer los dos a medias","Elegir el más fácil sin decir nada","Hacer los dos a máxima velocidad"],"w":"Pedir claridad es parte de manejar la carga de trabajo."},{"q":"Te das cuenta de que no alcanzarás a terminar la producción del turno. ¿Cuándo avisas?","o":["De inmediato, apenas lo noto","Al final del turno","Solo si me preguntan","Al día siguiente"],"w":"Avisar a tiempo permite reorganizar sin apuros ni riesgos."}]},{"s":"psico_grito","v":[{"q":"Un supervisor corrige un error gritando y descalificando frente a todos. ¿Cómo debe corregirse?","o":["Con respeto, explicando qué mejorar","Con gritos, para que no se repita","Con burlas, para que lo recuerde","En silencio, anotándolo en su hoja"],"w":"Corregir con respeto protege la salud y mejora el trabajo."},{"q":"Un jefe grita y humilla a un trabajador frente al equipo, una sola vez. Según la Ley Karin, puede ser:","o":["Acoso laboral, aunque ocurra una vez","Nada, porque no se repitió","Solo un mal día del jefe","Acoso solo si hay testigos que firmen"],"w":"Con la Ley Karin, el acoso laboral no requiere reiteración."},{"q":"¿Cuál de estas conductas es buen trato en el trabajo?","o":["Corregir con respeto, sin gritos ni sobrenombres","Poner sobrenombres, si todos se ríen","Gritar cuando hay apuro","Corregir en público para que todos aprendan"],"w":"El respeto también es seguridad."}]},{"s":"psico_apoyo","v":[{"q":"Un compañero se ve agotado e irritable hace semanas. Lo mejor es:","o":["Preguntarle cómo está y escucharlo sin juzgar","No meterme, es su problema","Contarles a todos para que lo ayuden","Decirle que falte unos días sin avisar"],"w":"Cuidarnos entre todos también es prevención."},{"q":"Llega un trabajador nuevo a la línea de paneles. ¿Qué es apoyo entre compañeros?","o":["Explicarle la tarea y sus riesgos","Dejar que aprenda solo","Hacerle bromas de bienvenida","Darle las tareas más pesadas"],"w":"Un equipo que se apoya trabaja mejor y más seguro."},{"q":"¿Por qué el apoyo entre compañeros es importante?","o":["Protege la salud mental de todos","Reemplaza a la jefatura","Permite terminar antes el turno","Así nadie tiene que avisar nada"],"w":"Es uno de los factores que más protegen la salud mental."}]},{"s":"psico_ayuda","v":[{"q":"Si tu malestar se debe al trabajo, ¿quién puede evaluarlo dentro del seguro de la Ley 16.744?","o":["La ACHS","Tu isapre o Fonasa","La Inspección del Trabajo","Solo un psicólogo particular"],"w":"La ACHS evalúa y atiende según la Ley 16.744."},{"q":"Te sientes sobrepasado por el trabajo. ¿A quién puedes recurrir en la empresa?","o":["A tu jefatura o al Delegado de SST","Solo a tu familia","A nadie, es mejor no decir","Solo a los compañeros de turno"],"w":"La jefatura y el Delegado de SST pueden ayudar a buscar soluciones."},{"q":"Pedir ayuda por un problema de salud mental es una señal de debilidad.","vf":false,"w":"Falso. Pedir ayuda a tiempo es una decisión responsable."}]},{"s":"psico_auto","v":[{"q":"Estás agotado y debes operar la sierra. ¿Qué es lo seguro?","o":["Avisar que no estoy bien antes de operar","Operar más rápido para terminar luego","Operar igual, pero con más cuidado","Tomar un energizante y seguir"],"w":"El cansancio aumenta los errores. Reconocerlo y avisar es autocuidado."},{"q":"¿Por qué el cansancio y el estrés aumentan los accidentes?","o":["Llevan a apurarse, saltarse pasos y distraerse","Porque las máquinas fallan más","Porque el EPP pierde efecto","No los aumentan si tienes experiencia"],"w":"Hacen más probables las acciones inseguras."},{"q":"Dormiste muy poco por un problema personal y te toca la rebajadora. ¿Qué haces?","o":["Le aviso a mi jefatura antes de partir","Opero igual sin decir nada","Pido a un compañero que me cubra a escondidas","Opero solo la mitad del turno sin avisar"],"w":"Decirlo antes de operar permite reorganizar la tarea sin riesgo."}]}]},{"id":"karin","sec":"todos","title":"Ley Karin: trabajo libre de acoso y violencia","thumb":"karin_intro","learn":[{"s":"karin_intro","t":"¿Qué es la Ley Karin?","x":"La <b>Ley 21.643</b>, vigente desde el <b>1 de agosto de 2024</b>, modificó el Código del Trabajo para <b>prevenir, investigar y sancionar</b> el acoso laboral, el acoso sexual y la violencia en el trabajo. Todas las personas tienen derecho a un trabajo libre de acoso y violencia, y el empleador debe protegerlo con medidas de prevención, un procedimiento de investigación y sanciones."},{"s":"karin_sexual","t":"Acoso sexual","x":"Son <b>requerimientos de carácter sexual, en forma indebida y por cualquier medio, no consentidos</b>, que amenacen o perjudiquen la situación laboral o las oportunidades en el empleo de quien los recibe. \"Por cualquier medio\" incluye comentarios, gestos, contacto físico y mensajes o fotos por celular o redes sociales. Puede venir de cualquier persona, sin importar su cargo."},{"s":"karin_laboral","t":"Acoso laboral","x":"Es toda agresión u hostigamiento, por cualquier medio, de la jefatura o de uno o más compañeros, que cause menoscabo, maltrato o humillación, o que amenace o perjudique la situación laboral. Con la Ley Karin <b>no requiere reiteración: basta una vez</b>. Ejemplos: gritar o insultar, humillar frente al equipo, aislar a alguien o quitarle sus tareas sin razón."},{"s":"karin_terceros","t":"Violencia en el trabajo","x":"Es la ejercida por <b>terceros</b> ajenos a la empresa, como <b>clientes, proveedores o usuarios</b>, contra los trabajadores. Por ejemplo, un chofer que insulta o amenaza a quien carga su camión en el patio, o un proveedor que agrede a quien recibe su despacho. La ley también la cubre: se previene y se puede denunciar igual que el acoso."},{"s":"karin_protocolo","t":"Protocolo y Reglamento Interno","x":"El empleador debe tener un <b>protocolo de prevención</b> del acoso sexual, el acoso laboral y la violencia en el trabajo (Código del Trabajo, art. 211-A), y un <b>procedimiento de investigación</b> en el <b>Reglamento Interno</b>. Ambos deben darse a conocer a los trabajadores. Tienes derecho a conocerlos: pregunta a tu jefatura dónde están."},{"s":"karin_denuncia","t":"Cómo denunciar","x":"La denuncia se presenta <b>ante el empleador</b> o ante la <b>Inspección del Trabajo</b>, por escrito o en forma verbal. Es <b>reservada</b>: la información se maneja cuidando la intimidad de las personas. Cuenta los hechos con el mayor detalle posible: qué pasó, cuándo, dónde y quién lo vio, y guarda los mensajes o pruebas que tengas.","k":"Si sufres o ves acoso, denúncialo: la denuncia es reservada."},{"s":"karin_resguardo","t":"Medidas de resguardo","x":"Al recibir una denuncia, el empleador debe adoptar de inmediato <b>medidas de resguardo</b> para proteger a la persona denunciante, por ejemplo:<ul><li>Separar los espacios físicos.</li><li>Redistribuir la jornada.</li><li>Derivar a atención psicológica temprana en la <b>ACHS</b>.</li></ul>Estas medidas se toman mientras se investiga, sin esperar el resultado."},{"s":"karin_represalia","t":"Sin represalias","x":"No se permiten <b>represalias</b> contra quien denuncia o declara como testigo: no se le puede castigar, hostigar, cambiar de turno como castigo ni perjudicar por haber denunciado. Si ocurre, también se puede reclamar ante la Inspección del Trabajo. Denunciar de buena fe es un derecho protegido."},{"s":"karin_testigo","t":"No seas testigo silencioso","x":"Si ves una situación de acoso o violencia:<ul><li>No participes ni te rías.</li><li>Acompaña a la persona afectada.</li><li>Oriéntala sobre cómo denunciar.</li><li>Si te citan como testigo, cuenta lo que viste.</li></ul>El silencio permite que el maltrato continúe. No enfrentes al agresor con violencia: avisa y deja que actúe el procedimiento.","k":"Nunca te quedes callado ni te rías ante un acoso."},{"s":"karin_auto","t":"Autocuidado: la \"broma\" que daña","x":"Así como la mayoría de los accidentes se relacionan con una acción insegura, el acoso suele empezar con conductas que se normalizan: bromas pesadas, sobrenombres, reenviar fotos o videos de un compañero. La decisión segura: <b>parar, no reenviar, pedir que se borre, respetar el \"no\"</b> y avisar. Si a alguien le duele o lo humilla, no es broma."}],"quiz":[{"s":"karin_intro","v":[{"q":"¿Desde cuándo rige la Ley Karin (Ley 21.643)?","o":["1 de agosto de 2024","1 de enero de 2024","1 de febrero de 2025","1 de agosto de 2025"],"w":"Rige desde el 1 de agosto de 2024."},{"q":"¿Qué conductas busca prevenir, investigar y sancionar la Ley Karin?","o":["Acoso laboral, acoso sexual y violencia laboral","Solo el acoso sexual entre compañeros","Solo los accidentes del trabajo graves","Solo las peleas con golpes en la faena"],"w":"Cubre las tres conductas."},{"q":"¿Qué número tiene la Ley Karin?","o":["Ley 21.643","Ley 16.744","Ley 20.949","Ley 20.096"],"w":"La Ley 21.643 modificó el Código del Trabajo en esta materia."}]},{"s":"karin_laboral","v":[{"q":"Para que exista acoso laboral, la conducta debe repetirse varias veces.","vf":false,"w":"Falso. Con la Ley Karin basta una sola vez."},{"q":"Un supervisor humilla a un trabajador frente al equipo una sola vez. Según la Ley Karin, eso:","o":["Puede ser acoso laboral","No es acoso porque no se repitió","Solo es acoso si hay golpes","Es acoso solo si queda por escrito"],"w":"El acoso laboral ya no requiere reiteración."},{"q":"¿Quién puede cometer acoso laboral?","o":["La jefatura o uno o más compañeros","Solo la jefatura directa","Solo el dueño de la empresa","Solo personas de otra empresa"],"w":"Puede venir de la jefatura o de los propios compañeros."}]},{"s":"karin_sexual","v":[{"q":"Un compañero envía mensajes de carácter sexual por celular a una colega, que no los quiere. Eso puede ser:","o":["Acoso sexual","Un asunto privado fuera del trabajo","Violencia de terceros","Acoso solo si ocurre en la planta"],"w":"Son requerimientos sexuales no consentidos, por cualquier medio, incluido el celular."},{"q":"¿Qué elemento es clave para que un requerimiento sexual sea acoso?","o":["Que no sea consentido por quien lo recibe","Que exista contacto físico","Que ocurra dentro del horario","Que lo haga un jefe"],"w":"Sin consentimiento, no corresponde, por ningún medio y venga de quien venga."},{"q":"Un trabajador hace comentarios y gestos sexuales a una compañera; ella le pide que pare y él sigue. ¿Qué es?","o":["Acoso sexual: ella puede denunciarlo","Una broma, porque no hubo contacto","Acoso solo si queda grabado","Algo que ella debe resolver sola"],"w":"Comentarios y gestos también son \"cualquier medio\"."}]},{"s":"karin_terceros","v":[{"q":"El chofer de un cliente insulta y amenaza a un ayudante durante la carga del camión. Eso es:","o":["Violencia en el trabajo","Acoso laboral entre compañeros","Algo normal en el patio","Acoso sexual"],"w":"La violencia de clientes, proveedores o usuarios está cubierta por la ley."},{"q":"Según la Ley Karin, ¿quiénes ejercen la \"violencia en el trabajo\"?","o":["Terceros como clientes, proveedores o usuarios","Solo la jefatura","Solo los compañeros","Solo los contratistas dentro de la nave"],"w":"Es la violencia que viene de personas ajenas a la empresa."},{"q":"Un proveedor amenaza a la persona que recibe su despacho. ¿Se puede denunciar?","o":["Sí: la ley cubre la violencia de terceros","No, porque no es trabajador de la empresa","Solo si hubo golpes","Solo si el proveedor lo acepta"],"w":"La violencia de terceros se previene y se denuncia igual que el acoso."}]},{"s":"karin_denuncia","v":[{"q":"¿Ante quién se puede presentar una denuncia por acoso?","o":["Ante el empleador o la Inspección del Trabajo","Solo ante Carabineros, como un delito","Solo ante la ACHS, por ser salud","Solo ante el sindicato de la empresa"],"w":"Ambos canales están disponibles y la denuncia es reservada."},{"q":"¿Cómo se maneja la información de una denuncia?","o":["En forma reservada, cuidando la intimidad","Se publica para que todos sepan","Se comenta en la reunión de equipo","Se informa a todos los posibles testigos"],"w":"La reserva protege a las personas involucradas."},{"q":"¿Qué conviene incluir al denunciar?","o":["Qué pasó, cuándo, dónde y quién lo vio","Solo mi nombre","Solo el nombre del acusado","Mi opinión sobre la persona"],"w":"Mientras más detalles y pruebas, mejor se puede investigar."}]},{"s":"karin_resguardo","v":[{"q":"¿Qué es una medida de resguardo?","o":["Separar espacios o cambiar la jornada de quien denuncia","Trasladar a quien denuncia a otra área como castigo","Suspender la investigación hasta que todo se calme","Pedir a las dos partes que se reconcilien"],"w":"Protegen a la persona afectada mientras se investiga."},{"q":"Al recibir una denuncia, ¿qué debe hacer primero el empleador?","o":["Proteger a la persona denunciante","Esperar el resultado para actuar","Pedir que lo arreglen entre ellos","Despedir a las dos personas"],"w":"Las medidas de resguardo se toman de inmediato, sin esperar el resultado."},{"q":"¿Dónde puede recibir atención psicológica temprana quien denuncia?","o":["En la ACHS","Solo en forma particular","En la Inspección del Trabajo","En el sindicato"],"w":"La derivación a la ACHS es una de las medidas de resguardo."}]},{"s":"karin_represalia","v":[{"q":"Después de una denuncia, se puede castigar al denunciante si la jefatura no está de acuerdo.","vf":false,"w":"Falso. No se permiten represalias contra quien denuncia o declara."},{"q":"A un compañero le cambian el turno como castigo por declarar como testigo. Eso es:","o":["Una represalia prohibida","Una medida normal de la jefatura","Una medida de resguardo","Algo permitido si el turno es mejor pagado"],"w":"Perjudicar a un testigo por declarar es una represalia."},{"q":"¿A quiénes protege la prohibición de represalias?","o":["A quien denuncia y a quien declara como testigo","Solo a quien presentó la denuncia","Solo a la jefatura que investiga","Solo a la persona acusada mientras tanto"],"w":"Denunciar y declarar de buena fe son derechos protegidos."}]},{"s":"karin_burla","v":[{"q":"Unos compañeros se ríen y le ponen sobrenombres ofensivos a una colega. ¿Cuál es la reacción correcta?","o":["No participar, acompañarla y orientarla a denunciar","Reírme para no quedar fuera del grupo","No meterme, no es mi problema","Decirle a ella que no se lo tome a mal"],"w":"No ser testigo silencioso: el silencio permite que el maltrato siga."},{"q":"¿Qué significa no ser un testigo silencioso?","o":["Acompañar a la persona y orientarla a denunciar","Grabar todo y subirlo a redes sociales","Enfrentar al agresor a golpes","Esperar que la persona lo resuelva sola"],"w":"Se apoya a la persona y se usa el procedimiento, sin violencia."},{"q":"Si te citan como testigo en una investigación, lo correcto es contar lo que viste.","vf":true,"w":"Verdadero. El silencio permite que el maltrato continúe."}]},{"s":"karin_protocolo","v":[{"q":"El procedimiento de investigación del acoso y la violencia debe estar en:","o":["El Reglamento Interno","El contrato de trabajo","El check list diario","La hoja de vida del trabajador"],"w":"Además, el protocolo de prevención es obligatorio (Código del Trabajo, art. 211-A)."},{"q":"¿Qué documento debe tener el empleador para prevenir el acoso y la violencia?","o":["Un protocolo de prevención","Solo un buzón de sugerencias","Solo una charla al año","Un registro de asistencia"],"w":"El art. 211-A del Código del Trabajo exige el protocolo."},{"q":"Quieres conocer el protocolo de prevención de {EMP}. ¿Qué haces?","o":["Pregunto a mi jefatura dónde está","Nada: es solo para jefaturas","Lo pido en la Inspección del Trabajo","Nada: no es obligatorio tenerlo"],"w":"Los trabajadores tienen derecho a conocer el protocolo y el procedimiento."}]},{"s":"karin_auto","v":[{"q":"Un compañero reenvía al grupo una foto burlesca de otro. ¿Qué es lo correcto?","o":["No reenviarla, pedir que la borre y avisar","Reenviarla, es solo una broma","Comentarla, pero sin reenviarla","Borrarla de mi teléfono y no decir nada"],"w":"Si a alguien le duele, no es broma. Parar a tiempo protege a todos."},{"q":"¿Cuándo una broma deja de ser broma?","o":["Cuando a la persona le duele o la humilla","Solo cuando hay golpes","Solo cuando la ve la jefatura","Nunca, las bromas son parte del trabajo"],"w":"El acoso suele empezar con conductas que se normalizan."},{"q":"Te llega por WhatsApp un video que ridiculiza a un compañero de la planta. ¿Qué haces?","o":["No lo reenvío, pido que lo borren y aviso","Lo reenvío solo a un amigo de confianza","Lo guardo por si acaso","Respondo con risas y sigo"],"w":"Reenviar también es participar en el daño."}]}]},{"id":"maquinas","sec":"planta","title":"Sierras y máquinas","thumb":"maq_resguardo","mins":5,"learn":[{"s":"maq_planta","t":"Las máquinas de la planta","x":"En la planta se trabaja con <b>sierra escuadradora o circular, rebajadora (router), encoladora y prensa</b>. Todas tienen partes que giran, cortan o aprietan con una fuerza mucho mayor que la de tu mano. <b>Solo opera una máquina quien fue capacitado y autorizado</b> por la jefatura. Un error de un segundo puede costar un dedo o una mano."},{"s":"maq_resguardo","t":"La protección está por algo","x":"Las sierras y máquinas tienen <b>resguardos</b> que separan tus manos de la hoja y de las partes móviles. <b>Nunca se retiran ni se anulan</b> para \"trabajar más rápido\". Antes de partir, revisa que el resguardo esté puesto y bien fijo. Si falta, está flojo o dañado, <b>la máquina no se usa</b> y se avisa a la jefatura.","k":"Nunca retires ni anules un resguardo: sin él, la máquina no se usa."},{"s":"maq_empujador","t":"Manos lejos de la hoja","x":"Para piezas pequeñas o el final del corte usa un <b>empujador</b>. Nunca acerques los dedos a la hoja: los guantes no protegen del corte y no son excusa para acercar la mano. Tampoco te pongas justo detrás de la línea de corte: la pieza puede salir despedida hacia atrás con fuerza, lo que se llama <b>contragolpe</b>."},{"s":"maq_router","t":"Rebajadora (router) de paneles","x":"<ul><li>Fija bien el panel antes de rebajar.</li><li>Manos fuera de la zona de la fresa y del recorrido del cabezal.</li><li>Al apagar, <b>la fresa sigue girando un rato por inercia</b>: espera que pare del todo.</li><li>Retira virutas solo con la máquina detenida.</li></ul>Apagada no es lo mismo que detenida."},{"s":"maq_atrap","t":"Encolado y prensa: atrapamiento","x":"Entre los <b>rodillos de la encoladora</b> y entre los <b>platos de la prensa</b> hay puntos de atrapamiento: lo que entra no sale. Nunca acomodes un panel con la mano, un listón o el pie mientras la prensa baja o los rodillos giran. Si algo queda mal, <b>detén con la parada de emergencia</b> y avisa. Si ves a alguien con la mano adentro, detén la máquina."},{"s":"maq_suelto","t":"Nada suelto","x":"Ropa suelta, mangas abiertas, <b>anillos, cadenas, pulseras o pelo largo suelto</b> pueden ser atrapados en segundos por partes que giran, y arrastrar tu mano o tu cabeza hacia la máquina. Antes de operar: <b>pelo tomado y recogido bajo el casco, overol abrochado y sin joyas</b>. Lo que cuelga, se engancha."},{"s":"maq_limpiar","t":"Nunca limpiar con la máquina en marcha","x":"Retirar recortes, virutas o polvo con la máquina funcionando es causa típica de cortes graves y amputaciones. <b>Primero detén y espera que pare del todo</b>. Usa escobilla o aspiración, nunca la mano ni aire comprimido. Si debes meter las manos o limpiar a fondo dentro de la máquina, <b>aplica el bloqueo con candado y tarjeta</b>."},{"s":"maq_loto","t":"Bloqueo y etiquetado (LOTO)","x":"Para destrabar, limpiar a fondo o hacer mantención:<ul><li>1. Detén la máquina.</li><li>2. Desconecta la energía.</li><li>3. Pon <b>tu candado y tu tarjeta</b>.</li><li>4. Verifica que no parte.</li></ul>Si trabajan varias personas, <b>cada una pone su propio candado</b>. Solo quien puso el candado lo retira.","k":"Apagar no es bloquear: pon tu candado y tarjeta antes de meter las manos."},{"s":"maq_epp","t":"Tu EPP y la parada de emergencia","x":"En la sierra y la rebajadora usa <b>lentes de seguridad</b> (saltan astillas), <b>protector auditivo</b> y <b>mascarilla</b> para el polvo de madera, además de casco, overol y zapatos de seguridad. Antes de partir, <b>ubica la parada de emergencia</b> y asegúrate de que funciona. Si no funciona, la máquina no se usa y se avisa a la jefatura."},{"s":"maq_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una acción insegura. En máquinas, las típicas son <b>sacar un recorte con la mano \"porque es un segundo\"</b>, retirar un resguardo o saltarse el bloqueo. La decisión segura: detener, esperar y bloquear. Avisa de inmediato los resguardos dañados o las paradas de emergencia que no funcionan."}],"quiz":[{"s":"maq_resguardo","v":[{"q":"Si el resguardo de la sierra molesta, puedo sacarlo con cuidado mientras corto.","vf":false,"w":"Falso. El resguardo nunca se retira; si falta o falla, la máquina no se usa."},{"q":"El resguardo de la sierra está flojo y se mueve al cortar. ¿Qué haces?","o":["Detengo, no la uso y aviso","Sigo cortando con más cuidado","Lo saco para que no estorbe","Lo amarro con alambre y sigo"],"w":"Un resguardo flojo no protege: la máquina se detiene y se avisa."},{"q":"¿Para qué sirve el resguardo de la sierra?","o":["Separa las manos de la hoja y las partes móviles","Hace que el corte salga más recto y limpio","Evita que el panel se ensucie con polvo","Solo reduce el ruido y las astillas de la hoja"],"w":"Es la barrera entre tu mano y la hoja."}]},{"s":"maq_q_atasco","v":[{"q":"Se atascó un trozo de panel en la máquina. ¿Qué haces primero?","o":["Detengo, desconecto y pongo mi candado y tarjeta","Lo saco rápido con la mano","Lo empujo con un palo con la máquina andando","Apago con el botón y lo saco de inmediato"],"w":"Antes de meter las manos: detener, desenergizar y bloquear."},{"q":"La sierra se trabó con un recorte y ya la detuviste. ¿Qué sigue antes de meter las manos?","o":["Desconectar, poner candado y tarjeta, y verificar","Meter la mano rápido, ya está detenida","Pedir a un compañero que vigile el botón","Esperar un minuto y meter la mano"],"w":"Detenida no es bloqueada: alguien podría encenderla."},{"q":"Después de poner tu candado y tarjeta, ¿qué haces antes de meter las manos?","o":["Verifico que la máquina no parte","Nada más, ya está bloqueada","Saco la tarjeta para que no estorbe","Aviso por radio y empiezo"],"w":"El último paso del bloqueo es verificar que no hay energía."}]},{"s":"maq_sinres","v":[{"q":"Llegas a tu puesto y la sierra no tiene su resguardo sobre la hoja. ¿Qué haces?","o":["No la uso y aviso a mi jefatura","La uso con cuidado, solo cortes cortos","La uso con guantes gruesos","Corto rápido y aviso al final del turno"],"w":"Sin resguardo, la máquina no se usa."},{"q":"¿Cuándo se puede usar una sierra sin su resguardo?","o":["Nunca","Para piezas pequeñas","Si el operador tiene experiencia","Si la jefatura está presente"],"w":"No hay excepciones: el resguardo siempre va puesto."},{"q":"Un compañero sacó el resguardo para \"trabajar más rápido\". ¿Qué le dices?","o":["Que lo reponga y no use la sierra sin él","Que está bien si es solo un corte","Que use lentes y siga","Que lo saque solo en cortes rectos"],"w":"Retirar un resguardo es una acción insegura típica."}]},{"s":"maq_empujador","v":[{"q":"Para cortar una pieza pequeña en la sierra uso:","o":["Un empujador","Mis dedos, con cuidado","Guantes gruesos para acercar la mano","La palma abierta sobre la pieza"],"w":"El empujador mantiene tus manos lejos de la hoja."},{"q":"Al final del corte, la pieza queda muy cerca de la hoja. ¿Cómo la terminas de pasar?","o":["Con el empujador, manos lejos de la hoja","Con la mano, porque falta poco","Tirándola desde el otro lado de la hoja","Con la palma abierta, que es más segura"],"w":"El tramo final es el más peligroso para los dedos."},{"q":"¿Por qué no debes ubicarte justo detrás de la línea de corte?","o":["Por el contragolpe: la pieza sale hacia atrás","Porque tapas la luz","Porque el polvo sale hacia adelante","Porque ahí no alcanzas el interruptor"],"w":"El contragolpe puede lanzar la pieza con mucha fuerza."}]},{"s":"maq_loto","v":[{"q":"¿Quién puede retirar el candado de bloqueo?","o":["Solo quien lo puso","Cualquier compañero del turno","El que termine primero la tarea","El que necesite usar la máquina"],"w":"Solo la persona que instaló su candado lo retira."},{"q":"Dos personas trabajan dentro de la misma máquina. ¿Cómo se bloquea?","o":["Cada una pone su propio candado y tarjeta","Basta un candado para los dos","Pone el candado el que llegó primero","Basta con apagar desde el tablero"],"w":"Cada persona se protege con su propio candado."},{"q":"Si apagaste la máquina desde su botón, ya está bloqueada y puedes meter las manos.","vf":false,"w":"Falso. Apagar no es bloquear: hay que desconectar, poner candado y tarjeta, y verificar."}]},{"s":"maq_suelto","v":[{"q":"¿Qué NO debes usar al operar una sierra o la rebajadora?","o":["Ropa suelta, anillos o pelo suelto","Lentes de seguridad bien ajustados","Protector auditivo tipo fono","Zapatos de seguridad con puntera"],"w":"Lo que cuelga puede ser atrapado por las partes que giran."},{"q":"Tienes el pelo largo y vas a operar la rebajadora. ¿Qué haces?","o":["Lo tomo y lo recojo bajo el casco","Lo dejo suelto si no es muy largo","Lo amarro solo si me molesta","Me alejo un poco más de la fresa"],"w":"El pelo suelto puede enrollarse en segundos."},{"q":"¿Por qué hay que sacarse anillos y pulseras para operar máquinas?","o":["Pueden engancharse y arrastrar la mano","Se rayan con el polvo","Molestan al usar guantes","Interfieren con la parada de emergencia"],"w":"Un anillo enganchado arrastra el dedo hacia la máquina."}]},{"s":"maq_routerOff","v":[{"q":"Apagaste la rebajadora y la fresa sigue girando. ¿Qué haces?","o":["Espero que se detenga por completo","Retiro la viruta rápido con la mano","La freno con un trozo de madera","Saco el panel mientras se detiene"],"w":"La fresa gira por inercia: apagada no es detenida."},{"q":"¿Por qué \"apagada\" no es lo mismo que \"detenida\" en la rebajadora?","o":["La fresa sigue girando un rato por inercia","Porque queda energía en el panel","Porque el motor vuelve a partir solo","Son lo mismo: al apagar se detiene"],"w":"Hay que esperar que la fresa pare del todo."},{"q":"La fresa de la rebajadora puede seguir girando un rato después de apagarla.","vf":true,"w":"Verdadero. Por eso se espera que se detenga por completo."}]},{"s":"maq_prensa","v":[{"q":"Un panel quedó desalineado mientras la prensa baja. ¿Qué haces?","o":["Detengo con la parada de emergencia y aviso","Lo acomodo rápido con la mano","Lo empujo con un listón mientras baja","Espero que baje y lo acomodo apretado"],"w":"Entre los platos de la prensa hay atrapamiento: la mano nunca entra."},{"q":"¿Dónde está el riesgo de atrapamiento en la prensa?","o":["Entre los platos que se cierran","Solo en el tablero eléctrico","En las patas de la prensa","Solo en el piso alrededor"],"w":"Donde algo se cierra, tu mano no entra."},{"q":"Un compañero mete la mano entre los platos de la prensa para ajustar un panel. ¿Qué haces?","o":["Uso la parada de emergencia y le pido que salga","Lo ayudo a ajustar para que termine rápido","Lo dejo, él tiene más experiencia que yo","Le aviso a la jefatura al final del turno"],"w":"Detener la máquina de inmediato puede salvarle la mano."}]},{"s":"maq_limpiar","v":[{"q":"Hay virutas sobre la mesa de la sierra y la hoja está girando. ¿Qué haces?","o":["Detengo, espero que pare y limpio con escobilla","Las saco con la mano, con cuidado y lejos de la hoja","Las soplo con aire comprimido desde lejos","Las empujo con un trozo de panel mientras corto"],"w":"Nunca se limpia con la máquina en marcha."},{"q":"¿Con qué se limpian los recortes y el polvo de la máquina?","o":["Escobilla o aspiración, con la máquina detenida","Aire comprimido, con la máquina andando","La mano con guante, con la máquina detenida","Un trapo, mientras la hoja gira lento"],"w":"Escobilla o aspiración, siempre con la máquina detenida."},{"q":"Para limpiar a fondo dentro de la máquina, ¿qué debes hacer?","o":["Aplicar el bloqueo con candado y tarjeta","Solo apagarla desde el botón","Solo esperar que la hoja pare","Pedir a alguien que no la encienda"],"w":"Si las manos entran a la máquina, se bloquea."}]},{"s":"maq_epp","v":[{"q":"La parada de emergencia de la sierra no funciona. ¿Qué haces?","o":["No la uso y aviso a mi jefatura","La uso igual, con más cuidado","La reparo yo mismo","La uso solo para cortes cortos"],"w":"Sin parada de emergencia, la máquina no se usa."},{"q":"¿Qué debes hacer antes de partir con la sierra?","o":["Ubicar la parada de emergencia y tener el EPP puesto","Revisar solo que esté enchufada","Encenderla y probar con la mano cerca","Sacar el resguardo para revisar la hoja"],"w":"EPP puesto y parada ubicada antes de partir."},{"q":"Además de casco y zapatos, ¿qué EPP corresponde en la sierra y la rebajadora?","o":["Lentes, protector auditivo y mascarilla","Solo guantes de cuero y lentes","Solo lentes de seguridad y fonos","Careta facial, sin otros elementos"],"w":"Saltan astillas, hay ruido y polvo de madera."}]}]},{"id":"herramientas","sec":"planta","title":"Herramientas eléctricas portátiles","thumb":"herr_esmeril","mins":5,"learn":[{"s":"herr_revisar","t":"Revísala antes de enchufarla","x":"Antes de cada uso mira el <b>cable, el enchufe, la carcasa y el interruptor</b>. Cable pelado o parchado con cinta, enchufe quebrado, carcasa rota o interruptor que no corta: <b>no se usa</b>. Sepárala, márcala como dañada y avisa; solo la repara un técnico autorizado. Trasládala siempre <b>tomada del mango</b>, nunca colgando del cable."},{"s":"herr_esmeril","t":"Esmeril angular","x":"<ul><li>Siempre con su <b>protección del disco</b> y su mango lateral.</li><li>Tómalo con las dos manos.</li><li>Dirige las chispas hacia el piso, lejos de personas, del EPS y de otros materiales que arden.</li><li>Espera que el disco pare antes de dejarlo.</li></ul>Sin protección, un disco que se rompe lanza trozos hacia tu cara y tus manos.","k":"Nunca saques la protección del disco del esmeril."},{"s":"herr_disco","t":"El disco correcto","x":"<ul><li>Las <b>RPM del disco</b> deben ser iguales o mayores que las de la máquina: por ejemplo, disco de 13.300 RPM en un esmeril de 11.000 RPM.</li><li>Diámetro adecuado a la máquina y a su protección.</li><li>Disco de corte para cortar; de desbaste para desbastar.</li><li>Sin trizaduras, golpes ni vencido.</li></ul>Un disco que revienta lanza trozos como proyectiles."},{"s":"herr_desenchufar","t":"Desenchufa para cambiar accesorios","x":"Para cambiar <b>disco, broca u hoja</b>, o para limpiar: <b>desenchufa la herramienta o saca la batería</b>. Apagarla no basta: un gatillo apretado sin querer basta para un accidente. Al terminar, <b>retira la llave de ajuste o del mandril</b> y revisa que el accesorio quedó bien apretado antes de enchufar.","k":"Desenchufa o saca la batería antes de cambiar un accesorio."},{"s":"herr_circular","t":"Sierra circular de mano","x":"<ul><li>La <b>protección inferior</b> debe volver sola: nunca la amarres abierta. Si no vuelve, la sierra no se usa.</li><li>Pieza apoyada y fija con prensa, nunca sostenida con la mano.</li><li>Cuerpo fuera de la línea de corte, por el contragolpe.</li><li>Espera que la hoja pare antes de dejarla.</li></ul>"},{"s":"herr_caladora","t":"Caladora","x":"<ul><li>Base bien apoyada sobre la pieza.</li><li><b>Mira debajo</b>: la hoja sale por abajo; nada de manos, cables ni mesa en su camino.</li><li>Hoja adecuada al material y bien apretada.</li><li>Saca la hoja de la pieza solo cuando se haya detenido.</li></ul>La hoja corta por arriba y por debajo de la pieza."},{"s":"herr_taladro","t":"Taladro","x":"<ul><li>Sujeta la pieza con <b>prensa</b>, no con la mano.</li><li>Broca bien apretada y llave del mandril retirada.</li><li>Usa el <b>mango lateral</b>: si la broca se traba, el taladro gira con fuerza y puede torcerte la muñeca.</li><li>Si se traba, <b>suelta el gatillo de inmediato</b>.</li><li>Mangas ajustadas y pelo tomado.</li></ul>"},{"s":"herr_cables","t":"Cables y extensiones","x":"<ul><li>Extensiones en buen estado, sin uniones con cinta.</li><li><b>Desenrolla completo el carrete</b>: enrollado se calienta.</li><li>No pases cables por agua ni por bordes filosos, ni los dejes cruzando pasillos.</li><li>Si un cable está en el agua, desconecta desde el enchufe, alejado del charco, y avisa.</li></ul>Cable dañado o mojado puede dar una descarga eléctrica."},{"s":"herr_epp","t":"Tu EPP con herramientas","x":"<b>Protección ocular siempre.</b> Con esmeril: lentes de seguridad y, encima, <b>careta facial</b>, porque las partículas pueden entrar por los bordes de la careta. Además, protector auditivo y guantes según la tarea, y mascarilla si cortas madera u OSB. Pelo tomado y nada colgando. La empresa entrega este EPP sin costo."},{"s":"herr_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una acción insegura. Con herramientas, las típicas son <b>sacar la protección del esmeril</b>, montar un disco que \"igual calza\" o usar una herramienta con el cable dañado. La decisión segura: protección puesta, disco correcto y herramienta revisada. Avisa las herramientas dañadas y sepáralas para que nadie las use."}],"quiz":[{"s":"herr_cablePelado","v":[{"q":"El cable de la herramienta está pelado. ¿Qué haces?","o":["No la uso, la separo, la marco y aviso","Le pongo cinta aislante y sigo","La uso con guantes de cuero","La uso un rato y aviso al final"],"w":"Herramienta dañada no se usa: se separa y se informa."},{"q":"¿Cuál condición obliga a dejar de usar una herramienta eléctrica?","o":["Cable parchado con cinta o carcasa rota","Que tenga polvo en la carcasa","Que esté tibia después de usarla","Que el cable sea largo"],"w":"Cualquier daño en cable, enchufe o carcasa la deja fuera de uso."},{"q":"¿Quién puede reparar una herramienta eléctrica dañada?","o":["Un técnico autorizado","Cualquier trabajador con experiencia","El que la estaba usando","El jefe de turno, en el mismo puesto"],"w":"Una reparación improvisada puede dejarla con riesgo de descarga."}]},{"s":"herr_q_cambio","v":[{"q":"Puedo cambiar el disco del esmeril con la máquina enchufada si no aprieto el gatillo.","vf":false,"w":"Falso. Siempre se desenchufa, o se saca la batería, antes de cambiar un accesorio."},{"q":"Vas a cambiar el disco del esmeril. ¿Qué haces primero?","o":["Lo desenchufo","Lo apago y lo dejo enchufado","Pongo el seguro del gatillo","Pido que nadie toque el enchufe"],"w":"Apagarla no basta: un gatillo apretado sin querer causa el accidente."},{"q":"Terminaste de cambiar el disco. ¿Qué revisas antes de enchufar?","o":["Que saqué la llave y el disco quedó apretado","Que el disco esté tibio y bien centrado","Nada, solo enchufo y pruebo el gatillo","Que el gatillo quede apretado con el seguro"],"w":"Una llave olvidada o un disco suelto salen despedidos al partir."}]},{"s":"herr_q_disco","v":[{"q":"¿Qué disco puedes montar en el esmeril?","o":["RPM iguales o mayores, diámetro correcto y sin daños","RPM menores, si es de buena marca","Cualquiera que calce en el eje, si es nuevo","Uno más grande, si aprieto bien la tuerca"],"w":"Un disco con menos RPM, más grande o trizado puede reventar."},{"q":"El esmeril gira a 11.000 RPM. ¿Qué disco sirve?","o":["Uno de 13.300 RPM","Uno de 8.500 RPM","Uno de 10.000 RPM","Cualquiera: las RPM no importan"],"w":"Las RPM del disco deben ser iguales o mayores que las de la máquina."},{"q":"Vas a desbastar una pieza metálica con el esmeril. ¿Qué disco usas?","o":["Uno de desbaste","Uno de corte, más delgado","El que esté montado","Uno de corte gastado"],"w":"El disco de corte es delgado y se puede romper si se usa para desbastar."}]},{"s":"herr_epp","v":[{"q":"¿Qué protección ocular corresponde al usar el esmeril angular?","o":["Lentes de seguridad y, encima, careta facial","Solo careta facial, sin lentes","Solo lentes oscuros de sol","Ninguna, si es un trabajo rápido"],"w":"La careta complementa a los lentes: no los reemplaza."},{"q":"¿Por qué la careta facial no reemplaza a los lentes de seguridad?","o":["Las partículas pueden entrar por los bordes","Porque la careta es solo para soldar","Porque siempre se empaña","Sí los reemplaza: con careta basta"],"w":"Por eso con esmeril se usan ambos."},{"q":"Vas a cortar OSB con la sierra circular de mano. ¿Qué EPP corresponde?","o":["Lentes, protector auditivo y mascarilla","Solo guantes de cuero y casco","Solo careta facial y guantes","Solo protector auditivo y casco"],"w":"Hay astillas, ruido y polvo de madera."}]},{"s":"herr_cables","v":[{"q":"Usas una extensión de carrete. ¿Cómo debe estar?","o":["Desenrollada entera: enrollada se calienta","Enrollada, para que no estorbe en el paso","Desenrollada solo hasta donde alcance","Enrollada, pero lejos del agua y del polvo"],"w":"El cable enrollado acumula calor y puede derretirse."},{"q":"La extensión tiene una unión hecha con cinta aislante. ¿Qué haces?","o":["No la uso y aviso","La uso si la cinta está firme","La uso solo en lugares secos","Le agrego más cinta"],"w":"Una unión con cinta es un punto de descarga."},{"q":"¿Por dónde no deben pasar los cables de las herramientas?","o":["Por agua, bordes filosos ni pasillos","Pegados a la pared","Por el costado de la mesa de trabajo","Detrás de la máquina, lejos del paso"],"w":"El agua y los bordes filosos dañan el cable; en el pasillo, alguien tropieza."}]},{"s":"cables","v":[{"q":"Hay agua en el piso donde pasa la extensión. ¿Cuál es el riesgo principal?","o":["Descarga eléctrica","Solo un tropiezo","Que se oxide la herramienta","Que la herramienta pierda potencia"],"w":"Agua y electricidad no se mezclan: aleja el cable y avisa."},{"q":"Ves una extensión pasando por un charco. ¿Qué haces?","o":["Desconecto desde el enchufe, alejado del agua, y aviso","Tomo el cable con la mano para sacarlo del agua","Sigo trabajando si la herramienta funciona","Pongo un cartón sobre el charco"],"w":"Nunca se toma un cable energizado que está en el agua."},{"q":"Una extensión cruzando un pasillo es un riesgo de tropiezo y de daño al cable.","vf":true,"w":"Verdadero. Los cables no se dejan cruzando pasillos."}]},{"s":"herr_q_circular","v":[{"q":"La protección inferior de la sierra circular de mano no vuelve sola. ¿Qué haces?","o":["No la uso y aviso","La amarro abierta, así corta mejor","La uso con más cuidado","La empujo con el dedo después de cada corte"],"w":"Esa protección cubre la hoja al terminar el corte. Si no vuelve, la sierra no se usa."},{"q":"Al cortar un panel con la sierra circular de mano, ¿dónde va tu cuerpo?","o":["Fuera de la línea de corte, por el contragolpe","Detrás de la sierra, en línea con la hoja","Sobre la pieza, para afirmarla","Al frente, para ver mejor"],"w":"El contragolpe lanza la sierra hacia atrás, en la línea de corte."},{"q":"La pieza a cortar con la sierra circular es pequeña. ¿Cómo la sujetas?","o":["Apoyada y fija con prensa","Con la mano libre, lejos de la hoja","Con el pie sobre la pieza","Un compañero la sostiene"],"w":"Nunca se sostiene la pieza con la mano mientras se corta."}]},{"s":"herr_q_caladora","v":[{"q":"Antes de cortar con la caladora, ¿qué revisas debajo de la pieza?","o":["Que no haya manos, cables ni mesa en el camino","Nada: la hoja corta solo por arriba","Que mi otra mano sostenga bajo el corte","Que la hoja esté tibia para cortar mejor"],"w":"La hoja de la caladora sale por debajo de la pieza."},{"q":"¿Cuándo sacas la hoja de la caladora de la pieza?","o":["Cuando la hoja se detuvo","Mientras funciona, para ganar tiempo","Apenas suelto el gatillo","Cuando va a media velocidad"],"w":"La hoja en movimiento puede golpear y saltar."},{"q":"¿Por qué debes mirar debajo de la pieza antes de cortar con la caladora?","o":["La hoja sale por abajo y corta lo que haya","Porque el polvo cae hacia arriba","Porque la base se calienta","No hace falta: corta solo arriba"],"w":"La hoja también corta por debajo."}]},{"s":"herr_esmerilMal","v":[{"q":"El disco nuevo es más grande y no cabe con la protección. Un compañero dice \"sácale la protección\". ¿Qué haces?","o":["No lo monto: uso el disco correcto y aviso","Le saco la protección, es un corte corto","Corto lejos de los demás, sin protección","Lo monto y uso careta para compensar"],"w":"Retirar la protección es una acción insegura típica. El disco debe tener el diámetro y las RPM correctos."},{"q":"¿Qué pasa si montas un disco más grande que el que admite el esmeril?","o":["Supera su velocidad segura y puede reventar","Corta más rápido y con más seguridad","Solo hace más ruido y vibra un poco","Nada, si la tuerca queda bien firme"],"w":"Además, la protección ya no lo cubre."},{"q":"Tu esmeril quedó sin la protección del disco. ¿Qué haces?","o":["No lo uso hasta que tenga su protección","Lo uso con careta facial","Lo uso para cortes cortos","Lo uso tomándolo con las dos manos"],"w":"Sin protección, un disco roto lanza trozos hacia ti."}]},{"s":"herr_taladro","v":[{"q":"Vas a perforar una pieza pequeña con el taladro. ¿Cómo la sujetas?","o":["Con una prensa","Con la mano enguantada","Apoyada, sin sujetar, por su peso","Un compañero la sujeta con la mano"],"w":"Si la broca se traba, la pieza gira con fuerza."},{"q":"La broca se traba mientras perforas. ¿Qué haces?","o":["Suelto el gatillo de inmediato","Aprieto más el gatillo","Suelto el mango lateral","Tiro el taladro hacia atrás encendido"],"w":"Soltar el gatillo detiene el giro del taladro."},{"q":"¿Para qué sirve el mango lateral del taladro?","o":["Para controlarlo si la broca se traba","Para colgarlo en la pared","Solo para transportarlo","Para ajustar la broca"],"w":"Con las dos manos se controla el giro brusco del taladro."}]}]},{"id":"horquilla","sec":"planta","title":"Grúa horquilla: convivir con seguridad","thumb":"horq_contacto","mins":5,"learn":[{"s":"horq_ciego","t":"Una máquina pesada con puntos ciegos","x":"La grúa horquilla pesa varias toneladas, no frena como un auto y <b>la parte trasera se abre hacia los lados al girar</b>. Además, <b>el operador no ve todo</b>: la carga, el mástil y la parte trasera le tapan la vista. Un peatón en el punto ciego es invisible. Que tú veas la grúa no significa que el operador te vea a ti."},{"s":"horq_licencia","t":"Solo la opera quien está autorizado","x":"Para operarla se necesita <b>licencia de conducir clase D y autorización escrita de la empresa</b>; en {EMP} se exigen ambas. Sin capacitación no conoces sus riesgos ni sus límites. Nadie más se sube a manejarla: ni \"un ratito\", ni para moverla un metro. Si el operador no está, se espera o se avisa a la jefatura."},{"s":"horq_contacto","t":"Contacto visual antes de cruzar","x":"Antes de cruzar o acercarte: <b>detente, busca contacto visual</b> con el operador y espera su señal. <b>El peatón tiene prioridad</b>, pero nunca la des por segura. Respeta las zonas demarcadas, no camines por la ruta de la grúa y no cruces mirando el celular. Atento a la baliza y a la alarma de retroceso.","k":"Antes de cruzar, busca los ojos del operador y espera su señal."},{"s":"horq_bajo","t":"Nunca bajo una carga levantada","x":"Un pallet de paneles mal apilado puede deslizarse y caer en segundos. <b>Nadie pasa ni se queda bajo las horquillas levantadas</b>, aunque sea rápido o lleve casco. Mientras la grúa levanta, espera a distancia y fuera de su zona. Nadie viaja sobre las horquillas ni sobre la carga, y la grúa <b>nunca se usa para elevar personas</b>.","k":"Nunca pases ni te quedes bajo una carga levantada."},{"s":"horq_patio","t":"Carga de camiones en el patio","x":"Al cargar un camión, la grúa entra y sale muchas veces.<ul><li>Espera fuera de la zona de maniobra hasta que el operador te indique.</li><li>Nunca te pongas entre la grúa y el camión o un rack: puedes quedar atrapado contra algo fijo.</li><li>El camión debe estar detenido y frenado; si no, la carga se detiene.</li></ul>"},{"s":"horq_preuso","t":"Operador: revisión antes de partir","x":"Antes de usarla en el turno, el operador hace la revisión con su <b>check list</b>: <b>frenos, bocina, luces, neumáticos, horquillas, cadenas y fugas</b>. Si algo falla, aunque sea solo la bocina, <b>la grúa no se usa</b> y se avisa a la jefatura para su reparación. Nadie la repara de forma improvisada."},{"s":"horq_operar","t":"Operador: al conducir","x":"<ul><li>Cinturón de seguridad siempre.</li><li>Carga baja, cerca del piso, y mástil inclinado hacia atrás: con la carga alta la grúa pierde estabilidad y puede volcar.</li><li>Si la carga tapa la vista, avanza en reversa mirando hacia donde vas.</li><li>Bocina en cruces y puertas; velocidad baja.</li><li>Nunca superes la capacidad de su placa.</li></ul>"},{"s":"horq_estacionar","t":"Operador: al estacionar","x":"<ul><li>Horquillas apoyadas en el piso.</li><li>Freno de estacionamiento puesto.</li><li>Motor apagado y <b>llave retirada</b>, para que nadie sin autorización la use.</li><li>Lejos de salidas, extintores y pasillos.</li></ul>Nunca la dejes con la carga levantada ni con el motor encendido, ni siquiera por un momento: otra persona podría pasar bajo la carga o moverla sin autorización."},{"s":"horq_vuelco","t":"Si la grúa se vuelca","x":"El instinto dice \"salta\", pero saltar es lo más peligroso: la máquina te puede aplastar. <b>Quédate dentro con el cinturón puesto</b>, afírmate fuerte al volante, apoya los pies e inclínate hacia el lado contrario a la caída. El cinturón es lo que evita que salgas despedido bajo la máquina."},{"s":"horq_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una acción insegura. Con la grúa, las típicas son <b>cruzar apurado sin contacto visual</b> o mirando el celular, y <b>manejarla sin autorización</b>. La decisión segura: detenerte y esperar la señal. Avisa también las condiciones inseguras: pasillos bloqueados, piso dañado o grúa con fallas."}],"quiz":[{"s":"horq_licencia","v":[{"q":"¿Quién puede operar la grúa horquilla en {EMP}?","o":["Quien tiene licencia clase D y autorización escrita","Quien tiene licencia clase B y experiencia","Quien tiene licencia clase D, sin autorización","Quien autorizó de palabra el operador"],"w":"La empresa exige licencia clase D y autorización escrita para operarla."},{"q":"Un trabajador tiene licencia clase D, pero la empresa aún no lo autoriza por escrito. ¿Puede operar la grúa?","o":["No: se necesitan ambas cosas","Sí, la licencia basta","Sí, si va despacio","Sí, si solo la mueve en el patio"],"w":"Licencia y autorización escrita: las dos son obligatorias."},{"q":"¿Qué clase de licencia se exige para operar la grúa horquilla?","o":["Clase D","Clase B","Clase A2","Clase C"],"w":"La clase D corresponde a maquinaria como la grúa horquilla."}]},{"s":"under","v":[{"q":"La grúa tiene las horquillas levantadas con un pallet de paneles. ¿Puedes pasar por debajo si eres rápido?","o":["No: bajo una carga levantada no se pasa","Sí, si el operador me ve y me hace una seña","Sí, si llevo casco y paso agachado","Sí, si el pallet está bien amarrado"],"w":"Una carga puede caer en segundos, y el casco no protege de un pallet."},{"q":"¿Dónde debes esperar mientras la grúa levanta un pallet?","o":["A distancia, fuera de su zona y con contacto visual","Justo al lado, para ayudar a guiar","Bajo las horquillas, para revisar la carga","Detrás de la grúa, donde no estorbo"],"w":"Se espera a distancia y con contacto visual."},{"q":"¿Qué puede pasar con un pallet de paneles mal apilado en altura?","o":["Puede deslizarse y caer en segundos","Nada, las horquillas lo sostienen","Solo se daña el material","Solo cae si la grúa se mueve"],"w":"Por eso nadie pasa ni se queda bajo una carga levantada."}]},{"s":"horq_ciego","v":[{"q":"Si el operador va concentrado, puedo cruzar rápido por delante aunque no me haya visto.","vf":false,"w":"Falso. Siempre contacto visual y esperar la señal del operador."},{"q":"¿Por qué no basta con que tú veas la grúa para cruzar?","o":["El operador tiene puntos ciegos y puede no verte","Porque la grúa es silenciosa y no se escucha","Porque la grúa no tiene luces de aviso","Sí basta con que yo la vea a tiempo"],"w":"Que tú la veas no significa que él te vea."},{"q":"¿Qué parte de la grúa horquilla se abre hacia los lados al girar?","o":["La parte trasera","Las horquillas","El mástil","El techo de protección"],"w":"Por eso no hay que pararse al costado de la grúa cuando maniobra."}]},{"s":"horquilla_q_vision","v":[{"q":"La carga es alta y no deja ver hacia adelante. El operador debe:","o":["Avanzar en reversa, mirando hacia donde va","Avanzar igual, tocando la bocina","Levantar la carga para ver por debajo","Asomarse por el costado y avanzar"],"w":"Con la vista tapada se conduce en reversa, mirando el recorrido."},{"q":"¿Cómo debe ir la carga cuando la grúa circula?","o":["Baja, cerca del piso y con el mástil hacia atrás","Alta, para que el operador vea por debajo","A media altura, para ir más rápido","Alta y con el mástil hacia adelante"],"w":"Carga baja: más estabilidad y mejor visión."},{"q":"¿Por qué no se circula con la carga levantada?","o":["La grúa pierde estabilidad y puede volcar","Porque gasta más combustible","Porque las horquillas se doblan","Solo porque tapa la vista"],"w":"La carga alta sube el centro de gravedad de la grúa."}]},{"s":"ride","v":[{"q":"Está permitido subirse a las horquillas para alcanzar algo en altura.","vf":false,"w":"Falso. Nadie viaja ni se eleva sobre las horquillas."},{"q":"Necesitas alcanzar una caja en altura y un compañero te ofrece subirte a las horquillas. ¿Qué haces?","o":["No me subo: la grúa nunca eleva personas","Me subo si voy afirmado del mástil","Me subo sobre un pallet en las horquillas","Me subo si el operador va despacio"],"w":"Para trabajar en altura se usa el equipo adecuado, nunca la grúa."},{"q":"¿Puede alguien viajar sobre la carga o las horquillas en un traslado corto?","o":["No, nunca","Sí, si va sentado","Sí, si son menos de 10 metros","Sí, si lleva casco"],"w":"La grúa no está hecha para llevar personas."}]},{"s":"horq_preuso","v":[{"q":"En la revisión antes de partir, la bocina no funciona. ¿Qué corresponde?","o":["No usar la grúa y avisar a la jefatura","Usarla igual, con más cuidado","Usarla solo dentro del patio","Repararla con lo que encuentre"],"w":"Grúa con falla, grúa detenida. Se avisa para que la reparen."},{"q":"¿Qué revisa el operador en el check list antes de partir?","o":["Frenos, bocina, luces, neumáticos, horquillas y fugas","Solo el combustible y el nivel de aceite","Solo que el motor encienda y la bocina","Solo la limpieza de la cabina y los espejos"],"w":"Cada punto del check list puede evitar un accidente."},{"q":"¿Cuándo se hace la revisión con el check list?","o":["Antes de usar la grúa en el turno","Una vez al mes","Solo cuando falla","Al final de la semana"],"w":"La revisión es previa al uso, en cada turno."}]},{"s":"horq_patio","v":[{"q":"La grúa está cargando un camión en el patio. ¿Dónde debes estar?","o":["Fuera de la zona de maniobra, hasta que me indiquen","Entre la grúa y el camión, para guiar de cerca","Detrás de la grúa, pegado a ella","Sobre la carrocería del camión, ordenando"],"w":"Nunca entre la máquina y algo fijo. Se espera fuera de la zona de maniobra."},{"q":"El camión que se está cargando no tiene el freno puesto. ¿Qué corresponde?","o":["Detener la carga hasta que esté frenado","Cargar rápido antes de que se mueva","Poner un trozo de madera y seguir","Seguir, porque el chofer está cerca"],"w":"El camión debe estar detenido y frenado durante la carga."},{"q":"¿Por qué nunca debes ponerte entre la grúa y el camión o un rack?","o":["Puedes quedar atrapado contra algo fijo","Porque tapas la vista del chofer","Porque ensucias la carga","Porque la grúa no puede retroceder"],"w":"Entre una máquina y algo fijo no hay escape."}]},{"s":"horq_q_horq","v":[{"q":"Al estacionar la grúa, las horquillas deben quedar:","o":["Apoyadas en el piso","A media altura","Levantadas, para no tropezar","A unos 30 centímetros del piso"],"w":"Horquillas al piso, freno puesto, motor apagado y llave fuera."},{"q":"¿Qué se hace al dejar estacionada la grúa?","o":["Horquillas al piso, freno, motor apagado y llave fuera","Motor encendido para partir rápido","Llave puesta para el siguiente operador","Horquillas arriba para que nadie tropiece"],"w":"Retirar la llave evita que alguien sin autorización la use."},{"q":"La grúa debe estacionarse lejos de salidas, extintores y pasillos.","vf":true,"w":"Verdadero. Así no bloquea la evacuación ni el acceso a los extintores."}]},{"s":"horq_q_vuelco","v":[{"q":"Si la grúa comienza a volcarse, el operador debe:","o":["Quedarse dentro con cinturón y afirmarse","Saltar rápido hacia afuera de la cabina","Saltar hacia el lado contrario de la caída","Soltar el volante y agacharse en la cabina"],"w":"Saltar es lo más peligroso: la máquina puede aplastarte."},{"q":"¿Por qué el operador no debe saltar si la grúa se vuelca?","o":["Porque la máquina puede aplastarlo","Porque puede dañar la grúa","Porque pierde la licencia","Porque primero debe apagar el motor"],"w":"Dentro de la cabina, con cinturón, está más protegido."},{"q":"¿Qué elemento evita que el operador salga despedido en un vuelco?","o":["El cinturón de seguridad","La bocina","El techo de protección, por sí solo","Las luces"],"w":"Por eso el cinturón se usa siempre."}]},{"s":"horq_q_ratito","v":[{"q":"Un compañero te pide mover la grúa \"un ratito\" porque el operador no está. No tienes autorización. ¿Qué haces?","o":["No la opero y aviso a la jefatura","La muevo con cuidado, es solo un metro","La muevo sin cinturón, porque es corto","La muevo si él me guía"],"w":"Operar sin autorización es una acción insegura típica. Sin licencia y autorización escrita, no se opera."},{"q":"El operador dejó la grúa con la llave puesta y necesitas mover un pallet. No estás autorizado. ¿Qué haces?","o":["Espero al operador o aviso a la jefatura","La muevo yo, es solo un pallet","La muevo despacio y con cinturón","Le pido permiso a un compañero"],"w":"La llave puesta no es una autorización."},{"q":"¿Por qué operar la grúa \"solo un metro\" sin autorización es una acción insegura?","o":["Sin capacitación no conoces sus riesgos ni límites","No lo es si el recorrido es muy corto","Solo es un problema si te ve la jefatura","Porque puede gastar más combustible"],"w":"La autorización exige capacitación: por eso nadie más la opera."}]}]},{"id":"ruido","sec":"planta","title":"Ruido y protección auditiva","thumb":"ruido_limite","mins":5,"learn":[{"s":"ruido_cilios","t":"El ruido daña sin doler","x":"Dentro del oído hay <b>células ciliadas</b> muy finas que transforman el sonido en señales para el cerebro. El ruido fuerte, día tras día, las va destruyendo. No duele ni se nota: primero cuesta entender una conversación o escuchar la tele a volumen normal, y después ya no hay vuelta atrás. Esa pérdida se llama <b>hipoacusia</b>, es <b>permanente</b> y es una de las enfermedades profesionales más frecuentes en Chile."},{"s":"ruido_fuentes","t":"El ruido en la planta","x":"En {EMP} las fuentes más fuertes son la <b>sierra escuadradora, la rebajadora y el esmeril</b>; también suman la sierra circular manual, el compresor y las herramientas neumáticas. El ruido no se queda en la máquina: <b>si trabajas cerca, también estás expuesto</b>, aunque no la operes tú. El ayudante que recibe los paneles junto a la sierra oye el mismo ruido que el operador y necesita la misma protección."},{"s":"ruido_limite","t":"El límite legal y tu protector","x":"El DS 594 fija <b>85 dB(A) como límite para una jornada de 8 horas</b>. Si tu puesto lo supera, o la zona tiene el letrero azul de protector auditivo obligatorio, <b>lo usas todo el tiempo</b> que estés ahí. La empresa lo entrega <b>sin costo</b>, te enseña a usarlo y lo repone cuando se daña o se pierde. Es personal: no se presta. Revísalo antes de cada uso.","k":"En zona señalizada, el protector auditivo es obligatorio todo el tiempo."},{"s":"ruido_3db","t":"Más ruido, menos tiempo","x":"Los decibeles no suman como números normales: <b>cada 3 dB(A) más, la energía del ruido se duplica</b> y el tiempo permitido sin protección se reduce a la mitad.<ul><li>85 dB(A): 8 horas</li><li>88 dB(A): 4 horas</li><li>91 dB(A): 2 horas</li><li>94 dB(A): 1 hora</li></ul>Junto a una máquina de 94 dB(A), en una sola hora ya completaste la dosis de todo el día."},{"s":"ruido_prexor","t":"Nivel de acción: 82 dB(A)","x":"El protocolo <b>PREXOR</b> del MINSAL fija un <b>nivel de acción de 82 dB(A)</b>, bajo el límite legal. Si en tu puesto se alcanza ese nivel, se activan la <b>evaluación del ambiente</b> y la <b>vigilancia de tu salud</b>: la ACHS te hace audiometrías periódicas, sin costo para ti. <b>Asiste siempre</b>: el examen detecta el daño antes de que avance y permite corregir a tiempo tu protección."},{"s":"ruido_metro","t":"La prueba del metro","x":"Si para hablar con alguien <b>a un metro de distancia tienes que gritar</b>, el ruido probablemente supera lo seguro. Protégete y avisa a tu jefatura para que se evalúe el puesto; las mediciones las hace un especialista con instrumentos. Ojo con decir \"ya me acostumbré\": dejar de notar el ruido muchas veces significa que <b>ya perdiste algo de audición</b>."},{"s":"plugs","t":"Tapones: póntelos bien","x":"Con las manos limpias:<ul><li><b>1.</b> Enrolla el tapón con los dedos hasta dejarlo delgado.</li><li><b>2.</b> Con la otra mano tira la oreja <b>hacia arriba y atrás</b> para enderezar el canal.</li><li><b>3.</b> Insértalo y <b>sostenlo unos segundos</b> mientras se expande.</li></ul>Si queda asomado o se suelta, sácalo y repite. Tapón sucio, endurecido o que cayó al suelo: se cambia por uno nuevo."},{"s":"muffs","t":"Fonos (orejeras)","x":"Los fonos deben <b>cubrir la oreja completa</b> y sellar bien contra la cabeza. Pelo, gorros o patas de lentes gruesas bajo la almohadilla dejan pasar ruido. <b>Fonos en el cuello o subidos sobre el casco no protegen.</b> Antes de usarlos, revisa que las almohadillas no estén rotas ni endurecidas y que el arco apriete; si fallan, pide el recambio a tu jefatura."},{"s":"ruido_siempre","t":"Todo el tiempo, no a ratos","x":"Sacarte el protector incluso unos pocos minutos en una zona muy ruidosa te quita una gran parte de la protección de toda la jornada. <b>Póntelo antes de entrar y sácatelo al salir</b>, aunque solo vayas de paso o la máquina esté en pausa. Para conversar, sal de la zona. Para recibir una instrucción, pide a tu supervisor que se alejen de la máquina.","k":"Protección a ratos es protección a medias."},{"s":"ruido_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una acción insegura, y con el ruido pasa lo mismo. La típica es <b>sacarse el protector para conversar</b> o \"porque es un corte corto\". La decisión segura: dejarlo puesto y alejarte para hablar. Avisa a tu jefatura si tus fonos están dañados, si faltan tapones o si sales del turno con <b>zumbido u oídos tapados</b>: es una alerta de que el ruido te está llegando."}],"quiz":[{"s":"ruido_limite","v":[{"q":"Según el DS 594, ¿cuál es el límite de ruido para una jornada de 8 horas?","o":["85 dB(A)","82 dB(A)","90 dB(A)","80 dB(A)"],"w":"El DS 594 fija 85 dB(A) para 8 horas; 82 dB(A) es el nivel de acción del PREXOR, no el límite."},{"q":"Un puesto mide 87 dB(A) durante toda la jornada de 8 horas. ¿Qué significa?","o":["Supera el límite legal: protector obligatorio todo el tiempo","Está bajo el límite: el protector es voluntario","Está en el nivel de acción: solo hay que medir de nuevo","Es normal en una planta industrial y no exige ninguna medida adicional"],"w":"Sobre 85 dB(A) en 8 horas se supera el límite legal y el protector se usa siempre."},{"q":"Para una jornada de 8 horas, ¿qué nivel separa lo permitido de lo que sobrepasa la ley?","o":["85 dB(A)","82 dB(A)","88 dB(A)","100 dB(A)"],"w":"El límite legal del DS 594 para 8 horas es 85 dB(A)."}]},{"s":"ruido_cilios","v":[{"q":"¿Por qué la pérdida de audición por ruido es tan grave?","o":["Porque es permanente: esas células no se regeneran","Porque duele mucho y obliga a dejar de trabajar","Porque solo se cura con una operación costosa","Porque aparece de golpe, en un solo día de mucho ruido, sin aviso"],"w":"El ruido destruye de a poco las células del oído y ese daño no se recupera."},{"q":"Un compañero dice: \"Llevo años en la sierra sin fonos y nunca me ha dolido el oído\". ¿Qué es lo correcto?","o":["El ruido daña sin doler y el daño es permanente","Si no le duele, su oído ya se adaptó al ruido","Tiene razón: el daño solo ocurre cuando hay dolor","Le basta descansar el fin de semana para recuperarse"],"w":"La hipoacusia avanza sin dolor; cuando se nota, ya no tiene vuelta."},{"q":"Si dejas de exponerte al ruido, la audición perdida se recupera con los meses.","vf":false,"w":"Falso. La hipoacusia por ruido es permanente; por eso se previene."}]},{"s":"ruido_metro","v":[{"q":"¿Cuál es una señal práctica de que el ruido de tu puesto es alto?","o":["Tener que gritar para hablar con alguien a un metro","No escuchar la radio desde la sala del lado","Que la máquina vibre al encenderla","Que el ruido moleste al empezar el turno y luego ya no se note"],"w":"Es la prueba del metro: si debes gritar a un metro, protégete y avisa."},{"q":"Junto a la rebajadora tienes que gritar para que tu compañero, a un metro, te entienda. ¿Qué haces?","o":["Me protejo y aviso a la jefatura para que evalúen el puesto","Sigo igual porque ya me acostumbré a ese ruido","Hablo más fuerte y me pongo el protector solo al final de la tarea","Le pido que se acerque más y seguimos"],"w":"Gritar a un metro indica ruido alto: protección y evaluación del puesto."},{"q":"Llevas meses en la planta y sientes que ya te acostumbraste al ruido. ¿Qué puede significar?","o":["Que podrías estar perdiendo audición sin notarlo","Que tu oído se adaptó al ruido y por eso ya no le hace daño","Que la máquina se gastó y hace menos ruido","Que ya no necesitas usar el protector"],"w":"Dejar de notar el ruido puede ser señal de que ya hay daño auditivo."}]},{"s":"muffsBad","v":[{"q":"Un compañero trabaja en una zona ruidosa con los fonos colgando en el cuello. ¿Está protegido?","o":["No: los fonos protegen solo si cubren y sellan las orejas","Sí: basta con tenerlos puestos en el cuerpo","Sí, si la máquina está a más de un metro","En parte: cerca de la cabeza igual bloquean una parte importante del sonido"],"w":"Fonos en el cuello no protegen: deben cubrir la oreja completa y sellar."},{"q":"¿Qué hace que unos fonos dejen de proteger aunque los lleves encima?","o":["Usarlos en el cuello o con pelo o gorro bajo la almohadilla","Usarlos junto con el casco de seguridad","Que sean de otro color que los del resto","Usarlos durante toda la jornada sin sacarlos ni una sola vez"],"w":"Si no cubren la oreja y no sellan, el ruido pasa."},{"q":"Ves a un compañero en zona ruidosa con los fonos bajados \"para escuchar mejor\". ¿Qué es lo correcto?","o":["Que se los suba: así no lo protegen","Nada: en el cuello igual atenúan un poco","Que se ponga tapones y deje los fonos ahí","Que se los suba solo al encender la sierra"],"w":"Los fonos se usan sobre las orejas todo el tiempo en la zona."}]},{"s":"plugs","v":[{"q":"Al ponerte un tapón de espuma, ¿qué haces con la oreja?","o":["La tiro hacia arriba y atrás con la otra mano","La tiro hacia abajo y adelante","La aprieto contra la cabeza para cerrarla","No la toco: solo empujo el tapón con fuerza hasta que no se vea"],"w":"Tirar la oreja hacia arriba y atrás endereza el canal y el tapón sella."},{"q":"¿Cuál es el orden correcto para ponerse un tapón de espuma?","o":["Enrollarlo, tirar la oreja hacia arriba y atrás, insertarlo y sostenerlo","Insertarlo sin enrollar, tirar la oreja y soltarlo de inmediato","Mojarlo, tirar la oreja hacia abajo e insertarlo hasta el fondo","Tirar la oreja hacia atrás, insertarlo tal como viene y apretarlo ya puesto"],"w":"Enrollar, abrir el canal, insertar y sostener mientras se expande."},{"q":"Después de insertar el tapón enrollado, conviene sostenerlo unos segundos mientras se expande.","vf":true,"w":"Verdadero. Si lo sueltas antes, puede salirse y no sellar."}]},{"s":"ruido_siempre","v":[{"q":"¿Cuándo debes usar el protector en una zona señalizada como ruidosa?","o":["Todo el tiempo que estés en la zona","Solo mientras la máquina esté cortando","Solo si trabajas más de 8 horas ahí","Solo cuando tú operas la máquina"],"w":"En zona señalizada el protector es obligatorio todo el tiempo."},{"q":"Vas de paso por la zona de sierras a dejar un recado de dos minutos. ¿Qué haces?","o":["Me pongo el protector antes de entrar","Paso rápido: dos minutos no hacen daño","Me tapo los oídos con las manos","Entro sin protector si la sierra está en pausa"],"w":"El protector se pone antes de entrar, aunque vayas de paso."},{"q":"Te sacas el protector unos minutos cada hora para descansar dentro de la zona ruidosa. ¿Qué pasa?","o":["Pierdes gran parte de la protección de la jornada","Nada, si son menos de cinco minutos","Tu oído descansa y luego rinde mejor","Solo importa si el ruido de la zona supera los 100 dB(A)"],"w":"Unos minutos sin protector en ruido alto reducen mucho la protección total."}]},{"s":"ruido_3db","v":[{"q":"Si el ruido sube de 85 a 88 dB(A), el tiempo de exposición permitido...","o":["Se reduce a la mitad: de 8 a 4 horas","Baja un poco: de 8 a 7 horas","Se mantiene: son solo 3 dB(A)","Se duplica: pasa de 8 a 16 horas permitidas"],"w":"Cada 3 dB(A) más, la energía se duplica y el tiempo se reduce a la mitad."},{"q":"Una máquina genera 91 dB(A). Según el criterio de 3 dB(A), ¿cuánto tiempo se permite sin protección?","o":["2 horas","4 horas","6 horas","8 horas"],"w":"85: 8 h; 88: 4 h; 91: 2 h."},{"q":"Pasar de 85 a 88 dB(A) duplica la energía del ruido que llega a tu oído.","vf":true,"w":"Verdadero. Por eso el tiempo permitido baja a la mitad."}]},{"s":"ruido_q_82","v":[{"q":"Según el PREXOR, ¿qué se activa cuando un puesto alcanza el nivel de acción de 82 dB(A)?","o":["La evaluación del ambiente y la vigilancia de la salud","El permiso para trabajar sin protector","La paralización inmediata de la máquina","Solo la instalación de un letrero de advertencia en la zona"],"w":"El nivel de acción activa evaluación y vigilancia de salud con audiometrías."},{"q":"Tu puesto mide 83 dB(A), bajo el límite legal de 85. ¿Qué corresponde?","o":["Entrar a vigilancia de salud con audiometrías de la ACHS","Nada: mientras no pase de 85 no hay riesgo","Usar el protector solo la última hora","Trasladar la máquina a otro galpón de inmediato, sin más medidas"],"w":"Sobre 82 dB(A) ya se activa la vigilancia, aunque no se pase el límite."},{"q":"¿Para qué sirven las audiometrías periódicas que la ACHS hace a los expuestos a ruido?","o":["Para detectar el daño auditivo antes de que avance","Para decidir quién recibe un bono por ruido","Para medir cuánto ruido hace cada máquina","Para que puedas dejar de usar el protector si sale todo bien"],"w":"La audiometría detecta el daño a tiempo; no reemplaza el protector."}]},{"s":"ruido_zumbido","v":[{"q":"Al terminar el turno sientes un zumbido en los oídos. ¿Qué significa?","o":["Es una alerta de exposición: reviso mi protección y aviso","Es normal en la planta y se pasa durmiendo","Es señal de que el protector funcionó bien","Es solo cansancio general del turno y no tiene que ver con el ruido"],"w":"El zumbido indica que el ruido te está llegando: avisa y corrige."},{"q":"Varios días seguidos sales del turno con los oídos tapados y un pitido. ¿Qué haces?","o":["Aviso a mi jefatura y reviso cómo uso el protector","Espero unas semanas a ver si se pasa","Me limpio los oídos con cotonitos","Me pongo tapones en la casa para que el oído descanse del ruido"],"w":"Son síntomas de exposición: se avisan y se revisa la protección."},{"q":"Si el zumbido desaparece al día siguiente, el ruido no causó ningún daño.","vf":false,"w":"Falso. El zumbido que se pasa también es una alerta; el daño se acumula."}]},{"s":"ruido_q_charla","v":[{"q":"Necesitas hablar con un compañero junto a la sierra encendida. ¿Cuál es la decisión segura?","o":["Alejarnos de la zona ruidosa para conversar","Sacarme un fono un momento para escucharlo","Gritarle con los fonos sobre el casco","Bajarme los fonos al cuello mientras hablamos"],"w":"Para conversar se sale de la zona, sin sacarse el protector dentro."},{"q":"El supervisor quiere darte una instrucción al lado de la escuadradora en marcha. ¿Qué haces?","o":["Le pido que salgamos de la zona para hablar","Me saco los fonos solo durante la instrucción","Le pido que me la repita más fuerte","Me saco un tapón y lo vuelvo a poner después"],"w":"La conversación se hace lejos del ruido, con el protector puesto en la zona."},{"q":"¿Cuál es la acción insegura más típica con el protector auditivo?","o":["Sacárselo para conversar dentro de la zona","Ponérselo antes de entrar a la zona","Pedir recambio cuando está dañado","Guardarlo limpio en su bolsa al terminar el turno"],"w":"Sacarse el protector para hablar es el error más común."}]}]},{"id":"polvo","sec":"planta","title":"Polvo de madera y protección respiratoria","thumb":"polvo_que","learn":[{"s":"polvo_que","t":"El polvo que no se ve","x":"Cortar, rebajar y lijar OSB y madera genera <b>polvo muy fino</b>. Lo que ves flotando es solo una parte: las partículas más pequeñas no se ven, quedan mucho rato en el aire y llegan <b>hasta el fondo de los pulmones</b>. A corto plazo irrita ojos, nariz y garganta y provoca tos; con los años puede causar alergias, asma y otras enfermedades respiratorias."},{"s":"polvo_cancer","t":"Es cancerígeno","x":"La IARC (agencia de la OMS) clasifica el <b>polvo de madera, de todo tipo, como cancerígeno Grupo 1</b>: comprobado en personas. Se asocia sobre todo al <b>cáncer de nariz y senos paranasales</b>, que aparece después de años de exposición, cuando ya no se puede volver atrás. El <b>OSB también es madera</b>: su polvo cuenta igual, y además lleva resinas que pueden irritar.","k":"Polvo de madera: cancerígeno comprobado, también el del OSB."},{"s":"polvo_ext","t":"Primero, control en la fuente","x":"Lo más efectivo es <b>captar el polvo donde se genera</b>, antes de que llegue a tu nariz. <b>Si la máquina tiene extracción, debe estar encendida y conectada antes de cortar.</b> Revisa que la manga no esté rota ni suelta y que realmente aspire. Si falla, no sigas cortando: avisa a tu jefatura. El respirador es la última barrera, no reemplaza a la extracción."},{"s":"polvo_limpia","t":"Limpiar sin levantar polvo","x":"El polvo se limpia <b>aspirando o humedeciendo</b>, <b>nunca soplando</b> con aire comprimido: soplarlo lo deja flotando para ti y tus compañeros, y el aire a presión puede lesionar ojos y piel. Barrer en seco también lo levanta. Además, el polvo de madera acumulado sobre motores, vigas y tableros <b>es combustible</b> y puede arder. Usa tu respirador mientras limpias.","k":"Aspirar o humedecer; soplar nunca."},{"s":"polvo_resp","t":"El respirador correcto","x":"Usa un <b>respirador con filtro para partículas certificado</b>, por ejemplo P2 o N95, el que la empresa defina para tu puesto. Una <b>mascarilla quirúrgica o de tela no filtra el polvo fino</b>: no es protección respiratoria. La empresa lo entrega <b>sin costo</b> (DS 594, art. 53). Si se acaban, no cortes sin protección: pide más a tu jefatura."},{"s":"polvo_sello","t":"Bien ajustado, sin fugas","x":"<ul><li>Ajusta <b>ambos elásticos</b>, uno en la nuca y otro sobre las orejas.</li><li>Moldea la pieza de la nariz con los dedos de ambas manos.</li><li><b>Revisa el sello cada vez</b>: cubre el respirador con las manos y respira; no debe entrar ni salir aire por los bordes.</li><li>La <b>barba</b> en el borde deja pasar el polvo.</li><li>Póntelo <b>antes</b> de entrar a la zona con polvo.</li></ul>"},{"s":"polvo_cambio","t":"Cuándo cambiarlo","x":"Cambia el respirador desechable cuando esté <b>sucio, húmedo o dañado</b>, cuando se suelte un elástico o cuando <b>cueste respirar</b> a través de él: eso indica que el filtro está saturado. No lo sacudas para seguir usándolo. Guárdalo limpio en una bolsa o caja, no colgando del cuello lleno de polvo. Es personal: no se presta."},{"s":"polvo_higiene","t":"No te lleves el polvo","x":"<ul><li>Lávate <b>manos y cara</b> antes de comer, beber o fumar fuera del área, y al terminar el turno.</li><li>No comas ni bebas en la zona de corte: hazlo en el lugar habilitado.</li><li>Aspira o sacude la ropa lejos de donde se come, nunca con aire comprimido.</li><li>Evita llevar la ropa de trabajo con polvo a tu casa: expones a tu familia.</li></ul>"},{"s":"polvo_sintomas","t":"Escucha a tu cuerpo","x":"Avisa a tu jefatura y consulta si tienes <b>nariz tapada de un lado</b> por semanas, <b>sangrado nasal frecuente</b>, tos persistente, ahogo, silbido al respirar u ojos irritados. Si tu puesto tiene vigilancia de salud, <b>asiste a tus exámenes</b> aunque te sientas bien. Una enfermedad profesional la cubre la Ley 16.744 en la ACHS; su fono es el 1404."},{"s":"polvo_self","t":"Autocuidado: polvo","x":"La mayoría de los accidentes y enfermedades se relacionan con una <b>acción insegura</b>: apurarse, saltarse un paso, no usar el EPP. Con el polvo, la típica es <b>\"es un corte no más\"</b> sin respirador, o limpiar soplando. El daño se acumula corte a corte. Decide seguro: extracción encendida si existe, respirador puesto aunque la extracción funcione, y <b>avisa</b> si algo falla."}],"quiz":[{"s":"polvo_cancer","v":[{"q":"Según la IARC, ¿cómo se clasifica el polvo de madera?","o":["Cancerígeno Grupo 1, comprobado en personas","Posible cancerígeno, aún en estudio","Irritante, pero no cancerígeno","Cancerígeno, pero solo el de maderas duras como el roble"],"w":"Todo polvo de madera es Grupo 1: cancerígeno comprobado."},{"q":"¿Qué cáncer se asocia principalmente al polvo de madera?","o":["De nariz y senos paranasales","De piel en manos y brazos","De estómago, por tragar polvo durante la jornada","De hígado por las resinas"],"w":"El polvo de madera se asocia sobre todo al cáncer nasal y de senos paranasales."},{"q":"¿Por qué el polvo de madera exige protección aunque no notes ningún daño?","o":["Porque es cancerígeno y el daño aparece después de años","Porque el daño se elimina solo con los años","Porque solo afecta a las personas que fuman","Porque con los años causa sordera y pérdida de equilibrio"],"w":"El cáncer por polvo de madera aparece después de años: se previene hoy."}]},{"s":"polvo_cancer","v":[{"q":"¿El polvo de OSB tiene el mismo riesgo que el polvo de madera?","o":["Sí: el OSB es madera y su polvo cuenta igual","No: al ser madera procesada, el riesgo desaparece","Solo si el OSB está húmedo","Solo si se corta con sierra circular"],"w":"El OSB es madera: su polvo es polvo de madera, cancerígeno."},{"q":"En tu puesto cortas solo OSB, nunca madera maciza. ¿Necesitas protegerte del polvo?","o":["Sí: el polvo de OSB es polvo de madera cancerígeno","No: el riesgo es solo de la madera maciza","Solo si el corte dura más de una hora","No, porque las resinas del OSB atrapan el polvo y lo vuelven inofensivo"],"w":"El tipo de madera no cambia la clasificación: todo polvo de madera es Grupo 1."},{"q":"El polvo de OSB no es peligroso porque es madera procesada.","vf":false,"w":"Falso. El OSB es madera: su polvo es cancerígeno."}]},{"s":"polvo_mascMal","v":[{"q":"Un operador corta OSB usando una mascarilla quirúrgica. ¿Está protegido del polvo fino?","o":["No: necesita un respirador certificado como P2 o N95","Sí: cualquier mascarilla que tape nariz y boca sirve","Sí, si la cambia cada dos horas","Sí, siempre que la cambie cada dos horas y use además lentes"],"w":"La mascarilla quirúrgica no filtra el polvo fino."},{"q":"¿Qué protección respiratoria corresponde para cortar madera y OSB?","o":["Respirador con filtro para partículas certificado","Mascarilla quirúrgica bien ajustada","Mascarilla de tela lavable de dos capas","Pañuelo húmedo bien amarrado sobre nariz y boca durante el corte"],"w":"Se usa un respirador certificado para partículas, como P2 o N95."},{"q":"Se acabaron los respiradores P2 y un compañero te ofrece una mascarilla quirúrgica para cortar. ¿Qué haces?","o":["No corto sin protección adecuada y pido respiradores","Uso la mascarilla quirúrgica solo por hoy","Uso dos mascarillas quirúrgicas juntas","Corto rápido, con la mascarilla quirúrgica, y respiro lo menos posible"],"w":"Si no hay respirador adecuado, no se corta: se pide a la jefatura."}]},{"s":"polvo_ext","v":[{"q":"La sierra tiene extracción, pero está desconectada. ¿Qué haces?","o":["La conecto y la enciendo; si falla, aviso","Corto igual porque llevo respirador","Abro el portón para ventilar y corto","Corto igual y al terminar aspiro todo el polvo que quedó en la zona"],"w":"Si la máquina tiene extracción, debe estar encendida y conectada antes de cortar."},{"q":"¿Cuál es la medida más efectiva contra el polvo de madera?","o":["Captarlo en la fuente con la extracción encendida","Usar el respirador como única medida","Ventilar el galpón abriendo todas las puertas y ventanas","Barrer al terminar cada corte"],"w":"El control en la fuente evita que el polvo llegue a tu nariz; el respirador es la última barrera."},{"q":"Al encender la extracción notas que no aspira porque la manga está rota. ¿Qué corresponde?","o":["Avisar a la jefatura antes de seguir cortando","Seguir cortando y avisar al final del turno","Tapar la rotura con cinta y seguir","Cortar con respirador puesto y dejar la extracción para el otro turno"],"w":"Una extracción que no aspira no protege: se avisa antes de seguir."}]},{"s":"polvo_limpia","v":[{"q":"¿Cómo se limpia el polvo de madera de la mesa y el piso?","o":["Aspirando o humedeciendo","Soplando con aire comprimido","Barriendo en seco con escoba","Sacudiendo con un paño seco"],"w":"Aspirar o humedecer evita que el polvo vuelva al aire."},{"q":"Un compañero limpia su ropa y la máquina con la pistola de aire comprimido. ¿Por qué está mal?","o":["Deja el polvo flotando y el aire a presión puede lesionar","Porque gasta demasiado aire del compresor","Porque daña la pintura de la máquina","Solo está mal si no usa lentes de seguridad mientras sopla"],"w":"Soplar levanta el polvo para todos y el aire a presión lesiona ojos y piel."},{"q":"Aspirar el polvo es más seguro que barrerlo en seco.","vf":true,"w":"Verdadero. Barrer en seco lo levanta; aspirar lo retira."}]},{"s":"polvo_sello","v":[{"q":"¿Qué debes hacer cada vez que te pones el respirador?","o":["Ajustar ambos elásticos, moldear la nariz y revisar el sello","Ajustar solo un elástico, porque el otro molesta","Ponerlo sobre la barba para que quede firme","Revisar el sello una vez a la semana, cuando el respirador es nuevo"],"w":"El sello se revisa cada vez; sin sello, entra polvo."},{"q":"Con el respirador puesto, sientes que entra aire por un costado al respirar. ¿Qué significa?","o":["Que no sella: entra polvo y debo reajustarlo","Que respira bien y está funcionando","Que es nuevo y todavía no se adapta","Que es normal en los respiradores desechables y no hay que hacer nada"],"w":"Si entra aire por el borde, entra polvo."},{"q":"Con barba, el respirador sella igual de bien.","vf":false,"w":"Falso. La barba en el borde deja pasar aire y polvo."}]},{"s":"polvo_cambio","v":[{"q":"¿Cuándo cambias el respirador desechable?","o":["Cuando está sucio, húmedo, dañado o cuesta respirar","Una vez a la semana, aunque esté roto","Solo cuando se pierde o se rompe del todo","Al cambiar de tarea, aunque esté nuevo, limpio y sin daños"],"w":"Un respirador tapado o dañado deja de proteger."},{"q":"A mitad del turno te cuesta respirar a través del respirador y está lleno de polvo. ¿Qué haces?","o":["Pido uno nuevo: el filtro está saturado","Lo sacudo y lo sigo usando","Me lo bajo cuando cuesta respirar","Lo sacudo bien contra la mesa para soltar el polvo y sigo"],"w":"Cuando cuesta respirar, el filtro está saturado y se cambia."},{"q":"¿Cómo guardas el respirador durante la colación?","o":["Limpio, en una bolsa o caja, sin prestarlo","Colgando del cuello para no perderlo","Sobre la mesa de corte, listo para usar","En el bolsillo del pantalón, junto con los guantes de trabajo"],"w":"Guardado limpio sigue protegiendo; es personal."}]},{"s":"polvo_higiene","v":[{"q":"Terminaste de cortar y vas a comer. ¿Qué haces primero?","o":["Me lavo manos y cara","Me sacudo la ropa donde voy a comer","Me limpio con aire comprimido","Me saco solo los guantes"],"w":"Así no tragas polvo ni lo llevas a donde se come."},{"q":"¿Dónde puedes comer o beber agua durante el turno?","o":["En el lugar habilitado, fuera de la zona de corte","En mi puesto, con la sierra detenida","En la zona de corte, si uso respirador","Donde quiera dentro de la planta, si me lavo las manos después"],"w":"En la zona de corte no se come ni se bebe."},{"q":"Llevar la ropa de trabajo con polvo a tu casa puede exponer a tu familia.","vf":true,"w":"Verdadero. El polvo viaja en la ropa; por eso se limpia o se deja en el trabajo si es posible."}]},{"s":"polvo_sintomas","v":[{"q":"Hace semanas tienes la nariz tapada de un lado y sangras seguido. ¿Qué haces?","o":["Aviso a mi jefatura y consulto en la ACHS","Lo trato como un resfrío y sigo igual","Uso descongestionante sin consultar","Espero hasta mis vacaciones para consultar con calma en un médico"],"w":"Son síntomas que deben revisarse a tiempo."},{"q":"Trabajas con polvo de madera. ¿Cuál de estos síntomas debes avisar si se repite?","o":["Sangrado nasal frecuente","Estornudos un solo día de primavera","Ojos rojos tras una noche sin dormir","Una tos por un resfrío ya pasado"],"w":"El sangrado nasal frecuente es una señal de alerta del polvo de madera."},{"q":"Te citan a exámenes de vigilancia de salud por polvo, pero te sientes bien. ¿Qué haces?","o":["Asisto: detectan daños antes de que avancen","No voy, porque no tengo síntomas","Lo dejo para cuando haya menos trabajo","Voy solo si la jefatura me obliga a ir por escrito"],"w":"La vigilancia detecta el daño antes de los síntomas."}]},{"s":"polvo_self","v":[{"q":"Vas a hacer un solo corte rápido en la sierra. ¿Usas el respirador?","o":["Sí: el daño se acumula corte a corte","No: un corte corto no alcanza a dañar","Solo si veo mucho polvo en el aire","Solo si la extracción está apagada"],"w":"El polvo más fino no se ve y el daño se suma con los años."},{"q":"¿Cuál es la acción insegura típica con el polvo de madera?","o":["Decir \"es un corte no más\" y cortar sin respirador","Pedir un respirador nuevo si está sucio","Encender la extracción antes de cortar","Lavarse manos y cara antes de comer y al salir"],"w":"Cortar sin protección \"por un rato\" es el error más común."},{"q":"La extracción funciona bien. ¿Igual usas el respirador en tu puesto?","o":["Sí, si mi puesto lo exige: la extracción no capta todo","No: con extracción el respirador sobra","Solo en la última hora del turno","Solo si corto madera maciza, porque el OSB genera menos polvo"],"w":"La extracción reduce el polvo, pero no lo elimina por completo."}]}]},{"id":"quimicos","sec":"planta","title":"Adhesivos y sustancias químicas","thumb":"pictos","mins":5,"learn":[{"s":"quimicos_intro","t":"Químicos en la planta","x":"En el encolado de los paneles se usa <b>adhesivo</b>, y en la planta también hay <b>solventes</b> de limpieza, aceites y combustibles. Te pueden dañar por cuatro vías:<ul><li><b>Piel:</b> irritación, quemaduras y alergias.</li><li><b>Ojos:</b> lesiones por salpicaduras.</li><li><b>Respiración:</b> vapores que irritan o sensibilizan.</li><li><b>Boca:</b> al comer o fumar con las manos sucias.</li></ul>"},{"s":"quimicos_hds","t":"La Hoja de Datos de Seguridad (HDS)","x":"Cada producto químico tiene su <b>HDS</b> (NCh 2245), entregada por el proveedor en español. Ahí está todo:<ul><li>sus peligros;</li><li>el EPP que debes usar;</li><li>primeros auxilios;</li><li>qué hacer ante un derrame o un incendio;</li><li>cómo almacenarlo y qué productos son incompatibles.</li></ul>Debe estar disponible donde se usa el producto. Pregunta a tu jefatura dónde están las HDS de lo que usas."},{"s":"quimicos_pictos","t":"Pictogramas: rombos que avisan","x":"Según el SGA, exigido en Chile por el <b>DS 57</b>, los pictogramas son <b>rombos con borde rojo, fondo blanco y símbolo negro</b>:<ul><li><b>Llama:</b> inflamable.</li><li><b>Exclamación:</b> irritante o nocivo.</li><li><b>Silueta con estrella en el pecho:</b> daño grave a la salud, como alergia respiratoria o cáncer.</li><li><b>Corrosión:</b> daña piel, ojos y metales.</li></ul>Un mismo envase puede llevar varios rombos."},{"s":"quimicos_label","t":"La etiqueta del envase","x":"Además de los pictogramas, la etiqueta trae:<ul><li>nombre del producto y del proveedor;</li><li>palabra de advertencia: <b>\"Peligro\"</b> para lo más grave o <b>\"Atención\"</b> para lo menos grave;</li><li>indicaciones de peligro: qué daño puede causar;</li><li>consejos de prudencia: cómo usarlo, qué EPP usar y qué hacer si hay contacto.</li></ul>Léela antes de usar el producto, aunque creas conocerlo."},{"s":"quimicos_ppe","t":"Tu protección con adhesivos","x":"<ul><li><b>Guantes de nitrilo</b> u otro material que indique la HDS: un guante de tela absorbe el adhesivo y lo mantiene contra la piel.</li><li><b>Lentes de seguridad</b> contra salpicaduras.</li><li>Ropa de manga larga.</li><li><b>Protección respiratoria si la HDS lo indica.</b> Los adhesivos de poliuretano con isocianatos pueden sensibilizar y causar asma, aunque no huelan fuerte.</li></ul>"},{"s":"quimicos_hyg","t":"Ventilación e higiene","x":"<ul><li>Trabaja con <b>buena ventilación</b> y mantén los envases <b>tapados</b> para que no liberen vapores.</li><li><b>No comas, bebas ni fumes</b> donde se usan químicos.</li><li>Sácate los guantes y lávate manos y cara antes de comer y al terminar el turno.</li><li><b>Nunca limpies tu piel con solvente o diluyente</b>: la piel lo absorbe. Usa agua y jabón o el limpiador que indique la HDS.</li></ul>"},{"s":"quimicos_bottles","t":"Envases siempre rotulados","x":"Nunca guardes un químico en <b>botellas de bebida</b> ni en envases sin rótulo: alguien puede confundirlo y tomarlo. Si trasvasijas, el nuevo envase debe quedar <b>etiquetado con el nombre del producto y sus peligros</b>, aunque sea para usarlo el mismo turno. Si encuentras un envase sin etiqueta, <b>no lo uses</b> ni adivines qué es: avisa a tu jefatura.","k":"Nunca pongas un químico en una botella de bebida."},{"s":"quimicos_store","t":"Almacenamiento seguro","x":"El DS 43 regula cómo se almacenan las sustancias peligrosas. En tu puesto:<ul><li>Envases <b>cerrados y rotulados</b>, en el lugar destinado, con bandeja antiderrame si corresponde.</li><li>Lejos de calor, chispas y llamas.</li><li>Nunca en pasillos ni frente a salidas o extintores.</li><li>Separados de los productos que la HDS indique como <b>incompatibles</b>.</li></ul>Al terminar, cada envase vuelve cerrado a su lugar."},{"s":"quimicos_eyes","t":"Si hay contacto o derrame","x":"<ul><li><b>Ojos:</b> lava con abundante agua limpia <b>al menos 15 minutos</b>, con los párpados abiertos. Usa el lavaojos si existe.</li><li><b>Piel:</b> retira la ropa contaminada y lava con agua y jabón.</li><li><b>Vapores:</b> sal al aire fresco.</li><li><b>Derrame:</b> aleja a las personas, avisa y limpia según la HDS.</li></ul>Siempre avisa a tu jefatura y lleva la HDS a la atención en la ACHS (fono 1404).","k":"Químico en los ojos: agua abundante 15 minutos y avisa."},{"s":"quimicos_self","t":"Autocuidado con químicos","x":"La mayoría de los accidentes se relacionan con una <b>acción insegura</b>: apurarse, saltarse un paso, no usar el EPP. Con químicos, la típica es pensar <b>\"es solo pegamento\"</b> y trabajar sin guantes ni lentes, o frotarse los ojos con las manos sucias. Decide seguro: lee la etiqueta, usa tu EPP y <b>avisa</b> fugas, derrames o envases sin rótulo."}],"quiz":[{"s":"quimicos_hds","v":[{"q":"¿Dónde encuentras los peligros, el EPP y los primeros auxilios de un adhesivo?","o":["En la Hoja de Datos de Seguridad (HDS)","En la boleta o factura de compra","En el catálogo de ventas del proveedor","En lo que recuerden los compañeros que lo han usado por años"],"w":"La HDS es la fuente oficial de información del producto."},{"q":"Llega a la planta un adhesivo que nunca has usado. ¿Qué haces antes de usarlo?","o":["Leo su HDS y uso el EPP que indica","Lo uso igual que el adhesivo anterior","Lo huelo para saber si es fuerte","Pruebo un poco sin guantes para ver si irrita"],"w":"Antes de usar un producto nuevo se lee su HDS."},{"q":"¿Qué información NO encontrarás en una HDS?","o":["El precio y dónde comprarlo más barato","Los primeros auxilios ante un contacto","El EPP que se debe usar","Qué hacer ante un derrame o un incendio del producto"],"w":"La HDS trae peligros, EPP, primeros auxilios, derrames y almacenamiento; no precios."}]},{"s":"quimicos_botBad","v":[{"q":"Encuentras un líquido transparente en una botella de bebida sobre la mesa de trabajo. ¿Qué haces?","o":["No lo uso ni lo bebo, y aviso a la jefatura","Lo huelo para saber qué es","Lo boto al desagüe para evitar problemas","Lo uso para limpiar si huele a solvente de limpieza"],"w":"Un químico en botella de bebida es un peligro desconocido: se avisa."},{"q":"¿Por qué está prohibido guardar químicos en botellas de bebida?","o":["Porque alguien puede confundirlo y tomarlo","Porque el plástico cambia el color del producto","Porque el químico pierde efectividad","Solo porque se ve desordenado"],"w":"El riesgo principal es la ingestión por confusión."},{"q":"Ves una botella de bebida con un líquido en la mesa del área de encolado. ¿Cuál es el riesgo principal?","o":["Que alguien lo confunda con bebida y lo tome","Que se evapore y se pierda el producto","Que manche la mesa de trabajo","Que la botella se caiga, se quiebre y alguien se corte"],"w":"Los químicos nunca van en envases de alimentos o bebidas."}]},{"s":"quimicos_hyg","v":[{"q":"Terminas de encolar y es hora de colación. ¿Qué haces primero?","o":["Me saco los guantes y me lavo manos y cara","Como con cuidado de no tocar la comida","Me limpio las manos con diluyente","Me lavo solo si las manos se ven sucias de adhesivo"],"w":"Las manos sucias llevan el químico a la boca."},{"q":"Tienes adhesivo seco en las manos. ¿Cómo lo sacas?","o":["Con agua y jabón o el limpiador que indique la HDS","Con diluyente, que lo saca más rápido","Con un poco de bencina","Raspando la piel con el cartonero hasta que salga todo"],"w":"La piel absorbe los solventes: nunca se usan para limpiarla."},{"q":"Puedo comer mi colación en el puesto mientras uso adhesivo, si me cuido.","vf":false,"w":"Falso. No se come, bebe ni fuma donde se usan químicos."}]},{"s":"quimicos_eyes","v":[{"q":"Te salpicó adhesivo en los ojos. ¿Qué haces?","o":["Lavo con abundante agua al menos 15 minutos y aviso","Me froto con la manga limpia y sigo","Lavo unos segundos y espero que se pase","Me pongo gotas para los ojos y sigo trabajando con cuidado"],"w":"Agua abundante al menos 15 minutos, párpados abiertos, y avisar."},{"q":"¿Cómo se lavan los ojos tras una salpicadura química?","o":["Con agua abundante y párpados abiertos, al menos 15 minutos","Con agua y los ojos cerrados, durante 1 minuto","Con un paño húmedo, y luego se secan","Con leche o suero fisiológico, para neutralizar el químico de inmediato"],"w":"Los párpados abiertos permiten que el agua arrastre el químico."},{"q":"A tu compañero le saltó solvente a los ojos y ya los lavó 15 minutos. ¿Qué sigue?","o":["Avisar y llevar la HDS a la atención en la ACHS","Que siga trabajando si ya no le arde","Que se ponga lentes oscuros y descanse","Esperar hasta el final del turno para avisar, si sigue con molestias"],"w":"Después del lavado se avisa y se va a atención con la HDS."}]},{"s":"quimicos_pictos","v":[{"q":"¿Cómo son los pictogramas de peligro del SGA?","o":["Rombos con borde rojo, fondo blanco y símbolo negro","Círculos azules con símbolo blanco","Triángulos amarillos con borde negro","Rombos de cuatro colores con números, como el de la NCh 1411/4"],"w":"Así se ven en las etiquetas según el SGA y el DS 57."},{"q":"¿Qué norma exige en Chile los pictogramas del SGA en las etiquetas de sustancias químicas?","o":["DS 57","DS 594","Ley 20.949","Ley 16.744"],"w":"El DS 57 regula la clasificación y el etiquetado de sustancias químicas."},{"q":"Los pictogramas del SGA son rombos de borde rojo con un símbolo negro sobre fondo blanco.","vf":true,"w":"Verdadero. Es el formato de todos los pictogramas del SGA."}]},{"s":"quimicos_pictos","v":[{"q":"El rombo con una silueta humana y una estrella en el pecho indica:","o":["Daño grave a la salud, como asma o cáncer","Que el producto es un irritante leve","Que se debe usar siempre ropa de manga larga al manipularlo","Dónde están los primeros auxilios"],"w":"Es el pictograma de peligro grave para la salud."},{"q":"¿Qué indica el rombo con una llama?","o":["Producto inflamable","Producto corrosivo","Producto que se calienta al usarlo","Producto que daña la salud a largo plazo"],"w":"La llama indica que el producto es inflamable."},{"q":"En la etiqueta del adhesivo ves un rombo con un signo de exclamación. ¿Qué indica?","o":["Irritante o nocivo","Daño grave a la salud","Inflamable","Corrosivo"],"w":"La exclamación indica irritante o nocivo."}]},{"s":"quimicos_ppe","v":[{"q":"La HDS de tu adhesivo indica protección respiratoria. ¿Qué haces?","o":["Uso el respirador indicado durante toda la tarea","Lo uso solo si siento olor fuerte","Abro el portón y trabajo sin respirador","Uso una mascarilla quirúrgica, que es más cómoda para trabajar"],"w":"Un sensibilizante puede dañar aunque no huela: se sigue la HDS."},{"q":"¿Quién define qué guante y qué EPP usar con un adhesivo?","o":["La HDS del producto","La costumbre del puesto","El compañero con más años","Lo que haya disponible en bodega"],"w":"El EPP correcto lo indica la HDS."},{"q":"¿Por qué un adhesivo de poliuretano con isocianatos exige seguir la HDS aunque no huela fuerte?","o":["Porque puede sensibilizar y causar asma","Porque mancha la ropa para siempre","Porque es caro y hay que ahorrarlo","Porque se evapora rápido y se pierde si el envase queda abierto"],"w":"Los isocianatos pueden causar asma laboral sin dar aviso por el olor."}]},{"s":"quimicos_bottles","v":[{"q":"Al trasvasijar adhesivo a un envase más pequeño, ¿qué debe tener el nuevo envase?","o":["Etiqueta con el nombre y los peligros","Solo la fecha en que se trasvasijó","Nada, si se usa en el mismo turno","El nombre de quien lo trasvasijó y la hora en que lo hizo"],"w":"Todo envase con químico debe quedar rotulado."},{"q":"Encuentras un envase sin etiqueta con un líquido que huele a solvente. ¿Qué haces?","o":["No lo uso y aviso a la jefatura","Lo uso como solvente, por el olor","Le pongo la etiqueta que creo que corresponde","Lo mezclo con el solvente rotulado"],"w":"Envase sin etiqueta es peligro desconocido: no se usa ni se adivina."},{"q":"Si se usa solo durante el turno, un envase trasvasijado puede quedar sin etiqueta.","vf":false,"w":"Falso. Aunque sea por un rato, el envase debe quedar rotulado."}]},{"s":"quimicos_store","v":[{"q":"¿Cómo se guardan los envases de adhesivo al terminar?","o":["Cerrados y rotulados en su lugar, lejos de calor y chispas","Abiertos junto a la encoladora para el otro turno","En el pasillo, para tenerlos a mano","Cerrados, junto a la salida de emergencia para sacarlos rápido si hay fuego"],"w":"Así se almacenan de forma segura."},{"q":"¿Cuál de estos lugares NO sirve para dejar un bidón de solvente?","o":["Frente a la salida de emergencia","La bodega de químicos señalizada","Un estante con bandeja antiderrame","Un lugar ventilado y lejos de chispas"],"w":"Los químicos nunca obstruyen salidas ni pasillos."},{"q":"Dos productos que la HDS indica como incompatibles deben almacenarse separados.","vf":true,"w":"Verdadero. Juntos pueden reaccionar, liberar gases o incendiarse."}]},{"s":"quimicos_self","v":[{"q":"Un compañero encola sin guantes ni lentes porque \"es solo pegamento\". ¿Qué es lo correcto?","o":["Leer la etiqueta y usar el EPP que indica","Seguir así si nunca le ha pasado nada","Usar guantes solo si se ensucia mucho","Usar lentes solo cuando se aplica adhesivo en spray o a presión"],"w":"El adhesivo es un químico: se usa el EPP que indica su etiqueta y HDS."},{"q":"¿Cuál es la acción insegura típica con los químicos?","o":["Pensar \"es solo pegamento\" y no usar EPP","Leer la etiqueta antes de usarlo","Mantener el envase tapado","Lavarse las manos antes de comer y al terminar"],"w":"Subestimar el producto es el error más común."},{"q":"Vas a usar un producto que nunca has usado. ¿Cuál es la decisión segura?","o":["Leer su etiqueta y HDS, y usar el EPP indicado","Olerlo para saber si es fuerte","Usarlo igual que el adhesivo de siempre","Usar poca cantidad primero para probar cómo reacciona"],"w":"Antes de usar, se lee la etiqueta y se usa el EPP indicado."}]}]},{"id":"tmert","sec":"planta","title":"Trabajo repetitivo y lesiones de extremidades superiores (TMERT)","thumb":"tmert_intro","learn":[{"s":"tmert_intro","t":"¿Qué son los TMERT?","x":"Son <b>trastornos musculoesqueléticos de extremidades superiores</b>: lesiones de hombros, codos, muñecas y manos, como tendinitis, epicondilitis o síndrome del túnel carpiano. No vienen de un golpe: aparecen <b>de a poco</b>, por tareas repetitivas, con fuerza o en malas posturas. En la planta: encolar, cortar, rebajar, ubicar núcleos de EPS y apilar paneles durante todo el turno."},{"s":"tmert_factores","t":"Los principales factores de riesgo","x":"La Norma Técnica TMERT del MINSAL obliga a la empresa a evaluar los puestos considerando:<ul><li><b>Repetitividad:</b> el mismo movimiento muchas veces.</li><li><b>Fuerza:</b> apretar, empujar o sostener con esfuerzo.</li><li><b>Postura forzada:</b> muñeca doblada, brazos sobre los hombros.</li><li><b>Tiempo de recuperación:</b> si faltan pausas, el riesgo sube.</li></ul>Mientras más factores juntos, mayor riesgo."},{"s":"tmert_repet","t":"Repetitividad","x":"Al repetir el mismo gesto, el tendón roza una y otra vez, como una cuerda que pasa por una polea: con el tiempo se inflama. Ejemplos en {EMP}: pasar el rodillo de adhesivo, alimentar la sierra, ubicar núcleos de EPS o atornillar sin descanso. Mientras más rápido el ritmo y más corto el ciclo, menos tiempo tiene el tendón para recuperarse."},{"s":"tmert_fuerza","t":"Fuerza","x":"Apretar fuerte una herramienta, empujar paneles sobre la mesa o sostener una pieza con una mano carga músculos y tendones. Mientras más fuerza y más tiempo, más daño.<ul><li>Usa ayudas mecánicas, rodillos y prensas.</li><li>Pide ayuda con piezas grandes.</li><li>Agarra con toda la mano, no solo con la punta de los dedos.</li><li>Avisa si una tarea exige demasiada fuerza.</li></ul>"},{"s":"tmert_alto","t":"Posturas forzadas y postura neutra","x":"Las posturas que más dañan: brazos <b>sobre los hombros</b>, como al apilar alto en el rack; <b>muñeca doblada</b> o girada; codos separados del cuerpo. La postura neutra es lo contrario: <b>manos entre la cintura y los hombros, muñeca recta y codos cerca del cuerpo</b>. Acércate a la pieza en vez de estirarte. Para trabajar alto, pide que se baje con la grúa o usa la plataforma adecuada; nunca te subas a las pilas. Si la mesa no calza con tu altura, avisa."},{"s":"tmert_pausa","t":"Pausas: el tiempo de recuperación","x":"Músculos y tendones se recuperan cuando descansan. Usa las <b>pausas establecidas</b>, suelta la herramienta unos segundos entre ciclos y, si están indicados, haz los ejercicios de pausa activa sin forzar. Trabajar \"de corrido\" para salir antes acumula daño: las pausas no se juntan al final ni se cambian por salir temprano.","k":"La pausa es parte del trabajo seguro, no tiempo perdido."},{"s":"tmert_alternar","t":"Alterna tareas","x":"Cambiar de tarea durante el turno hace trabajar otros músculos y deja descansar los que más usaste. Por ejemplo, alternar corte, encolado y apilado. La rotación sirve si las tareas son realmente distintas. <b>Coordínala con tu jefatura</b>: se organiza entre todos, no cada uno por su cuenta ni dejando el puesto sin aviso."},{"s":"tmert_herram","t":"Herramientas adecuadas","x":"Una buena herramienta mantiene la muñeca recta y reduce la fuerza:<ul><li>Mango del tamaño de tu mano y con la forma adecuada a la tarea.</li><li>Herramientas afiladas y en buen estado: un cartonero sin filo obliga a apretar más.</li><li>Guantes de tu talla: uno grande obliga a apretar más.</li></ul>Si una herramienta te obliga a doblar la muñeca, pide otra o cambia la posición de la pieza."},{"s":"tmert_sintomas","t":"Avisa los síntomas temprano","x":"Señales de alerta:<ul><li><b>Hormigueo</b> o adormecimiento de los dedos.</li><li><b>Dolor nocturno</b> en manos o muñecas que te despierta.</li><li><b>Pérdida de fuerza</b>: se te caen las cosas.</li><li>Dolor de hombro o codo que no se pasa.</li></ul>Avisa a tu jefatura y consulta en la ACHS: tratado a tiempo, se recupera mejor. Aunque el dolor se pase el fin de semana, avísalo.","k":"Hormigueo o dolor nocturno: avisa hoy, no cuando sea tarde."},{"s":"tmert_auto","t":"Autocuidado: no aguantes el dolor","x":"La mayoría de los accidentes y lesiones se relacionan con una acción insegura. En TMERT, las típicas son <b>aguantar el dolor</b>, saltarse las pausas para ir más rápido o forzar con la muñeca doblada. La decisión segura: pausar, corregir la postura, pedir ayuda y <b>avisar</b> a tiempo. Reportar una herramienta o una mesa inadecuada también es autocuidado: así se corrige el puesto para todos."}],"quiz":[{"s":"tmert_factores","v":[{"q":"¿Cuáles son los principales factores de riesgo de TMERT?","o":["Repetitividad, fuerza y postura forzada","Ruido, polvo y vibración","Edad, peso y estatura de la persona","Frío, calor y humedad del puesto de trabajo"],"w":"Junto al tiempo de recuperación, son los factores que evalúa la Norma Técnica TMERT."},{"q":"Además de repetición, fuerza y postura, ¿qué otro factor aumenta el riesgo de TMERT?","o":["La falta de pausas o tiempo de recuperación","El uso de zapatos de seguridad","Trabajar con buena iluminación","Usar guantes de la talla correcta para cada mano"],"w":"Sin recuperación, el daño se acumula."},{"q":"Un trabajador pasa el rodillo de adhesivo todo el turno, apretando fuerte, con la muñeca doblada y sin pausas. ¿Qué factores de riesgo tiene?","o":["Los cuatro: repetición, fuerza, postura y falta de pausas","Solo repetición","Solo fuerza y postura","Solo repetición y fuerza; la postura de la muñeca no influye en esa tarea"],"w":"Tiene los cuatro factores juntos: el riesgo es alto."}]},{"s":"tmert_intro","v":[{"q":"¿Qué zonas del cuerpo afectan los TMERT de extremidades superiores?","o":["Hombros, codos, muñecas y manos","Columna lumbar y caderas","Rodillas, tobillos y pies","Solo el cuello y la parte alta de la espalda"],"w":"Afectan las extremidades superiores."},{"q":"¿Cuál de estas lesiones es un TMERT?","o":["Síndrome del túnel carpiano","Lumbago por levantar un panel","Esguince de tobillo por tropezar","Hipoacusia por ruido"],"w":"El túnel carpiano afecta la muñeca y la mano por tareas repetitivas."},{"q":"¿Cómo aparecen habitualmente los TMERT?","o":["De a poco, por la tarea diaria","De golpe, por un accidente puntual","Solo por un golpe directo en la mano","Solo en personas mayores de 50 años que hacen trabajos pesados"],"w":"Se desarrollan lentamente, por la tarea diaria."}]},{"s":"tmert_alto","v":[{"q":"Un compañero apila paneles en lo alto del rack con los brazos sobre los hombros todo el turno. ¿Qué riesgo tiene?","o":["Postura forzada que puede lesionar hombros y codos","Ninguno, si los paneles son livianos","Solo el riesgo de que se caigan los paneles","Solo cansancio muscular, que se pasa con el descanso de la noche"],"w":"Brazos sobre los hombros por largo rato es una postura forzada."},{"q":"¿Cuál de estas posturas es forzada?","o":["Brazos sobre los hombros al apilar alto","Manos entre la cintura y los hombros","Muñeca recta al usar la herramienta","Codos cerca del cuerpo"],"w":"Trabajar sobre los hombros carga hombros y codos."},{"q":"Para dejar paneles en un nivel alto tendrías que trabajar con los brazos sobre la cabeza. ¿Qué es lo correcto?","o":["Pedir que se baje con la grúa o usar una plataforma","Hacerlo rápido para estar menos tiempo así","Estirarse en la punta de los pies","Subirse a la pila de paneles para quedar más cerca del nivel"],"w":"Se evita la postura forzada con medios adecuados, sin estirarse ni trepar."}]},{"s":"tmert_pausa","v":[{"q":"¿Para qué sirven las pausas en una tarea repetitiva?","o":["Para que músculos y tendones se recuperen","Para que la máquina se enfríe","Solo para hidratarse","Solo para conversar con los compañeros y tomar agua"],"w":"La pausa es el tiempo de recuperación del cuerpo."},{"q":"El grupo quiere trabajar de corrido para salir antes. ¿Qué es lo correcto?","o":["Usar las pausas establecidas","Trabajar de corrido si todos están de acuerdo","Saltarse las pausas solo los viernes","Compensar con más pausas al día siguiente, si todos lo acuerdan"],"w":"Las pausas no se juntan ni se cambian por salir temprano."},{"q":"Saltarse las pausas para terminar antes ayuda a prevenir lesiones.","vf":false,"w":"Falso. Sin tiempo de recuperación, el daño se acumula."}]},{"s":"tmert_sintomas","v":[{"q":"Sientes hormigueo en los dedos y un dolor de muñeca que te despierta de noche. ¿Qué haces?","o":["Aviso pronto a mi jefatura y consulto","Aguanto hasta que sea más fuerte","Me pongo una muñequera y no aviso","Trabajo más rápido para terminar antes"],"w":"Son síntomas tempranos: avisar a tiempo permite corregir y tratar."},{"q":"¿Cuál es una señal temprana de TMERT?","o":["Dolor nocturno en manos o muñecas","Cansancio de piernas al final del turno","Sed después de trabajar","Hambre antes de la colación"],"w":"El dolor que despierta de noche es una alerta típica."},{"q":"Se te caen las herramientas porque perdiste fuerza en la mano. ¿Qué corresponde?","o":["Avisar a la jefatura y consultar en la ACHS","Apretar más fuerte para que no se caigan","Cambiar de mano y seguir igual","Esperar unos meses a ver si mejora sola con el descanso"],"w":"La pérdida de fuerza es señal de alerta y se consulta a tiempo."}]},{"s":"tmert_neutro","v":[{"q":"Una postura neutra para las manos es:","o":["Muñeca recta y codos cerca del cuerpo","Muñeca doblada hacia abajo","Codos separados del cuerpo","Manos sobre la altura de los hombros, cerca de la cara"],"w":"Así se reduce la carga en los tendones."},{"q":"¿Entre qué alturas conviene trabajar con las manos?","o":["Entre la cintura y los hombros","Entre los hombros y la parte alta de la cabeza","Bajo las rodillas","Sobre la cabeza"],"w":"Es la zona de menor esfuerzo para hombros y brazos."},{"q":"Acercarte a la pieza en vez de estirar los brazos ayuda a mantener una postura neutra.","vf":true,"w":"Verdadero. Con la pieza cerca, los codos quedan junto al cuerpo."}]},{"s":"tmert_alternar","v":[{"q":"Alternar entre corte, encolado y apilado durante el turno:","o":["Reparte el esfuerzo entre distintos músculos","Aumenta el riesgo de TMERT","Solo sirve para no aburrirse","Reemplaza la necesidad de hacer pausas durante el turno"],"w":"Variar la tarea deja recuperarse a los músculos más usados."},{"q":"Quieres rotar de tarea porque te duele la muñeca. ¿Cómo lo haces?","o":["Lo coordino con mi jefatura","Me cambio solo a otra máquina","Cambio con un compañero sin avisar","Dejo mi puesto un rato sin decir nada"],"w":"La rotación se organiza con la jefatura, no cada uno por su cuenta."},{"q":"¿Por qué sirve rotar entre tareas distintas?","o":["Porque descansan los músculos más usados","Porque se trabajan menos horas","Porque así no se necesitan pausas","Porque elimina por completo la repetición"],"w":"Cada tarea usa músculos diferentes y reparte la carga."}]},{"s":"tmert_herram","v":[{"q":"¿Qué característica debe tener una buena herramienta manual?","o":["Mantener la muñeca recta y exigir menos fuerza","Ser lo más pesada posible para dar firmeza","Tener el mango muy delgado para más precisión","Ser del mismo tamaño para todas las manos, para que sirva a todos"],"w":"Una herramienta adecuada reduce la fuerza y evita doblar la muñeca."},{"q":"Al usar el atornillador, tu muñeca queda doblada todo el rato. ¿Qué haces?","o":["Pido otra herramienta o cambio la posición de la pieza","Sigo igual, es solo un rato","Aprieto más fuerte para terminar rápido","Me pongo un guante más grueso para apretar con menos dolor"],"w":"La muñeca doblada aumenta el riesgo: se corrige la herramienta o la posición."},{"q":"Una herramienta cuyo mango te obliga a doblar la muñeca aumenta el riesgo de TMERT.","vf":true,"w":"Verdadero. La muñeca doblada es una postura forzada."}]},{"s":"tmert_auto","v":[{"q":"¿Cuál es la acción insegura típica que lleva a una lesión TMERT?","o":["Aguantar el dolor y seguir sin avisar","Usar las pausas establecidas","Pedir ayuda con piezas grandes","Avisar que una herramienta no sirve para la tarea"],"w":"El dolor es una alarma: avisar y corregir a tiempo es autocuidado."},{"q":"Te duele la muñeca hace días, pero hay mucha producción. ¿Qué decides?","o":["Aviso hoy y corrijo la tarea con la jefatura","Aguanto hasta que baje la producción","Tomo un analgésico y sigo igual","Uso solo la otra mano por unos días, sin avisar a nadie"],"w":"Avisar temprano evita que la lesión avance."},{"q":"Si el dolor de muñeca se pasa con el descanso del fin de semana, no es necesario avisarlo.","vf":false,"w":"Falso. Es una señal temprana: se avisa aunque mejore con el descanso."}]}]},{"id":"altura","sec":"planta","title":"Trabajo en altura y uso de escaleras","thumb":"altura_intro","learn":[{"s":"altura_intro","t":"¿Qué es trabajo en altura?","x":"Se considera <b>trabajo en altura desde 1,8 m</b> sobre el nivel inferior. Pero caer desde menos, como desde un pallet o la plataforma de un camión, también causa fracturas graves. En {EMP}: racks de bodega, carga de camiones, pilas altas de paneles y montaje en obra. Una caída de más de 1,8 m es <b>accidente grave</b>: se detiene el trabajo, se delimita la zona y se avisa de inmediato a la jefatura."},{"s":"altura_pallet","t":"Nunca sobre pallets ni horquillas","x":"Está <b>prohibido</b> subirse a un pallet, a una pila de paneles, a una silla, a un tambor o a las <b>horquillas de la grúa</b> para alcanzar algo alto. Las horquillas no tienen baranda ni son una plataforma para personas: un movimiento del operador y caes desde varios metros. Usa una escalera adecuada o pide que el operador baje la carga con la grúa.","k":"Las horquillas son para cargas, nunca para personas."},{"s":"altura_inspect","t":"Revisa la escalera antes de usarla","x":"Antes de subir, revisa:<ul><li>Peldaños completos y firmes.</li><li>Largueros sin grietas ni dobleces.</li><li>Zapatas antideslizantes en buen estado.</li><li>Sin aceite, barro ni adhesivo en los peldaños.</li><li>En la de tijera, el tensor o la cadena completa.</li></ul>Si está dañada, <b>no la uses</b>: márcala, retírala y avisa. Nunca la \"arregles\" con alambre o cinta."},{"s":"altura_ladder_ok","t":"Escalera bien instalada","x":"<ul><li>Escalera de apoyo con ángulo aproximado <b>4:1</b>: por cada 4 m de altura, el pie va separado 1 m del muro.</li><li>Que <b>sobresalga</b> cerca de 1 m del apoyo superior para afirmarte al subir y bajar.</li><li>Sobre piso firme y nivelado, nunca sobre cajas o pallets.</li><li>Amarrada arriba, o sujeta por un compañero mientras no lo esté.</li><li>La de tijera, siempre <b>abierta por completo</b> y con el tensor trabado.</li></ul>"},{"s":"altura_3p","t":"Sube y baja con 3 puntos de apoyo","x":"<ul><li>Siempre <b>3 puntos de apoyo</b>: dos manos y un pie, o dos pies y una mano.</li><li><b>De frente</b> a la escalera, al subir y al bajar.</li><li>Manos libres: herramientas en un bolso o cinturón.</li><li>En la de tijera, <b>no subas a los dos últimos peldaños</b> ni te estires hacia los lados: baja y mueve la escalera.</li><li><b>Una persona a la vez.</b></li></ul>"},{"s":"altura_camion_mal","t":"Carga y descarga de camiones","x":"La plataforma del camión es un borde sin protección. Las caídas típicas: <b>retroceder sin mirar</b> al acomodar paneles, pisar la orilla o <b>saltar al bajar</b>. Mira dónde pisas, mantente lejos del borde y no camines de espaldas. Para bajar, hazlo <b>de frente al camión, por la escalera o los peldaños, con 3 puntos de apoyo</b>. Saltar desde 1,2 m basta para romperse un tobillo."},{"s":"altura_apilado","t":"Pilas altas de paneles y racks","x":"No trepes sobre las pilas de paneles ni por los racks para ordenar o sacar algo de arriba: se pueden deslizar o volcar contigo encima, y los paneles de OSB son resbalosos. Para bajar material alto, usa la grúa horquilla con su operador o una escalera adecuada. Respeta la <b>altura máxima de apilamiento</b> que indique tu jefatura y no dejes pilas inclinadas."},{"s":"altura_arnes","t":"Montaje en obra: baranda y arnés","x":"Si en un montaje trabajas sobre una plataforma o andamio, debe tener <b>baranda y rodapié</b>. Donde a 1,8 m o más el borde no se pueda proteger, se usa <b>arnés de cuerpo completo</b> conectado a un <b>punto de anclaje adecuado</b>, nunca a una cañería o a algo que no resista. Revisa el arnés antes de usarlo: costuras, hebillas y cuerda. Úsalo solo con instrucción previa.","k":"Sin baranda sobre 1,8 m: arnés conectado a un anclaje adecuado."},{"s":"altura_herram","t":"Herramientas amarradas y zona inferior","x":"Un objeto que cae desde la altura puede herir gravemente a quien está abajo.<ul><li>Amarra las herramientas o súbelas en un bolso, no en las manos.</li><li><b>Delimita y señaliza</b> la zona inferior con conos o cinta.</li><li>No pases bajo personas trabajando en altura, aunque lleves casco.</li><li>Nunca lances herramientas hacia arriba ni hacia abajo.</li></ul>"},{"s":"altura_auto","t":"Autocuidado: no improvises","x":"La mayoría de los accidentes se relacionan con una acción insegura. En altura, la típica es <b>improvisar \"por un segundo\"</b>: subirse a un pallet, a una silla o a las horquillas, o usar una escalera dañada. La decisión segura: <b>detenerte y buscar el equipo correcto</b>. Avisar una escalera dañada o un borde sin protección también es autocuidado."}],"quiz":[{"s":"altura_intro","v":[{"q":"¿Desde qué altura se considera trabajo en altura?","o":["Desde 1,8 m","Desde 3 m","Desde 1 m","Desde 2,5 m sobre el piso"],"w":"Desde 1,8 m, aunque caer de menos altura también puede ser grave."},{"q":"¿Cuál de estas tareas corresponde a trabajo en altura?","o":["Ordenar material en una plataforma a 2 m del piso","Acomodar paneles sobre una mesa de 90 cm","Subir un escalón de 30 cm","Apilar paneles en el piso hasta la altura de la cintura"],"w":"Sobre 1,8 m del nivel inferior es trabajo en altura."},{"q":"Un compañero cae desde una plataforma a más de 1,8 m. ¿Cómo se considera y qué se hace?","o":["Accidente grave: se detiene, se delimita y se avisa","Accidente leve si puede caminar","Incidente que se informa al final del turno","Accidente menor si no sangra y logra levantarse solo"],"w":"Una caída de más de 1,8 m es accidente grave según SUSESO."}]},{"s":"altura_pallet","v":[{"q":"Necesitas alcanzar un panel alto y la grúa está al lado. ¿Qué haces?","o":["Pido que el operador baje la carga con la grúa","Me subo a las horquillas para que me eleve","Me paro sobre un pallet puesto en las horquillas","Trepo por el rack mientras la grúa espera"],"w":"La grúa mueve cargas, nunca personas."},{"q":"¿Por qué está prohibido que una persona suba a las horquillas de la grúa?","o":["Porque no tienen baranda ni son plataforma para personas","Porque se ensucian y luego resbalan los pallets","Solo porque la grúa pierde potencia","Porque solo el operador autorizado puede tocarlas o subirse a ellas"],"w":"Sin baranda ni plataforma, cualquier movimiento provoca una caída."},{"q":"Puedo subirme a las horquillas de la grúa para alcanzar un panel si es solo un momento.","vf":false,"w":"Falso. Las horquillas son para cargas, nunca para personas."}]},{"s":"altura_ladder_ok","v":[{"q":"Si la escalera debe apoyarse a 4 m de altura, ¿a qué distancia del muro va su pie?","o":["Aproximadamente a 1 m","Pegado al muro","A unos 2 m","A 4 m, igual que la altura"],"w":"Regla 4:1: por cada 4 de altura, 1 de separación."},{"q":"¿Cuánto debe sobresalir una escalera de apoyo sobre el punto superior?","o":["Cerca de 1 m","Nada, al ras del apoyo","Unos 10 cm","Al menos 3 m"],"w":"Sobresalir cerca de 1 m permite afirmarse al subir y bajar."},{"q":"Apoyas una escalera para subir a un nivel de 3 m. ¿Cuál es la instalación correcta?","o":["Pie a unos 75 cm del muro y sobresaliendo cerca de 1 m","Pie pegado al muro para que no resbale","Pie a 3 m del muro para que sea estable","Al ras del nivel superior, sin sobresalir, para que no estorbe al pasar"],"w":"Con la regla 4:1, a 3 m de altura el pie va a unos 75 cm."}]},{"s":"altura_mal_escalera","v":[{"q":"Un compañero está parado en el último peldaño de una escalera de tijera y se estira hacia el rack. ¿Qué está mal?","o":["Usa los últimos peldaños y se estira","Nada, si alguien sujeta la escalera","Solo que no lleva guantes","Solo que la escalera es de aluminio y debería ser de fibra"],"w":"En la tijera no se usan los dos últimos peldaños ni se estira el cuerpo."},{"q":"En una escalera de tijera te faltan 30 cm para alcanzar el material. ¿Qué haces?","o":["Bajo y busco una escalera más alta o la acerco","Subo al último peldaño con cuidado","Me estiro de lado afirmado con una mano","Me paro sobre la bandeja superior de la escalera para ganar altura"],"w":"Si no alcanzas, se cambia o se mueve la escalera."},{"q":"¿Hasta qué peldaño puedes subir en una escalera de tijera?","o":["Hasta antes de los dos últimos peldaños","Hasta el último peldaño, si está firme","Hasta la tapa superior","Sin límite, siempre que la escalera sea corta y esté firme"],"w":"Los dos últimos peldaños no dan apoyo suficiente."}]},{"s":"altura_3p","v":[{"q":"\"3 puntos de apoyo\" significa:","o":["Dos manos y un pie, o dos pies y una mano","Subir de tres en tres peldaños","Tres personas sujetando la escalera","Tres amarras que sujetan la escalera al muro"],"w":"Siempre tres puntos de contacto con la escalera."},{"q":"Necesitas subir un taladro por la escalera. ¿Cómo lo haces?","o":["En un bolso o cinturón, con las manos libres","En una mano, afirmándome con la otra","Bajo el brazo, apretado contra el cuerpo","Que me lo lancen cuando ya esté arriba y afirmado"],"w":"Con las manos libres se mantienen los 3 puntos de apoyo."},{"q":"Para bajar de una escalera, debes hacerlo de frente a ella.","vf":true,"w":"Verdadero. De frente puedes mantener 3 puntos de apoyo."}]},{"s":"altura_inspect","v":[{"q":"Encuentras una escalera con un peldaño suelto. ¿Qué haces?","o":["No la uso, la marco, la retiro y aviso","La uso con cuidado sin pisar ese peldaño","La amarro con alambre y la uso","La dejo donde está para que otro la vea"],"w":"Una escalera dañada no se usa ni se repara improvisando."},{"q":"¿Qué revisas en una escalera antes de subir?","o":["Peldaños, largueros, zapatas y limpieza","Solo que sea suficientemente alta","Solo que tenga la etiqueta del fabricante","Solo que esté limpia por fuera"],"w":"La revisión previa detecta fallas antes de subir."},{"q":"La escalera tiene restos de adhesivo y aceite en los peldaños. ¿Qué haces?","o":["No la uso hasta que esté limpia","La uso con guantes para afirmarme mejor","Subo rápido para no resbalar","La uso, porque el adhesivo da agarre"],"w":"Peldaños con aceite o adhesivo son causa de resbalones."}]},{"s":"altura_camion_mal","v":[{"q":"Terminaste de acomodar paneles sobre el camión. ¿Cómo bajas?","o":["De frente, por los peldaños, con 3 puntos de apoyo","Saltando desde la plataforma","De espaldas, deslizándome por la carga","Afirmado del espejo y saltando el último tramo, con las rodillas flexionadas"],"w":"Bajar de frente con 3 puntos de apoyo evita caídas."},{"q":"¿Cuál es la caída típica al cargar paneles sobre el camión?","o":["Retroceder sin mirar y caer por el borde","Resbalar dentro de la cabina","Caer al subir a la grúa horquilla","Tropezar con un panel apoyado en el piso de la bodega"],"w":"Caminar de espaldas sobre la plataforma lleva al borde."},{"q":"Mientras acomodas un panel sobre el camión, necesitas retroceder. ¿Qué haces?","o":["Miro dónde piso y me mantengo lejos del borde","Retrocedo rápido para terminar luego","Retrocedo mirando el panel","Le pido al chofer que me grite cuando llegue al borde"],"w":"Se mira dónde se pisa y no se camina de espaldas hacia el borde."}]},{"s":"altura_3p","v":[{"q":"¿Cuántas personas pueden estar a la vez sobre una escalera portátil?","o":["Una","Dos, si son livianas","Dos, una a cada lado","Las que quepan sin pasar el peso"],"w":"La escalera portátil es para una persona a la vez."},{"q":"Tu compañero está arriba de la escalera y necesitas pasarle una herramienta. ¿Qué haces?","o":["Se la paso desde abajo en un bolso o con una cuerda","Subo detrás de él para entregársela","Se la lanzo para que la agarre","Me subo a una caja firme junto a la escalera y se la paso"],"w":"Nunca dos personas en la misma escalera ni herramientas lanzadas."},{"q":"Dos personas pueden subir juntas a la misma escalera portátil para terminar más rápido.","vf":false,"w":"Falso. Una persona a la vez."}]},{"s":"altura_arnes","v":[{"q":"En un borde sin baranda donde corresponde usar arnés, ¿a qué lo conectas?","o":["A un punto de anclaje adecuado","A la cañería más cercana","A la baranda de una escalera","A nada: basta con tenerlo puesto"],"w":"Un arnés sin anclaje adecuado no detiene la caída."},{"q":"¿Qué tipo de arnés se usa para detener una caída?","o":["Arnés de cuerpo completo","Cinturón de cintura","Faja lumbar","Cuerda amarrada a la cintura"],"w":"Solo el arnés de cuerpo completo reparte la fuerza de la caída."},{"q":"Antes de usar un arnés debes haber recibido instrucción para usarlo.","vf":true,"w":"Verdadero. Mal puesto o mal conectado, no protege."}]},{"s":"altura_herram","v":[{"q":"Mientras un compañero trabaja en altura, la zona de abajo debe:","o":["Estar delimitada y señalizada","Usarse como pasillo corto","Tener material acopiado","Quedar libre solo si hay viento"],"w":"Así nadie queda expuesto a la caída de objetos."},{"q":"¿Cómo se suben las herramientas para trabajar en una plataforma?","o":["Amarradas o en un bolso","En la mano, una por una","En los bolsillos del pantalón","Lanzándolas desde abajo"],"w":"Las herramientas amarradas no caen sobre quien está abajo."},{"q":"Ves una zona delimitada con conos bajo una plataforma con gente trabajando. ¿Qué haces?","o":["La rodeo: no paso bajo personas trabajando en altura","Paso rápido porque llevo casco","Paso si no veo nada cayendo","Muevo un cono y paso con cuidado mirando hacia arriba"],"w":"La zona delimitada no se cruza, aunque lleves casco."}]}]},{"id":"horquilla_checklist","sec":"grua","title":"Revisión pre-uso y cuidado de la grúa","thumb":"horquilla_checklist_porque","mins":5,"learn":[{"s":"horquilla_checklist_porque","t":"El check-list diario","x":"Antes de usar la grúa <b>en cada turno</b>, el operador la revisa con el <b>check-list</b>, aunque otro la haya revisado antes. Solo la revisa y opera quien tiene <b>licencia clase D y autorización escrita</b> de {EMP}. Un freno que falla con un paquete de paneles arriba no se arregla en el momento: la revisión toma unos minutos y dice si la máquina puede trabajar <b>hoy</b>."},{"s":"horquilla_checklist_vuelta","t":"La vuelta alrededor","x":"Con el <b>motor apagado</b>, da una vuelta completa a la grúa y mira:<ul><li><b>Neumáticos:</b> cortes, desgaste, pernos sueltos.</li><li><b>Fugas:</b> manchas de aceite, combustible o líquido bajo la grúa.</li><li>Golpes o piezas sueltas.</li><li>Techo protector y respaldo de carga en su lugar.</li><li>Extintor de la grúa, si tiene, cargado y en su soporte.</li></ul>Una mancha bajo la grúa es un aviso de falla."},{"s":"horquilla_checklist_horq","t":"Horquillas, cadenas y mástil","x":"<ul><li><b>Horquillas:</b> sin trizaduras, sin estar dobladas ni gastadas y con su traba puesta.</li><li><b>Cadenas:</b> sin eslabones dañados y con tensión pareja en ambos lados.</li><li><b>Mástil:</b> sin golpes; las <b>mangueras hidráulicas</b> sin fugas ni grietas.</li></ul>Lo que sostiene la carga se revisa con atención: si una horquilla o una cadena falla, la carga cae sobre quien esté cerca."},{"s":"horquilla_checklist_cabina","t":"Desde el asiento, motor encendido","x":"Ponte el <b>cinturón</b>, enciende y prueba:<ul><li><b>Frenos</b> de servicio y de estacionamiento.</li><li><b>Dirección:</b> que gire suave, sin juego.</li><li><b>Bocina</b> y <b>luces</b>.</li><li><b>Alarma de retroceso</b> y baliza.</li><li>Subir, bajar e inclinar el mástil, sin tirones ni ruidos raros.</li></ul>Si no frena, no avisa o no levanta bien, la grúa no sale a trabajar."},{"s":"horquilla_checklist_falla","t":"Si algo falla","x":"<ul><li><b>No la uses</b>, ni \"solo un rato\" ni con cargas livianas.</li><li><b>Informa</b> de inmediato a tu jefatura.</li><li><b>Bloquéala</b>: saca la llave y pon la tarjeta de \"NO OPERAR\" o el aviso que use la planta.</li></ul>Así el siguiente turno no la usa sin saber. No intentes repararla si no es tu función: la repara personal de mantención.","k":"Grúa con falla: no se usa, se informa y se bloquea."},{"s":"horquilla_checklist_firma","t":"Marca con la verdad","x":"El check-list es un <b>registro</b>: lo que marcas queda como constancia de que la grúa se revisó. <b>Nunca lo firmes sin revisar</b>, ni marques \"bien\" algo que está mal, ni firmes por otro operador. Si un ítem está malo, anótalo y describe la falla: ese registro sirve para que la reparen y protege al próximo operador. Firmar sin revisar es engañarte a ti mismo."},{"s":"horquilla_checklist_glp","t":"Si tu grúa es a gas: cambio de cilindro","x":"Según el manual del fabricante:<ul><li><b>Motor apagado</b> y válvula del cilindro cerrada antes de desconectar.</li><li>En lugar ventilado, <b>lejos de fuego</b> y sin fumar.</li><li>Usa guantes y lentes: el gas licuado puede quemar la piel por frío.</li><li>Fija bien el cilindro y revisa la conexión.</li><li>Busca fugas con <b>agua jabonosa</b>: si salen burbujas, hay fuga. Nunca con una llama.</li></ul>","k":"Las fugas de gas se buscan con agua jabonosa, jamás con fuego."},{"s":"horquilla_checklist_bateria","t":"Si tu grúa es eléctrica: carga de batería","x":"<ul><li>Carga solo en el <b>lugar destinado</b>, ventilado y señalizado.</li><li>Grúa apagada y freno puesto antes de conectar.</li><li><b>No fumes</b> ni hagas chispas: algunas baterías liberan gases inflamables al cargar.</li><li>Revisa que el cable y el conector del cargador no estén dañados.</li><li>Si hay riesgo de ácido, usa guantes y lentes.</li></ul>"},{"s":"horquilla_checklist_combustible","t":"Carga de combustible","x":"Si tu grúa usa diésel o bencina:<ul><li><b>Motor apagado</b> siempre al cargar.</li><li><b>No fumes</b> ni uses llamas ni celular cerca.</li><li>No llenes hasta rebalsar; <b>limpia los derrames</b> antes de encender.</li><li>Ten ubicado el extintor más cercano.</li></ul>Un vapor de combustible y una chispa bastan para un incendio, y en la planta hay OSB y EPS que arden muy rápido."},{"s":"horquilla_checklist_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una acción insegura. Aquí, la típica es <b>saltarse la revisión</b> porque \"ayer andaba bien\" o hay apuro, y <b>usar la grúa con una falla</b> conocida. Una falla puede aparecer de un turno a otro. La decisión segura: revisarla cada turno y <b>detenerla si algo falla</b>. Avisar una falla a tu jefatura o al asesor en prevención también es autocuidado."}],"quiz":[{"s":"horquilla_checklist_porque","v":[{"q":"¿Cuándo se hace el check-list de la grúa?","o":["Antes de usarla en cada turno","Una vez a la semana","Solo cuando hace ruidos raros","Cuando lo pide mantención o la jefatura"],"w":"La revisión es diaria, antes de usarla en tu turno."},{"q":"¿Para qué sirve el check-list diario de la grúa?","o":["Para saber si la grúa puede trabajar hoy","Para reemplazar la mantención del fabricante","Para registrar las horas extra del operador","Para saber cuánto combustible gastó ayer"],"w":"El check-list confirma que la máquina está en condiciones antes de operar."},{"q":"Comienzas tu turno y la grúa está estacionada con la llave puesta. ¿Qué haces primero?","o":["Hago el check-list antes de operarla","La uso y la reviso al final del turno","La enciendo y salgo a trabajar","Pregunto si ayer funcionó y salgo"],"w":"Primero se revisa, después se opera."}]},{"s":"horquilla_checklist_q_frenos","v":[{"q":"Al probar la grúa, el freno se siente blando. ¿Qué haces?","o":["No la uso, informo a mi jefatura y la bloqueo","La uso con cuidado y a poca velocidad","La uso hasta terminar el turno y luego aviso","Uso solo el freno de estacionamiento hasta que la reparen"],"w":"Grúa con falla: no se usa, se informa y se bloquea."},{"q":"¿Cuáles son los tres pasos si la grúa tiene una falla?","o":["No usarla, informar y bloquearla","Usarla con cuidado, informar y anotar","Repararla, probarla y seguir","Estacionarla, dejar la llave y retirarse"],"w":"No usar, informar y bloquear evita que otro la use sin saber."},{"q":"El freno de servicio falla y ya informaste a la jefatura. ¿Qué falta?","o":["Bloquearla: sacar la llave y poner la tarjeta de NO OPERAR","Nada, la jefatura ya está informada","Dejarle la llave puesta al mecánico","Seguir usándola con cuidado hasta que llegue el mecánico a revisarla"],"w":"Sin bloqueo, el siguiente turno puede usarla sin saber."}]},{"s":"horquilla_checklist_jabon","v":[{"q":"¿Cuál es la forma correcta de buscar una fuga de gas en el cilindro?","o":["Con agua jabonosa: las burbujas muestran la fuga","Acercando un encendedor a la conexión","Oliendo de cerca la válvula abierta","Escuchando con el motor encendido si se oye un silbido"],"w":"Las fugas se buscan con agua jabonosa, jamás con una llama."},{"q":"Después de conectar el cilindro de gas sientes olor a gas. ¿Cómo encuentras la fuga?","o":["Aplico agua jabonosa en la conexión y busco burbujas","Acerco una llama pequeña a la conexión","Enciendo el motor para ver si anda bien","Aprieto la conexión con fuerza y sigo si el olor desaparece"],"w":"El agua jabonosa muestra la fuga sin riesgo de encenderla."},{"q":"Si al aplicar agua jabonosa en la conexión del cilindro aparecen burbujas, hay una fuga de gas.","vf":true,"w":"Verdadero. Las burbujas indican por dónde escapa el gas."}]},{"s":"horquilla_checklist_vuelta","v":[{"q":"Si el check-list del turno anterior está firmado, yo no necesito revisar la grúa.","vf":false,"w":"Falso. Cada operador revisa antes de usarla en su turno: algo pudo cambiar."},{"q":"En la vuelta alrededor ves una mancha de aceite bajo la grúa. ¿Qué haces?","o":["La trato como posible fuga e informo antes de operar","Sigo, es normal en grúas usadas","La limpio y opero sin avisar","Opero normal y vuelvo a revisar la mancha mañana"],"w":"Una mancha bajo la grúa puede indicar una fuga: se informa."},{"q":"¿En qué estado debe estar el motor durante la vuelta alrededor de la grúa?","o":["Apagado","Encendido en neutro","Encendido con el mástil arriba","Da lo mismo"],"w":"La inspección exterior se hace con el motor apagado."}]},{"s":"horquilla_checklist_cabina","v":[{"q":"La alarma de retroceso no suena, pero la bocina sí. ¿Puedo usar la grúa igual?","o":["No: es una falla, se informa y no se usa","Sí, con la bocina basta","Sí, si retrocedo poco","Sí, si un compañero camina detrás y me guía"],"w":"Si un dispositivo de aviso falla, la grúa tiene una falla."},{"q":"¿Qué pruebas desde el asiento con el motor encendido?","o":["Frenos, dirección, bocina, luces, alarma y mástil","Solo neumáticos y fugas","Solo el nivel de combustible","Solo que encienda sin problemas y no tenga luces de falla"],"w":"Esas pruebas confirman que la grúa frena, avisa y levanta bien."},{"q":"Antes de probar los frenos desde el asiento, ¿qué haces?","o":["Me pongo el cinturón","Subo el mástil al máximo","Cargo un pallet en las horquillas","Pruebo primero y luego me lo pongo"],"w":"El cinturón va puesto antes de mover la grúa."}]},{"s":"horquilla_checklist_horq","v":[{"q":"En la vuelta ves un eslabón de la cadena del mástil dañado. ¿Qué corresponde?","o":["Detener la grúa e informar: la cadena sostiene la carga","Seguir operando solo con cargas livianas","Lubricar la cadena y seguir","Seguir operando y avisar al final del turno"],"w":"Si la cadena se corta, la carga cae."},{"q":"Una horquilla tiene una trizadura pequeña. ¿Qué haces?","o":["No uso la grúa e informo","La uso solo con paquetes livianos","Cargo más peso en la otra horquilla","La uso hasta que la trizadura crezca"],"w":"Una horquilla trizada puede romperse con la carga arriba."},{"q":"¿Qué revisas en el mástil y las mangueras hidráulicas?","o":["Que no tengan golpes, fugas ni grietas","Solo que estén limpias","Que conserven su pintura original","Solo que tengan el largo correcto y estén bien pintados"],"w":"Una manguera con fuga puede hacer caer la carga."}]},{"s":"horquilla_checklist_q_glp","v":[{"q":"Al cambiar el cilindro de gas, lo primero es:","o":["Apagar el motor y cerrar la válvula del cilindro","Soltar la conexión con el motor en ralentí","Abrir la válvula para vaciar el gas restante","Retirar el cilindro vacío y luego apagar el motor"],"w":"Motor apagado y válvula cerrada antes de desconectar."},{"q":"¿Dónde se cambia el cilindro de gas de la grúa?","o":["En un lugar ventilado, lejos de fuego y sin fumar","Dentro de una bodega cerrada, para que no llueva","Junto a la sierra, donde se usa la grúa","En cualquier parte de la planta, si el motor está apagado"],"w":"El gas necesita ventilación y ninguna fuente de ignición cerca."},{"q":"¿Qué EPP usas al cambiar el cilindro de gas?","o":["Guantes y lentes","Solo protector auditivo","Solo respirador para polvo","Ninguno, es una tarea corta"],"w":"El gas licuado puede quemar la piel y los ojos por frío."}]},{"s":"horquilla_checklist_q_comb","v":[{"q":"Al cargar combustible, el motor puede quedar encendido si es solo un momento.","vf":false,"w":"Falso. El motor va apagado siempre al cargar combustible."},{"q":"Al cargar diésel, el estanque rebalsa y cae combustible al piso. ¿Qué haces?","o":["Limpio el derrame antes de encender","Enciendo y me alejo rápido","Dejo que se evapore solo","Lo cubro con un cartón y sigo trabajando normalmente"],"w":"El combustible derramado puede encenderse con una chispa."},{"q":"¿Qué debes tener ubicado mientras cargas combustible?","o":["El extintor más cercano","El check-list del día anterior","La llave de repuesto","La manguera de agua"],"w":"Ante un amago de incendio se actúa con el extintor; con agua, el combustible se esparce."}]},{"s":"horquilla_checklist_q_bat","v":[{"q":"¿Dónde se carga la batería de una grúa eléctrica?","o":["En el lugar destinado y ventilado, sin fuego ni chispas","En cualquier enchufe de la bodega","En una sala cerrada para que no se moje","Junto al encolado, que queda más cerca de la bodega"],"w":"La carga se hace solo en el lugar destinado, ventilado."},{"q":"Antes de conectar el cargador a la batería, ¿qué haces?","o":["Apago la grúa y pongo el freno","La dejo encendida para que cargue más rápido","Levanto el mástil para despejar","Nada, solo conecto"],"w":"Grúa apagada y frenada antes de conectar."},{"q":"Al cargar, algunas baterías liberan gases inflamables.","vf":true,"w":"Verdadero. Por eso se cargan en lugar ventilado, sin fumar ni hacer chispas."}]},{"s":"horquilla_q_apuro","v":[{"q":"Hay apuro y la grúa \"ayer andaba bien\". ¿Cuál es la decisión segura?","o":["Hacer el check-list igual: toma unos minutos","Saltarme la revisión por hoy","Revisar solo los frenos","Firmar el check-list ahora y revisar cuando haya menos trabajo"],"w":"Saltarse la revisión es la acción insegura típica."},{"q":"Un compañero te pide firmar el check-list sin revisar porque hay apuro. ¿Qué haces?","o":["Reviso y marco solo lo que comprobé","Firmo, total ayer estaba bien","Firmo y reviso si me queda tiempo","Le pido que lo firme él por mí, ya que él la usó antes"],"w":"El check-list es un registro: se firma solo lo revisado."},{"q":"¿Por qué no basta con que la grúa \"ayer andaba bien\"?","o":["Porque una falla puede aparecer de un turno a otro","Porque el check-list vence cada semana","Porque otro operador pudo ensuciarla","Porque la jefatura revisa las firmas cada semana"],"w":"Cada turno puede traer una falla nueva."}]}]},{"id":"pvd","sec":"admin","title":"Trabajo con computador: ergonomía y pausas","thumb":"pvd_intro","learn":[{"s":"pvd_intro","t":"Muchas horas frente a la pantalla","x":"En {EMP}, quienes trabajan en administración, ventas, adquisiciones o planificación pasan horas frente al computador. Una mala postura no duele el primer día, pero <b>sumada día a día</b> puede terminar en dolor de cuello, espalda, hombros y muñecas, o en lesiones como tendinitis. Ajustar tu puesto toma cinco minutos y se hace una vez: pantalla, silla, teclado y mouse."},{"s":"pvd_pantalla","t":"La pantalla","x":"<ul><li>El <b>borde superior a la altura de los ojos</b> o un poco más abajo.</li><li>A unos <b>50 a 70 cm</b>: más o menos un brazo estirado.</li><li><b>De frente</b>, no girada a un lado: girar el cuello todo el día lo sobrecarga.</li></ul>Si la pantalla está baja, ponle una base firme debajo. Si usas dos pantallas, la principal va al frente."},{"s":"pvd_silla","t":"Silla, espalda y pies","x":"<ul><li>Regula la altura: <b>codos en ángulo recto</b>, a la altura del escritorio.</li><li>Siéntate atrás, con la espalda <b>apoyada en el respaldo</b>, sobre todo la zona lumbar.</li><li><b>Pies planos</b> en el suelo o en un apoyapiés.</li><li>Hombros relajados, sin encogerlos.</li></ul>Si tu silla no se regula o está dañada, avisa a tu jefatura."},{"s":"pvd_teclado","t":"Teclado y mouse","x":"<ul><li>Teclado <b>cerca</b>, frente a ti, a la altura de los codos.</li><li><b>Muñecas rectas</b>: ni dobladas hacia arriba ni hacia los lados.</li><li>Mouse <b>al lado del teclado</b>, sin estirar el brazo.</li><li>Antebrazos apoyados en el escritorio, sin apoyar la muñeca en un borde filoso.</li></ul>Usar atajos de teclado también reduce los movimientos del mouse."},{"s":"pvd_vista","t":"Descansa la vista: 20-20-20","x":"Una <b>recomendación práctica</b>, no una norma legal: cada <b>20 minutos</b>, mira algo lejano, a unos 6 metros, durante <b>20 segundos</b>. Parpadea a propósito: frente a la pantalla parpadeamos menos y los ojos se secan. Ojos cansados, ardor, ojos secos o visión borrosa son señales para descansar. Si se repiten, consulta."},{"s":"pvd_pausas","t":"Pausas activas","x":"Estar quieto también cansa: los músculos que sostienen la postura trabajan todo el rato. Cada cierto rato:<ul><li><b>Levántate</b> y camina un poco.</li><li>Estira cuello, hombros, espalda y muñecas, sin forzar ni hacer movimientos bruscos.</li><li>Cambia de postura.</li></ul>Aprovecha tareas como ir a la impresora o a bodega para moverte.","k":"Levántate, estira y camina cada cierto rato."},{"s":"pvd_notebook","t":"Notebook y celular","x":"<ul><li>El notebook plano obliga a agachar la cabeza. Si lo usas muchas horas, ponlo sobre una <b>base</b> y usa <b>teclado y mouse aparte</b>.</li><li>El <b>celular</b>: súbelo a la altura de los ojos en vez de doblar el cuello.</li><li>En teletrabajo, usa una mesa y una silla; evita trabajar en la cama o el sillón.</li></ul>"},{"s":"pvd_luz","t":"Luz y reflejos","x":"<ul><li>Pon la pantalla <b>al costado de la ventana</b>: de frente encandila y de espaldas produce reflejos.</li><li>Usa cortinas o persianas si el sol pega en la pantalla.</li><li>Ajusta el brillo a la luz del lugar.</li><li>Limpia la pantalla.</li></ul>Los reflejos te obligan a forzar la vista y a torcer el cuerpo para esquivarlos."},{"s":"pvd_sintomas","t":"Señales de alerta","x":"Los <b>trastornos musculoesqueléticos de extremidades superiores (TMERT)</b> avisan antes:<ul><li>Dolor en cuello, hombros, codos o muñecas.</li><li>Hormigueo o adormecimiento en manos y dedos.</li><li>Pérdida de fuerza.</li></ul>Si se repiten, <b>avisa a tu jefatura</b> y consulta en la ACHS. Tratado a tiempo, se recupera mejor y más rápido.","k":"Hormigueo o dolor que se repite: avisa y consulta."},{"s":"pvd_auto","t":"Autocuidado: \"termino y paro\"","x":"La mayoría de los accidentes y lesiones se relacionan con una acción insegura. Frente al computador, la típica es <b>\"termino esto y paro\"</b>: horas encorvado sin moverte, ignorando el dolor. La decisión segura: <b>ajusta tu puesto y haz la pausa ahora</b>, no cuando termines. Avisar que tu silla o tu pantalla no sirven también es autocuidado."}],"quiz":[{"s":"pvd_pantalla","v":[{"q":"¿A qué altura debe estar el borde superior de la pantalla?","o":["A la altura de los ojos o un poco más abajo","Por encima de la cabeza","A la altura del pecho","A la altura del teclado, para mirar hacia abajo"],"w":"Así el cuello queda recto."},{"q":"¿A qué distancia de tus ojos debe quedar la pantalla?","o":["A unos 50 a 70 cm, un brazo estirado","A unos 20 cm, para ver mejor","A más de 1,5 m","Lo más cerca posible, para no forzar la vista"],"w":"A un brazo de distancia se ve bien sin forzar la vista ni el cuello."},{"q":"Tu pantalla está a un costado y debes girar el cuello para verla. ¿Qué haces?","o":["La pongo de frente","La dejo así y giro la silla a ratos","La subo más alto","Le bajo el brillo"],"w":"La pantalla va de frente para no torcer el cuello."}]},{"s":"pvd_cel_mal","v":[{"q":"Revisas correos en el celular con el cuello doblado. ¿Qué es lo correcto?","o":["Subir el celular a la altura de los ojos","Agachar más la cabeza para ver mejor","Aumentar la letra y seguir en la misma postura","Apoyar el celular en las piernas"],"w":"Subir el celular evita doblar el cuello."},{"q":"¿Qué parte del cuerpo se sobrecarga al mirar el celular hacia abajo por mucho rato?","o":["El cuello","Las rodillas","Los tobillos","La zona lumbar solamente"],"w":"La cabeza inclinada carga la columna del cuello."},{"q":"Mirar el celular con el cuello doblado por largos ratos sobrecarga el cuello.","vf":true,"w":"Verdadero. Por eso se sube el celular a la altura de los ojos."}]},{"s":"pvd_teclado","v":[{"q":"Al escribir, las muñecas deben estar:","o":["Rectas, con el teclado cerca","Dobladas hacia arriba","Dobladas hacia los lados","Apoyadas en el borde del escritorio"],"w":"Muñecas rectas y teclado cerca, a la altura de los codos."},{"q":"¿Dónde debe estar el mouse?","o":["Al lado del teclado","Al fondo del escritorio","Sobre un cuaderno alto","En el extremo de la mesa"],"w":"Junto al teclado no se estira el brazo."},{"q":"Usas el mouse con el brazo estirado todo el día. ¿Qué corriges?","o":["Acerco el mouse junto al teclado","Lo uso con la otra mano","Pongo un cojín bajo el codo y sigo","Lo cambio por uno más grande"],"w":"El brazo estirado sobrecarga hombro y codo."}]},{"s":"pvd_vista","v":[{"q":"La regla 20-20-20 es una norma legal obligatoria en Chile.","vf":false,"w":"Falso. Es una recomendación práctica para descansar la vista."},{"q":"Según la regla 20-20-20, cada 20 minutos debes:","o":["Mirar algo lejano durante 20 segundos","Cerrar los ojos durante 20 minutos","Alejarte 20 metros de la pantalla","Parpadear 20 veces seguidas mirando la pantalla"],"w":"Mirar lejos unos 20 segundos relaja la vista."},{"q":"Al final del día tienes los ojos secos y con ardor. ¿Qué te ayuda?","o":["Mirar lejos cada 20 minutos y parpadear a propósito","Subir el brillo al máximo","Acercarme más a la pantalla","Trabajar sin pausas para terminar antes y descansar en la casa"],"w":"Frente a la pantalla parpadeamos menos y los ojos se secan."}]},{"s":"pvd_silla","v":[{"q":"Los pies deben quedar:","o":["Planos en el suelo o en un apoyapiés","Colgando de la silla","Cruzados bajo la silla","Apoyados en la base con ruedas de la silla"],"w":"Pies apoyados, espalda en el respaldo y codos en ángulo recto."},{"q":"¿Cómo regulas la altura de la silla?","o":["Con los codos en ángulo recto a la altura del escritorio","Con los hombros levantados para alcanzar el teclado","Lo más baja posible","Con las rodillas sobre la altura de la cadera, bien recogidas"],"w":"Los codos en ángulo recto marcan la altura correcta."},{"q":"Trabajas sentado en el borde de la silla, sin apoyar la espalda. ¿Qué corriges?","o":["Me siento atrás, con la zona lumbar apoyada","Bajo la pantalla","Subo los pies a la silla","Me inclino más hacia adelante para ver mejor la pantalla"],"w":"La espalda apoyada descarga la zona lumbar."}]},{"s":"pvd_luz","v":[{"q":"¿Dónde conviene poner la pantalla respecto de la ventana?","o":["Al costado de la ventana","De frente a la ventana","De espaldas a la ventana","Pegada a la ventana, para aprovechar la luz natural"],"w":"Al costado se evitan reflejos y encandilamiento."},{"q":"El sol de la tarde se refleja en tu pantalla. ¿Qué haces?","o":["Cierro la cortina o persiana y ajusto el brillo","Inclino la cabeza para esquivar el reflejo","Subo el brillo al máximo","Me acerco más a la pantalla para leer mejor"],"w":"Controlar la luz evita forzar la vista y la postura."},{"q":"Los reflejos en la pantalla te obligan a forzar la vista y la postura.","vf":true,"w":"Verdadero. Por eso la pantalla va al costado de la ventana."}]},{"s":"pvd_notebook","v":[{"q":"Si usas notebook muchas horas, lo recomendable es:","o":["Ponerlo en una base y usar teclado y mouse aparte","Usarlo sobre las piernas en el sillón","Bajar el brillo al mínimo","Usarlo plano en el escritorio, con su propio teclado"],"w":"Así la pantalla sube a la altura de los ojos."},{"q":"¿Por qué un notebook plano en el escritorio provoca dolor de cuello?","o":["Porque obliga a agachar la cabeza","Porque calienta el escritorio","Porque su teclado es más blando","Porque pesa más que un computador de escritorio"],"w":"La pantalla baja obliga a doblar el cuello."},{"q":"Haces teletrabajo algunos días. ¿Cuál es la mejor opción?","o":["Mesa con el notebook en una base, teclado y mouse aparte","Cama con el notebook en las piernas","Sillón con el notebook sobre un cojín","Mesa con el notebook plano, usando su propio teclado y el touchpad"],"w":"En casa se aplican las mismas reglas de postura."}]},{"s":"pvd_sintomas","v":[{"q":"Tienes hormigueo en las manos varias veces a la semana. ¿Qué haces?","o":["Aviso a mi jefatura y consulto en la ACHS","Espero que se pase solo","Tomo un analgésico sin consultar","Me pongo una muñequera y no digo nada mientras se pueda trabajar"],"w":"Es una señal de alerta de TMERT: se avisa y se consulta a tiempo."},{"q":"¿Cuál de estas es una señal de alerta de TMERT por trabajo con computador?","o":["Adormecimiento de manos y dedos","Sueño después de almuerzo","Hambre a media mañana","Frío en los pies en los días de invierno"],"w":"El adormecimiento de manos es una alerta típica."},{"q":"Llevas semanas con un dolor de hombro que no se pasa. ¿Qué corresponde?","o":["Avisar y consultar a tiempo","Seguir igual, es por la edad","Cambiar el mouse de mano sin avisar","Esperar a las vacaciones"],"w":"Un dolor que se repite se avisa y se consulta."}]},{"s":"pvd_pausas","v":[{"q":"Las pausas activas sirven solo para quienes cargan peso.","vf":false,"w":"Falso. Estar quieto también cansa: levántate, estira y camina."},{"q":"¿Qué es una pausa activa frente al computador?","o":["Levantarse, caminar y estirar sin forzar","Mirar el celular sentado","Cambiar de ventana en el computador","Comer algo en el escritorio mientras se revisan correos"],"w":"La pausa activa implica moverse y estirar."},{"q":"Llevas dos horas sentado sin moverte. ¿Qué haces?","o":["Me levanto, camino y estiro","Sigo hasta terminar el informe","Me acomodo en la silla y sigo","Estiro el cuello con un tirón fuerte"],"w":"Moverse cada cierto rato evita la sobrecarga; los estiramientos se hacen sin forzar."}]},{"s":"pvd_auto","v":[{"q":"¿Cuál es la acción insegura típica frente al computador?","o":["Decir \"termino esto y paro\" y seguir horas sin moverse","Ajustar la altura de la silla","Hacer pausas activas","Avisar que la silla no se regula o está dañada"],"w":"Postergar la pausa e ignorar el dolor es el error más común."},{"q":"Tu silla no se regula y te duele la espalda. ¿Qué haces?","o":["Aviso a mi jefatura para cambiarla","Me acostumbro con el tiempo","Pongo un cojín y no aviso","Trabajo de pie todo el día para no usar la silla"],"w":"Avisar una condición del puesto también es autocuidado."},{"q":"Sientes dolor de cuello a media mañana, pero quieres terminar un informe. ¿Qué decides?","o":["Hago la pausa ahora y ajusto mi puesto","Termino el informe y después descanso","Tomo un analgésico y sigo","Me masajeo el cuello sin dejar de escribir"],"w":"El dolor avisa: la pausa se hace ahora."}]}]},{"id":"oficina","sec":"admin","title":"Riesgos en la oficina","thumb":"of_intro","learn":[{"s":"of_intro","t":"La oficina también tiene riesgos","x":"En la oficina no hay grúas ni sierras, pero sí accidentes:<ul><li>Caídas por cables, cajones abiertos o pisos mojados.</li><li>Golpes por archivadores que se vuelcan.</li><li>Riesgo eléctrico e incendio por zapatillas sobrecargadas.</li><li>Caídas al subirse a una silla.</li><li>Accidentes en el trayecto de ida y vuelta al trabajo.</li></ul>Conocer estos riesgos es el primer paso para evitarlos."},{"s":"of_caidas","t":"Caídas al mismo nivel","x":"<ul><li><b>Cables</b> por el piso: ordénalos por la orilla o con canaletas.</li><li><b>Cajones</b> abiertos: ciérralos apenas los uses.</li><li>Alfombras levantadas, piso mojado o café derramado: <b>limpia, señaliza o avisa</b> de inmediato.</li><li>No camines leyendo el celular ni con cajas que te tapen la vista.</li><li>Usa los pasamanos en las escaleras.</li></ul>"},{"s":"of_cajones","t":"Archivadores","x":"<ul><li>Abre <b>un cajón a la vez</b>: con dos abiertos arriba, el peso se va hacia adelante y el mueble se puede volcar.</li><li>Pon lo <b>pesado en los cajones de abajo</b>.</li><li>Cierra cada cajón al terminar.</li><li>Si el mueble es alto, debe estar firme o anclado al muro: si se mueve, avisa.</li></ul>"},{"s":"of_electrico","t":"Riesgo eléctrico","x":"<ul><li><b>No conectes una zapatilla a otra</b> (en cadena).</li><li>No sobrecargues enchufes con estufas, hervidores y equipos a la vez.</li><li>Desenchufa tomando el enchufe, no tirando del cable.</li><li>Cable pelado, enchufe caliente u olor a quemado: <b>no lo uses y avisa</b>. Nunca le eches agua.</li><li>No intentes reparar instalaciones: lo hace un electricista autorizado.</li></ul>","k":"Sin zapatillas en cadena; lo dañado no se usa y se avisa."},{"s":"of_silla_mal","t":"La silla no es escalera","x":"Para alcanzar un archivo alto, <b>nunca te subas a una silla</b>, menos si tiene ruedas: se desliza o gira y la caída es casi segura. Tampoco a cajas ni a un escritorio. Usa una <b>escalera o un piso de altura adecuado</b>, o pide ayuda. Y deja lo de uso frecuente a una altura cómoda, entre la cintura y los hombros."},{"s":"of_orden","t":"Orden y aseo","x":"<ul><li>Nada de cajas ni archivos en el piso, en los pasillos ni frente a puertas.</li><li>Escritorio ordenado: menos cosas que caen o se derraman.</li><li>Café o agua derramada: límpiala de inmediato.</li><li>Tijeras y cartoneros, cerrados y guardados.</li><li>Lo que no sirve se retira, no se acumula.</li></ul>El orden es la medida de prevención más barata que existe."},{"s":"of_evac","t":"Emergencias y evacuación","x":"<ul><li>Conoce las <b>vías de evacuación</b> y la <b>zona de seguridad</b>.</li><li>Puertas, pasillos y extintores, siempre <b>despejados</b>.</li><li>En un sismo: <b>agáchate, cúbrete y afírmate</b>, lejos de ventanas y muebles altos.</li><li>Evacúa caminando cuando se indique, sin volver por tus cosas.</li><li>Números: <b>131</b> SAMU, <b>132</b> Bomberos, <b>133</b> Carabineros; ACHS <b>1404</b>.</li></ul>","k":"Conoce tu salida y mantenla despejada."},{"s":"of_trayecto","t":"Accidente de trayecto","x":"Es el que ocurre en el <b>trayecto directo, de ida o regreso</b>, entre tu casa y el trabajo (Ley 16.744, art. 5), y está cubierto. Si te desvías por un motivo personal, ese tramo puede no quedar cubierto. Si te pasa:<ul><li>Avisa a tu jefatura.</li><li>Atiéndete en la <b>ACHS</b>.</li><li>Guarda pruebas: parte o constancia de Carabineros, testigos u otros medios.</li></ul>"},{"s":"of_auto","t":"Autocuidado: \"es un segundo\"","x":"La mayoría de los accidentes se relacionan con una acción insegura. En la oficina, la típica es <b>\"es un segundo\"</b>: subirse a la silla, saltar el cable, dejar el cajón abierto. La decisión segura: <b>busca la escalera, ordena el cable, cierra el cajón</b>. Y si ves una condición insegura, corrígela si puedes o avísala: también es autocuidado."}],"quiz":[{"s":"of_silla_mal","v":[{"q":"¿Cuál es la forma correcta de alcanzar un archivo alto?","o":["Con una escalera o un piso de altura adecuado","Subiéndome a la silla con ruedas, con cuidado","Subiéndome al escritorio","Parándome sobre una caja de archivos firme y bien cerrada"],"w":"La silla con ruedas se desliza y gira."},{"q":"Un compañero se sube a su silla con ruedas para sacar una carpeta del estante. ¿Qué le dices?","o":["Que se baje: la silla puede girar o deslizarse","Que trabe las ruedas y siga","Que se afirme del estante","Que lo haga rápido, afirmándose del estante"],"w":"La silla no es escalera, menos con ruedas."},{"q":"¿Qué ayuda a no tener que subirse para alcanzar cosas?","o":["Dejar lo de uso frecuente a una altura cómoda","Poner todo en el estante más alto","Guardar archivos encima de los muebles","Apilar cajas cerca del estante para alcanzar sin escalera"],"w":"Lo que se usa seguido va entre la cintura y los hombros."}]},{"s":"of_electrico","v":[{"q":"Se puede conectar una zapatilla eléctrica a otra zapatilla si faltan enchufes.","vf":false,"w":"Falso. Las zapatillas en cadena se sobrecargan y pueden provocar un incendio."},{"q":"Faltan enchufes para el hervidor y la estufa. ¿Qué haces?","o":["Aviso para que se instalen enchufes adecuados","Conecto una zapatilla a otra","Uso un adaptador triple en la zapatilla","Conecto la estufa al alargador del computador"],"w":"La solución es una instalación adecuada, no sobrecargar."},{"q":"¿Cómo se desenchufa correctamente un equipo?","o":["Tomando el enchufe, no tirando del cable","Tirando del cable con fuerza","Moviendo el enchufe de lado a lado","Tirando del cable desde lejos, con un tirón firme y corto"],"w":"Tirar del cable lo daña y puede dejarlo pelado."}]},{"s":"of_cajones","v":[{"q":"¿Por qué conviene abrir un solo cajón del archivador a la vez?","o":["Porque con varios abiertos el mueble puede volcarse","Para que no se mezclen los papeles","Para que el cajón no se trabe","Porque así dura más el mueble y no se desgastan los rieles"],"w":"Con varios cajones abiertos arriba, el peso se va hacia adelante."},{"q":"¿Dónde guardas los archivos más pesados?","o":["En los cajones de abajo","En el cajón de arriba","Repartidos arriba para equilibrar","Encima del mueble"],"w":"Lo pesado abajo da estabilidad al mueble."},{"q":"Los objetos pesados deben ir en los cajones de abajo del archivador.","vf":true,"w":"Verdadero. Así el mueble no se vuelca hacia adelante."}]},{"s":"of_caidas","v":[{"q":"Un cable cruza el pasillo de la oficina. ¿Qué haces?","o":["Lo ordeno por la orilla o aviso para canalizarlo","Lo salto cada vez que paso","Le pongo una alfombra encima sin avisar","Lo dejo donde está, porque todos en la oficina ya saben que está ahí"],"w":"Los cables por el piso son una causa típica de caídas."},{"q":"Alguien derramó café en el pasillo. ¿Qué haces?","o":["Limpio de inmediato o señalizo y aviso","Lo esquivo y sigo","Le pongo un papel encima","Espero al personal de aseo sin señalizar"],"w":"El piso mojado se limpia o se señaliza de inmediato."},{"q":"¿Cuál de estas es una causa típica de caídas en la oficina?","o":["Un cajón abierto en el paso","Usar zapatos cerrados","Tener buena iluminación","Usar los pasamanos al subir y bajar escaleras"],"w":"Cajones abiertos y cables en el piso provocan tropiezos."}]},{"s":"of_electrico","v":[{"q":"Notas olor a quemado en un enchufe. ¿Qué haces?","o":["Dejo de usarlo y aviso de inmediato","Sigo trabajando y aviso al final","Le echo agua para enfriarlo","Lo desarmo con cuidado para revisar qué tiene"],"w":"Lo dañado no se usa y se avisa; nunca agua sobre electricidad."},{"q":"El cable del hervidor está pelado. ¿Qué haces?","o":["No lo uso y aviso","Lo envuelvo con cinta y lo uso","Lo uso sin tocar la parte pelada","Lo uso solo con las manos secas"],"w":"Un cable pelado puede electrocutar o iniciar un incendio."},{"q":"Un enchufe está caliente al tacto. ¿Qué significa?","o":["Posible falla: se deja de usar y se avisa","Que está funcionando bien","Que es normal en enchufes con mucho uso","Que el equipo conectado consume poca energía"],"w":"El calor en un enchufe indica sobrecarga o falla."}]},{"s":"of_evac","v":[{"q":"En un sismo, la conducta recomendada es:","o":["Agacharse, cubrirse y afirmarse","Correr por la escalera de inmediato","Pararse junto a la ventana","Salir a buscar el auto"],"w":"Lejos de ventanas y muebles altos."},{"q":"Suena la alarma de evacuación y tu celular quedó en otro escritorio. ¿Qué haces?","o":["Evacúo caminando sin volver por mis cosas","Voy a buscarlo rápido y salgo","Espero a ver si es simulacro","Salgo corriendo por el camino más corto que conozca"],"w":"Se evacúa caminando, sin volver por pertenencias."},{"q":"Durante un sismo estás junto a un ventanal. ¿Qué haces?","o":["Me alejo, me agacho, me cubro y me afirmo","Me quedo junto al ventanal para ver","Salgo corriendo durante el movimiento","Me paro bajo el marco de la ventana"],"w":"Los vidrios pueden quebrarse: aléjate y protégete."}]},{"s":"of_trayecto","v":[{"q":"Un accidente en el trayecto directo de tu casa al trabajo está cubierto por la Ley 16.744.","vf":true,"w":"Verdadero. El accidente de trayecto está definido en el art. 5 de la Ley 16.744."},{"q":"Sales del trabajo y te desvías a hacer un trámite personal. Tienes un accidente en ese desvío. ¿Qué puede pasar?","o":["Que no quede cubierto: no es el trayecto directo","Queda cubierto igual, porque salías del trabajo","Lo cubre siempre la empresa","Solo queda cubierto si fue en la mañana, camino al trabajo"],"w":"La cobertura es para el trayecto directo casa-trabajo."},{"q":"¿Qué ley define y cubre el accidente de trayecto?","o":["Ley 16.744","Ley 20.949","Ley 21.643","Ley 18.290"],"w":"La Ley 16.744 cubre accidentes del trabajo y de trayecto."}]},{"s":"of_trayecto","v":[{"q":"Si sufres un accidente de trayecto, ¿qué te sirve como prueba?","o":["Parte o constancia de Carabineros, testigos u otros medios","Solo tu palabra, sin nada más","Solo una publicación en redes sociales","Un certificado de la junta de vecinos del lugar del accidente"],"w":"Avisa, atiéndete en la ACHS y guarda pruebas."},{"q":"Tuviste un choque menor camino al trabajo y te duele el cuello. ¿Qué haces?","o":["Aviso a mi jefatura y me atiendo en la ACHS","Me voy a la casa y espero que se pase","Voy al consultorio y no aviso","Trabajo igual y aviso solo si el dolor empeora en los próximos días"],"w":"El accidente de trayecto se avisa y se atiende en la ACHS."},{"q":"¿Dónde te atiendes si tienes un accidente de trayecto?","o":["En la ACHS","En cualquier clínica, pagando yo","En el consultorio, con mi previsión de salud","En ninguna parte: no tiene cobertura"],"w":"La ACHS atiende el accidente de trayecto sin costo para ti."}]},{"s":"exitBlocked","v":[{"q":"Hay cajas apiladas frente a la puerta de salida. Eso es:","o":["Una condición insegura que se ordena o se avisa","Algo aceptable si es por pocos días","Un problema solo de aseo","Correcto si las cajas son livianas y se pueden mover rápido"],"w":"Salidas y pasillos siempre despejados."},{"q":"¿Por qué la salida de emergencia debe estar siempre despejada?","o":["Para evacuar rápido y sin obstáculos","Solo para que la oficina se vea ordenada","Porque lo exige el arrendador","Para que entre más luz"],"w":"En una emergencia cada segundo cuenta."},{"q":"Dejar cajas frente a la salida es aceptable si es solo por un día.","vf":false,"w":"Falso. Una emergencia puede ocurrir justo ese día."}]},{"s":"of_auto","v":[{"q":"¿Cuál es el acto inseguro más típico en la oficina?","o":["\"Es un segundo\": subirse a la silla","Buscar la escalera para alcanzar algo","Ordenar los cables por la orilla","Cerrar los cajones después de usarlos, uno por uno"],"w":"Un segundo de apuro puede costar meses de recuperación."},{"q":"Necesitas una carpeta del estante alto y la escalera está en otra sala. ¿Qué decides?","o":["Voy a buscar la escalera","Me subo a la silla, es un segundo","Me paro en el escritorio","Pido que me sujeten la silla"],"w":"Se busca el equipo correcto en vez de improvisar."},{"q":"Ves un cajón abierto en el paso, en el escritorio de un compañero que salió. ¿Qué haces?","o":["Lo cierro: corregir una condición insegura es autocuidado","Lo dejo, no es mi escritorio","Lo esquivo cada vez que paso","Le dejo una nota en el escritorio para que lo cierre mañana"],"w":"Corregir o avisar las condiciones inseguras protege a todos."}]}]}]});
